INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('70f993e7-b737-51e0-b6c2-f9d0534ae2d8', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 7, 7, 'A red laser pointer emits light of wavelength 650 nm. Calculate the energy carried by one of its photons, in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.06', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 650 × 10⁻⁹ = 3.06 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: E = hc/λ. A1: E = 3.06 × 10⁻¹⁹ J.', 2, NULL, NULL),
('01b94d5a-3c8a-52e2-a79a-5681a7e3dab8', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 8, 8, 'Which observation is evidence that light behaves as a stream of particles?', NULL, 1, 'multiple_choice'::answer_type, 'The photoelectric effect', NULL, false, NULL, false, NULL, 'Photoelectric emission shows light delivers energy in individual quanta. Mark scheme (1 mark). B1: C (The photoelectric effect).', 1, NULL, NULL),
('7838c54b-42e9-5637-92e4-80700ffb53ce', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 9, 9, 'A photon of violet light has a frequency of 7.3 × 10¹⁴ Hz. Calculate the photon energy in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '4.84', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 7.3 × 10¹⁴ = 4.84 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: E = hf. A1: E = 4.8 × 10⁻¹⁹ J.', 2, NULL, NULL),
('9eb5377e-8048-54a0-aabf-f0c9fec43494', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 10, 10, 'A beam of electrons passes through a thin layer of graphite and forms rings on a screen. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons can behave as waves', NULL, false, NULL, false, NULL, 'The rings are a diffraction pattern, a wave effect. Mark scheme (1 mark). B1: A (Electrons can behave as waves).', 1, NULL, NULL),
('94a89604-f9f1-5303-b853-d288766de960', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 11, 11, 'A proton travels at 2.0 × 10⁵ m s⁻¹. Calculate its de Broglie wavelength in units of 10⁻¹² m. Take h = 6.63 × 10⁻³⁴ J s and mₚ = 1.67 × 10⁻²⁷ kg.', NULL, 1, 'numeric'::answer_type, '1.985', '10⁻¹² m', false, NULL, false, NULL, 'λ = h/mv = 6.63 × 10⁻³⁴ ÷ (1.67 × 10⁻²⁷ × 2.0 × 10⁵) = 1.99 × 10⁻¹² m. Mark scheme (2 marks). C1: λ = h/p. A1: λ = 1.99 × 10⁻¹² m.', 2, NULL, NULL),
('5dbd285a-fda4-50b4-a0b8-5a1644b8d691', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 12, 12, 'The energy of a single photon is directly proportional to which quantity?', NULL, 1, 'multiple_choice'::answer_type, 'The frequency of the radiation', NULL, false, NULL, false, NULL, 'E = hf, so doubling the frequency doubles the energy of each photon. Mark scheme (1 mark). B1: D (The frequency of the radiation).', 1, NULL, NULL),
('413e25b0-bd2a-541f-9283-72ad9a3be6a2', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 13, 13, 'A photon carries 3.0 × 10⁻¹⁹ J. Express this energy in electronvolts (eV). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.875', 'eV', false, NULL, false, NULL, 'E = 3.0 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 1.88 eV. Mark scheme (1 mark). A1: E = 1.88 eV.', 1, NULL, NULL),
('f56caacf-2340-5f62-b6f9-46bc3f1903bb', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 14, 14, 'Which experiment is usually quoted as evidence that light is a wave?', NULL, 1, 'multiple_choice'::answer_type, 'Young''s double-slit experiment', NULL, false, NULL, false, NULL, 'Interference fringes need superposition of waves. Mark scheme (1 mark). B1: B (Young''s double-slit experiment).', 1, NULL, NULL),
('53f66960-5139-5111-87d5-01bb1f9d7da8', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 15, 15, 'Electrons in a diffraction tube have a de Broglie wavelength of 0.15 nm. Calculate their momentum in units of 10⁻²⁴ kg m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '4.42', '10⁻²⁴ kg m s⁻¹', false, NULL, false, NULL, 'p = h/λ = 6.63 × 10⁻³⁴ ÷ 0.15 × 10⁻⁹ = 4.42 × 10⁻²⁴ kg m s⁻¹. Mark scheme (2 marks). C1: p = h/λ. A1: p = 4.42 × 10⁻²⁴ kg m s⁻¹.', 2, NULL, NULL),
('18b988e2-d932-5fc9-889e-ec9c1646d3a4', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 16, 16, 'Which description fits the particle model of light?', NULL, 1, 'multiple_choice'::answer_type, 'Energy arrives in discrete packets, each absorbed at one point', NULL, false, NULL, false, NULL, 'Photons are localised quanta of energy. Mark scheme (1 mark). B1: C (Energy arrives in discrete packets, each absorbed at one point).', 1, NULL, NULL),
('1022d7ea-2746-5d40-8183-6f4a50c25b00', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 17, 17, 'Green light from a mercury lamp has photons of energy 2.27 eV. Calculate the energy of each photon in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.632', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = 2.27 × 1.60 × 10⁻¹⁹ = 3.63 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: 1 eV = 1.60 × 10⁻¹⁹ J. A1: E = 3.63 × 10⁻¹⁹ J.', 2, NULL, NULL),
('68f72605-c62f-5040-9623-0d06f8cdd171', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 18, 18, 'What is meant by a quantum of energy?', NULL, 1, 'multiple_choice'::answer_type, 'The smallest discrete amount of energy that can be transferred in a process', NULL, false, NULL, false, NULL, 'Energy in electromagnetic radiation is transferred in whole numbers of quanta (photons). Mark scheme (1 mark). B1: A (The smallest discrete amount of energy that can be transferred in a process).', 1, NULL, NULL),
('09fb8adc-0181-5be7-954d-febc5f6e1b99', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 19, 19, 'An ultraviolet photon has an energy of 6.6 × 10⁻¹⁹ J. Calculate its wavelength. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.014e-7', 'm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 6.6 × 10⁻¹⁹ = 3.01 × 10⁻⁷ m. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 3.01 × 10⁻⁷ m.', 2, NULL, NULL),
('0c88f9d0-5b41-5c96-8dd9-44b70a9c7c94', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 20, 20, 'For electrons to be diffracted noticeably by a crystal, how must their de Broglie wavelength compare with the spacing of the atoms?', NULL, 1, 'multiple_choice'::answer_type, 'It must be of a similar size', NULL, false, NULL, false, NULL, 'Diffraction is most marked when the wavelength is similar to the gap size. Mark scheme (1 mark). B1: D (It must be of a similar size).', 1, NULL, NULL),
('dbf41f71-d7b3-5751-9def-d69586063569', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 21, 21, 'A neutron (mass 1.67 × 10⁻²⁷ kg) leaves a reactor at 2200 m s⁻¹. Calculate its de Broglie wavelength. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.805e-10', 'm', false, NULL, false, NULL, 'λ = h/mv = 6.63 × 10⁻³⁴ ÷ (1.67 × 10⁻²⁷ × 2200) = 1.80 × 10⁻¹⁰ m. Mark scheme (2 marks). C1: λ = h/mv. A1: λ = 1.80 × 10⁻¹⁰ m.', 2, NULL, NULL),
('7a45ecd8-737f-5dcc-b65d-4969640cf42b', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 22, 22, 'Which statement about a photon is correct?', NULL, 1, 'multiple_choice'::answer_type, 'It travels at the speed of light and has no rest mass', NULL, false, NULL, false, NULL, 'Photons are massless quanta of electromagnetic radiation. Mark scheme (1 mark). B1: B (It travels at the speed of light and has no rest mass).', 1, NULL, NULL),
('20f1533c-0542-57cd-ac66-a8aed7587602', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 23, 23, 'A laser emits 4.0 × 10¹⁶ photons each second, each of energy 3.1 × 10⁻¹⁹ J. Calculate its output power.', NULL, 1, 'numeric'::answer_type, '0.0124', 'W', false, 0.05, false, NULL, 'P = nE = 4.0 × 10¹⁶ × 3.1 × 10⁻¹⁹ = 0.0124 W. Mark scheme (2 marks). C1: P = (photons per second) × E. A1: P = 0.012 W.', 2, NULL, NULL),
('e2399b3c-9275-58e1-91fd-8eed0bfc0756', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 24, 24, 'A helium–neon laser of output power 0.50 mW emits light of wavelength 633 nm. Calculate the number of photons it emits each second. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.591e15', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 633 × 10⁻⁹ = 3.142 × 10⁻¹⁹ J. n = 0.50 × 10⁻³ ÷ 3.142 × 10⁻¹⁹ = 1.59 × 10¹⁵. Mark scheme (3 marks). C1: E = hc/λ. C1: n = P/E. A1: n = 1.59 × 10¹⁵.', 3, NULL, NULL),
('3680b815-3c58-58c2-95a6-71cfb6fb2410', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 25, 25, 'An electron is accelerated from rest through a potential difference of 50 V. Calculate its de Broglie wavelength. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.737e-10', 'm', false, NULL, false, NULL, 'Ek = eV = 1.60 × 10⁻¹⁹ × 50 = 8.0 × 10⁻¹⁸ J. p = √(2mEk) = √(2 × 9.11 × 10⁻³¹ × 8.0 × 10⁻¹⁸) = 3.818 × 10⁻²⁴ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 3.818 × 10⁻²⁴ = 1.74 × 10⁻¹⁰ m. Mark scheme (4 marks). C1: Ek = eV. C1: p = √(2mEk). C1: λ = h/p. A1: λ = 1.74 × 10⁻¹⁰ m.', 4, NULL, NULL),
('04b17875-9183-54cb-b93a-43b677c7f02e', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 26, 26, 'An electron and a proton have the same de Broglie wavelength. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'They have the same momentum', NULL, false, NULL, false, NULL, 'λ = h/p, so equal λ means equal p; the proton is slower and has less kinetic energy. Mark scheme (3 marks). C1: λ = h/p. C1: equal λ ⇒ equal p. A1: C (They have the same momentum).', 3, NULL, NULL),
('1dca8fca-f493-59b4-b769-6a3ad37a65be', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 27, 27, 'A blue line in the spectrum of hydrogen has wavelength 410 nm. Calculate the photon energy in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.032', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 410 × 10⁻⁹ = 4.851 × 10⁻¹⁹ J. In eV: 4.851 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 3.03 eV. Mark scheme (3 marks). C1: E = hc/λ. C1: ÷ e. A1: E = 3.03 eV.', 3, NULL, NULL),
('29d41a4d-8212-5059-a0e1-dd995df6a19a', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 28, 28, 'Electrons have a de Broglie wavelength of 0.20 nm. Calculate their kinetic energy in eV. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '37.7', 'eV', false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 0.20 × 10⁻⁹ = 3.315 × 10⁻²⁴ kg m s⁻¹. Ek = p²/2m = (3.315 × 10⁻²⁴)² ÷ (2 × 9.11 × 10⁻³¹) = 6.031 × 10⁻¹⁸ J. In eV: 6.031 × 10⁻¹⁸ ÷ 1.60 × 10⁻¹⁹ = 37.7 eV. Mark scheme (4 marks). C1: p = h/λ. C1: Ek = p²/2m. C1: ÷ e. A1: Ek = 37.7 eV.', 4, NULL, NULL),
('706ce56e-8430-5e4a-88ae-682e2f88a552', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 29, 29, 'Why is the wave model of light unable to explain the photoelectric effect?', NULL, 2, 'multiple_choice'::answer_type, 'A wave would deliver energy continuously, so even dim light of any frequency should eventually release electrons', NULL, false, NULL, false, NULL, 'Emission depends on frequency, not intensity, and is instant: energy arrives in photons. Mark scheme (3 marks). C1: wave energy spread and continuous. C1: threshold frequency observed. A1: A (A wave would deliver energy continuously, so even dim light of any frequency should eventually release electrons).', 3, NULL, NULL),
('cbc4e492-cda6-5fe0-95aa-88346a6829ff', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 30, 30, 'Calculate (energy of a photon of blue light, 450 nm) ÷ (energy of a photon of red light, 700 nm).', NULL, 2, 'numeric'::answer_type, '1.556', NULL, false, NULL, false, NULL, 'E ∝ 1/λ, so ratio = 700 ÷ 450 = 1.56. Mark scheme (3 marks). C1: E = hc/λ. C1: ratio of wavelengths inverted. A1: ratio = 1.56.', 3, NULL, NULL),
('efba5f9c-054f-5e4d-9ade-82bd715767ff', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 31, 31, 'In an electron diffraction tube the electrons have a de Broglie wavelength of 5.0 × 10⁻¹¹ m. Calculate the speed of the electrons. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '1.456e7', 'm s⁻¹', false, NULL, false, NULL, 'v = h/mλ = 6.63 × 10⁻³⁴ ÷ (9.11 × 10⁻³¹ × 5.0 × 10⁻¹¹) = 1.46 × 10⁷ m s⁻¹. Mark scheme (3 marks). C1: λ = h/mv. C1: rearranged. A1: v = 1.46 × 10⁷ m s⁻¹.', 3, NULL, NULL),
('d5cbfb5b-ac3f-52da-90ff-27246c56b9a6', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 32, 32, 'In the photon model, what determines the intensity of a beam of monochromatic light?', NULL, 2, 'multiple_choice'::answer_type, 'The number of photons arriving per second per unit area', NULL, false, NULL, false, NULL, 'For fixed frequency, each photon has the same energy, so intensity ∝ photon flux. Mark scheme (3 marks). C1: photon energy fixed by f. C1: intensity ∝ number per second per area. A1: D (The number of photons arriving per second per unit area).', 3, NULL, NULL),
('618ca9e9-c0b1-5557-b1ae-b34a37835abf', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 33, 33, 'Light of wavelength 550 nm and intensity 2.0 W m⁻² falls on a detector of area 1.0 × 10⁻⁴ m². How many photons reach the detector each second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '5.53e14', NULL, false, NULL, false, NULL, 'P = IA = 2.0 × 1.0 × 10⁻⁴ = 2.0 × 10⁻⁴ W. E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 550 × 10⁻⁹ = 3.616 × 10⁻¹⁹ J. n = 2.0 × 10⁻⁴ ÷ 3.616 × 10⁻¹⁹ = 5.53 × 10¹⁴. Mark scheme (4 marks). C1: P = IA. C1: photon energy. C1: n = P/E. A1: n = 5.53 × 10¹⁴.', 4, NULL, NULL),
('70824ee2-52b0-512b-9f32-e3970e1d0e0f', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 34, 34, 'The accelerating voltage in an electron diffraction tube is increased. What happens to the rings on the screen?', NULL, 2, 'multiple_choice'::answer_type, 'They get smaller because the electrons'' de Broglie wavelength decreases', NULL, false, NULL, false, NULL, 'Higher p.d. gives larger momentum and λ = h/p is smaller, so the diffraction angle is smaller. Mark scheme (3 marks). C1: momentum increases. C1: λ decreases so angles smaller. A1: B (They get smaller because the electrons'' de Broglie wavelength decreases).', 3, NULL, NULL),
('a0b169af-aa3b-5125-ad3f-e1bf07d96bfb', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 35, 35, 'An α-particle (mass 6.64 × 10⁻²⁷ kg) moves at 1.5 × 10⁷ m s⁻¹. Calculate its de Broglie wavelength in units of 10⁻¹⁵ m. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '6.657', '10⁻¹⁵ m', false, NULL, false, NULL, 'λ = h/mv = 6.63 × 10⁻³⁴ ÷ (6.64 × 10⁻²⁷ × 1.5 × 10⁷) = 6.66 × 10⁻¹⁵ m. Mark scheme (3 marks). C1: p = mv. C1: λ = h/p. A1: λ = 6.66 × 10⁻¹⁵ m.', 3, NULL, NULL),
('3b93e456-772f-551e-b46d-d77f2621d348', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 36, 36, 'A green laser has wavelength 532 nm. Calculate the momentum of one of its photons in units of 10⁻²⁷ kg m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '1.246', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'p = h/λ = 6.63 × 10⁻³⁴ ÷ 532 × 10⁻⁹ = 1.25 × 10⁻²⁷ kg m s⁻¹. Mark scheme (3 marks). C1: p = h/λ. C1: nm to m. A1: p = 1.25 × 10⁻²⁷ kg m s⁻¹.', 3, NULL, NULL),
('f2507641-9e59-5f53-8a62-87082b97d479', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 37, 37, 'An X-ray photon and an electron both have a wavelength of 0.10 nm. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'The photon has much more energy than the electron', NULL, false, NULL, false, NULL, 'Both have p = h/λ. The photon energy is pc ≈ 12 keV; the electron energy is p²/2m ≈ 150 eV. Mark scheme (4 marks). C1: equal momenta. C1: photon E = pc. C1: electron E = p²/2m much smaller. A1: C (The photon has much more energy than the electron).', 4, NULL, NULL),
('54f3d84d-dd3d-5923-9b75-a10b9c2a2e7c', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 38, 38, 'An electron moves at 1.0 × 10⁶ m s⁻¹. Calculate the wavelength of a photon that has the same momentum as the electron. Give your answer in nm. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '0.7278 nm', 'nm', false, NULL, false, NULL, 'p = 9.11 × 10⁻³¹ × 1.0 × 10⁶ = 9.11 × 10⁻²⁵ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 9.11 × 10⁻²⁵ = 7.278 × 10⁻¹⁰ m. In nm: 7.278 × 10⁻¹⁰ × 10⁹ = 0.728. Mark scheme (4 marks). C1: p = mv. C1: λ = h/p. C1: convert to nm. A1: λ = 0.728 nm.', 4, NULL, NULL),
('cf0a577b-5ff0-5116-9272-4432ff5fb5b5', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 39, 39, 'Why is no diffraction seen when a cricket ball is thrown through a doorway?', NULL, 2, 'multiple_choice'::answer_type, 'Its de Broglie wavelength is far smaller than the width of the doorway', NULL, false, NULL, false, NULL, 'λ = h/mv ≈ 10⁻³⁴ m for a ball, far too small to diffract. Mark scheme (3 marks). C1: λ = h/mv tiny. C1: compare with gap. A1: A (Its de Broglie wavelength is far smaller than the width of the doorway).', 3, NULL, NULL),
('2708ed90-8b7c-5765-bbd6-e32b1a860f87', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 40, 40, 'An infrared laser of wavelength 1064 nm has an output of 1.0 W. How many photons does it emit per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '5.349e18', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1064 × 10⁻⁹ = 1.869 × 10⁻¹⁹ J. n = 1.0 ÷ 1.869 × 10⁻¹⁹ = 5.35 × 10¹⁸. Mark scheme (3 marks). C1: photon energy. C1: n = P/E. A1: n = 5.35 × 10¹⁸.', 3, NULL, NULL),
('f880783f-5e4a-5749-9a0a-0786cbd9234e', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 41, 41, 'Which pair of observations supports wave–particle duality for electrons?', NULL, 2, 'multiple_choice'::answer_type, 'Electrons are deflected by fields as charged particles, and they form diffraction patterns', NULL, false, NULL, false, NULL, 'Deflection shows particle behaviour; diffraction shows wave behaviour. Mark scheme (3 marks). C1: particle evidence. C1: wave evidence. A1: D (Electrons are deflected by fields as charged particles, and they form diffraction patterns).', 3, NULL, NULL),
('68699b77-3391-5115-a250-d60839fb0666', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 42, 42, 'A radio station broadcasts at 98 MHz. Calculate the energy of one of its photons in units of 10⁻²⁶ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '6.497', '10⁻²⁶ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 98 × 10⁶ = 6.50 × 10⁻²⁶ J. Mark scheme (3 marks). C1: E = hf. C1: MHz to Hz. A1: E = 6.5 × 10⁻²⁶ J.', 3, NULL, NULL),
('a868bf14-09da-5134-b3fd-fcb246ba86b3', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 43, 43, 'Electrons are accelerated from rest through 150 V and directed at a crystal whose atomic planes are 2.1 × 10⁻¹⁰ m apart. (a) Calculate the kinetic energy of each electron in joules. (b) Calculate the momentum. (c) Calculate the de Broglie wavelength. (d) State whether noticeable diffraction is expected. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.003e-10', 'm', false, NULL, false, NULL, '(a) Ek = 1.60 × 10⁻¹⁹ × 150 = 2.4 × 10⁻¹⁷ J. (b) p = √(2 × 9.11 × 10⁻³¹ × 2.4 × 10⁻¹⁷) = 6.613 × 10⁻²⁴ kg m s⁻¹. (c) λ = 6.63 × 10⁻³⁴ ÷ 6.613 × 10⁻²⁴ = 1.00 × 10⁻¹⁰ m. (d) Yes: λ is similar to the plane spacing. Mark scheme (5 marks). C1: Ek = eV. C1: p = √(2mEk). C1: λ = h/p. B1: comparison with spacing. A1: λ = 1.00 × 10⁻¹⁰ m.', 5, NULL, NULL),
('3c044832-7b0b-513d-9e86-9c0f55f393d5', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 44, 44, 'A 5.0 mW laser emits light of wavelength 405 nm. All the light is absorbed by a small black card. (a) Calculate the photon energy. (b) Calculate the number of photons absorbed per second. (c) Calculate the momentum of one photon. (d) Calculate the force on the card. Give only the answer to (d), in units of 10⁻¹¹ N. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '1.667', '10⁻¹¹ N', false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 405 × 10⁻⁹ = 4.911 × 10⁻¹⁹ J. (b) n = 5.0 × 10⁻³ ÷ 4.911 × 10⁻¹⁹ = 1.018 × 10¹⁶ s⁻¹. (c) p = 6.63 × 10⁻³⁴ ÷ 405 × 10⁻⁹ = 1.637 × 10⁻²⁷ kg m s⁻¹. (d) F = np = 1.018 × 10¹⁶ × 1.637 × 10⁻²⁷ = 1.67 × 10⁻¹¹ N. Mark scheme (6 marks). C1: photon energy. C1: photon rate. C1: photon momentum. M1: F = rate of change of momentum. C1: value. A1: F = 1.67 × 10⁻¹¹ N.', 6, NULL, NULL),
('e5fb1dc3-8c7d-56f0-8b3e-689cdf058666', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 45, 45, 'An electron and a photon each have an energy of 2.0 keV. (a) Calculate the wavelength of the photon. (b) Calculate the momentum of the electron. (c) Calculate the de Broglie wavelength of the electron. (d) Calculate (photon wavelength) ÷ (electron wavelength). Give only the answer to (d). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '22.64', NULL, false, NULL, false, NULL, 'E = 2000 × 1.60 × 10⁻¹⁹ = 3.2 × 10⁻¹⁶ J. (a) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 3.2 × 10⁻¹⁶ = 6.216 × 10⁻¹⁰ m. (b) p = √(2 × 9.11 × 10⁻³¹ × 3.2 × 10⁻¹⁶) = 2.415 × 10⁻²³ kg m s⁻¹. (c) λₑ = 6.63 × 10⁻³⁴ ÷ 2.415 × 10⁻²³ = 2.746 × 10⁻¹¹ m. (d) 6.216 × 10⁻¹⁰ ÷ 2.746 × 10⁻¹¹ = 22.6. Mark scheme (6 marks). C1: keV to J. C1: photon λ = hc/E. C1: electron p = √(2mE). C1: λₑ = h/p. C1: ratio. A1: ratio = 22.6.', 6, NULL, NULL),
('a19295f3-dc62-51a9-b84b-074678c723d3', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 46, 46, 'Sunlight of intensity 1000 W m⁻² falls on a solar cell of area 0.020 m². Treat the light as photons of mean wavelength 550 nm. (a) Calculate the power reaching the cell. (b) Calculate the energy of one photon. (c) Calculate the number of photons reaching the cell per second. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.53e19', NULL, false, NULL, false, NULL, '(a) P = 1000 × 0.020 = 20 W. (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 550 × 10⁻⁹ = 3.616 × 10⁻¹⁹ J. (c) n = 20 ÷ 3.616 × 10⁻¹⁹ = 5.53 × 10¹⁹. Mark scheme (5 marks). C1: P = IA. C1: photon energy. M1: n = P/E. B1: mean wavelength assumption. A1: n = 5.53 × 10¹⁹.', 5, NULL, NULL),
('c55d05e5-b2e3-5196-96bc-3231e2f645a6', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 47, 47, 'A very dim beam of light of wavelength 600 nm and power 1.0 × 10⁻¹⁶ W passes through a double slit to a detector 1.2 m away. (a) Calculate the number of photons per second. (b) Calculate the mean distance between successive photons along the beam. (c) Explain why an interference pattern still builds up. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '9.945e5', 'm', false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 600 × 10⁻⁹ = 3.315 × 10⁻¹⁹ J, so n = 1.0 × 10⁻¹⁶ ÷ 3.315 × 10⁻¹⁹ = 301.7 s⁻¹. (b) Spacing = c/n = 3.00 × 10⁸ ÷ 301.7 = 9.94 × 10⁵ m. (c) The photons pass the slits one at a time, yet each arrives with the probability given by the wave pattern. Mark scheme (5 marks). C1: photon rate. M1: spacing = c ÷ rate. C1: value. B1: one photon at a time; wave gives probability. A1: spacing = 9.94 × 10⁵ m.', 5, NULL, NULL),
('ebfc27bf-2ae7-5f19-9468-42250e456667', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 48, 48, 'A beam of neutrons is to be diffracted by a crystal, so the neutrons need a de Broglie wavelength of 0.18 nm. A neutron has mass 1.67 × 10⁻²⁷ kg. (a) Calculate the momentum required. (b) Calculate the speed. (c) Calculate the kinetic energy in eV. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.02539', 'eV', false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 0.18 × 10⁻⁹ = 3.683 × 10⁻²⁴ kg m s⁻¹. (b) v = 3.683 × 10⁻²⁴ ÷ 1.67 × 10⁻²⁷ = 2206 m s⁻¹. (c) Ek = p²/2m = (3.683 × 10⁻²⁴)² ÷ (2 × 1.67 × 10⁻²⁷) = 4.062 × 10⁻²¹ J. In eV: 4.062 × 10⁻²¹ ÷ 1.60 × 10⁻¹⁹ = 0.0254 eV. Mark scheme (6 marks). C1: p = h/λ. C1: v = p/m. C1: Ek = p²/2m. C1: J to eV. B1: slow (thermal) neutrons suffice. A1: Ek = 0.0254 eV.', 6, NULL, NULL),
('fa8e475c-20d4-52fd-b526-ebc98df435d5', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 49, 49, 'A camera flash releases 2.0 J of light energy in 1.0 ms. Treat the light as photons of wavelength 500 nm. (a) Calculate the mean power of the flash. (b) Calculate the photon energy. (c) Calculate the number of photons emitted. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.028e18', NULL, false, NULL, false, NULL, '(a) P = 2.0 ÷ 1.0 × 10⁻³ = 2000 W. (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 500 × 10⁻⁹ = 3.978 × 10⁻¹⁹ J. (c) N = 2.0 ÷ 3.978 × 10⁻¹⁹ = 5.03 × 10¹⁸. Mark scheme (5 marks). C1: P = E/t. C1: photon energy. M1: N = total energy ÷ photon energy. B1: single wavelength assumed. A1: N = 5.03 × 10¹⁸.', 5, NULL, NULL),
('72d751e7-da5b-52f8-94ba-d351fae8e562', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 50, 50, 'Radio waves of 100 MHz and X-rays of 3.0 × 10¹⁸ Hz are both electromagnetic. (a) Calculate the photon energy of each. (b) Calculate (X-ray photon energy) ÷ (radio photon energy). (c) Explain why the particle nature is obvious for X-rays but not for radio waves. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s.', NULL, 3, 'numeric'::answer_type, '3e10', NULL, false, NULL, false, NULL, '(a) Radio: 6.63 × 10⁻³⁴ × 100 × 10⁶ = 6.63 × 10⁻²⁶ J; X-ray: 6.63 × 10⁻³⁴ × 3.0 × 10¹⁸ = 1.99 × 10⁻¹⁵ J. (b) Ratio = 3.0 × 10¹⁸ ÷ 100 × 10⁶ = 3.00 × 10¹⁰. (c) A radio signal contains enormous numbers of tiny quanta, so it seems continuous; one X-ray photon can ionise an atom. Mark scheme (6 marks). C1: radio E. C1: X-ray E. C1: ratio = ratio of frequencies. B1: many small quanta. B1: single X-ray photon detectable. A1: ratio = 3.0 × 10¹⁰.', 6, NULL, NULL),
('1844c863-4368-5d92-915f-4db77716b4e9', '7d22edfc-44c4-4846-9769-292936cb7827', 'ddd29c21-5c10-43b3-8daf-432cc4c86b34', 'a-level', '28.1', '9702 coursebook 28.1 · Modelling with particles and waves', 51, 51, 'A beam of electrons and a beam of red light (650 nm) are to give the same diffraction pattern with a given grating, so they must have the same wavelength. (a) Calculate the momentum the electrons need. (b) Calculate their speed. (c) Calculate the accelerating p.d. needed, starting from rest. Give only the answer to (c), in units of 10⁻⁶ V. Take h = 6.63 × 10⁻³⁴ J s, mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3.569', '10⁻⁶ V', false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 650 × 10⁻⁹ = 1.020 × 10⁻²⁷ kg m s⁻¹. (b) v = 1.020 × 10⁻²⁷ ÷ 9.11 × 10⁻³¹ = 1120 m s⁻¹. (c) V = p²/(2me) = (1.020 × 10⁻²⁷)² ÷ (2 × 9.11 × 10⁻³¹ × 1.60 × 10⁻¹⁹) = 3.57 × 10⁻⁶ V. Mark scheme (5 marks). C1: p = h/λ. C1: v = p/m. M1: eV = p²/2m. C1: value. A1: V = 3.57 × 10⁻⁶ V.', 5, NULL, NULL)
