('9094e01c-035a-5790-8fd4-9d9c9a0a2f8a', '9eb5377e-8048-54a0-aabf-f0c9fec43494', 'Graphite emits light when struck', 'D', false, 3),
('52f3e6b0-1d98-5acc-94fb-e17226669584', '5dbd285a-fda4-50b4-a0b8-5a1644b8d691', 'The wavelength of the radiation', 'A', false, 0),
