('f0bb1b9f-59ab-50d2-94b4-81a35d9d81af', '5dbd285a-fda4-50b4-a0b8-5a1644b8d691', 'The amplitude of the wave', 'C', false, 2),
('9b6d71f1-3e7f-5cbf-8329-981dc8272531', '5dbd285a-fda4-50b4-a0b8-5a1644b8d691', 'The frequency of the radiation', 'D', true, 3),
('c1cfa997-3482-5d23-bba1-f47f6b349b4b', 'f56caacf-2340-5f62-b6f9-46bc3f1903bb', 'The photoelectric effect', 'A', false, 0),
('8a477aef-296a-5c60-a9f8-47ebac0e2702', 'f56caacf-2340-5f62-b6f9-46bc3f1903bb', 'Young''s double-slit experiment', 'B', true, 1),
('6869814a-6773-5121-b424-9561ff411b26', 'f56caacf-2340-5f62-b6f9-46bc3f1903bb', 'Line emission spectra', 'C', false, 2),
('aa9232b0-13ae-53ce-808b-83d38c443118', 'f56caacf-2340-5f62-b6f9-46bc3f1903bb', 'The emission of electrons from a hot filament', 'D', false, 3),
('143c31b4-d696-5fe1-a900-9522afd674a6', '18b988e2-d932-5fc9-889e-ec9c1646d3a4', 'Energy spreads out evenly over the whole wavefront', 'A', false, 0),
('e0c7f5e7-6da2-5c38-bf5a-478648ddc974', '18b988e2-d932-5fc9-889e-ec9c1646d3a4', 'Light bends round obstacles', 'B', false, 1),
('2a5433c6-a64f-5a9c-9b4b-5dea3df48d9b', '18b988e2-d932-5fc9-889e-ec9c1646d3a4', 'Energy arrives in discrete packets, each absorbed at one point', 'C', true, 2),
('28832130-67e4-5450-b1f1-06fe49df1329', '18b988e2-d932-5fc9-889e-ec9c1646d3a4', 'Two beams can cancel to give darkness', 'D', false, 3),
('dd3d7430-a73a-51d5-a589-1d936959e822', '68f72605-c62f-5040-9623-0d06f8cdd171', 'The smallest discrete amount of energy that can be transferred in a process', 'A', true, 0),
('2a9cfded-84cb-514d-8900-f7de73f76407', '68f72605-c62f-5040-9623-0d06f8cdd171', 'Any very small amount of energy', 'B', false, 1),
('63a23b85-514c-5b3b-ae20-df180957bcc2', '68f72605-c62f-5040-9623-0d06f8cdd171', 'The energy of one mole of photons', 'C', false, 2),
('f584052e-d3ef-5b8c-b0d0-4e99a1623be3', '68f72605-c62f-5040-9623-0d06f8cdd171', 'The energy needed to remove an electron from a metal', 'D', false, 3),
('74fa0d11-f39e-5e1b-801b-83f379495e4c', '0c88f9d0-5b41-5c96-8dd9-44b70a9c7c94', 'It must be much larger', 'A', false, 0),
('4364af18-e9d7-5218-bf11-80faf8b61329', '0c88f9d0-5b41-5c96-8dd9-44b70a9c7c94', 'It must be much smaller', 'B', false, 1),
('eaa7499a-3aac-51b4-a4cf-8e97b64ccd64', '0c88f9d0-5b41-5c96-8dd9-44b70a9c7c94', 'It makes no difference', 'C', false, 2),
('58b14c8b-6253-53b1-b45c-7e5e03a95142', '0c88f9d0-5b41-5c96-8dd9-44b70a9c7c94', 'It must be of a similar size', 'D', true, 3),
('741d48c9-f084-57ae-acb5-5d9cf6b05c4c', '7a45ecd8-737f-5dcc-b65d-4969640cf42b', 'It has a negative charge', 'A', false, 0),
('38ed1c91-bb30-542b-843d-599c5cd7d138', '7a45ecd8-737f-5dcc-b65d-4969640cf42b', 'It travels at the speed of light and has no rest mass', 'B', true, 1),
('b2c93a42-8a1b-56b6-af34-5cd72f14e6dd', '7a45ecd8-737f-5dcc-b65d-4969640cf42b', 'It travels more slowly than light in a vacuum', 'C', false, 2),
('b4dd378f-8f5b-5d13-b496-5bdead722036', '7a45ecd8-737f-5dcc-b65d-4969640cf42b', 'It always has the same energy', 'D', false, 3),
('ce0b27c8-1aea-5938-87ed-f441c281dccc', '04b17875-9183-54cb-b93a-43b677c7f02e', 'They have the same speed', 'A', false, 0),
('472c05e1-9c4a-5347-a91c-5666f5964ef4', '04b17875-9183-54cb-b93a-43b677c7f02e', 'They have the same kinetic energy', 'B', false, 1),
('65342ec7-a784-58d9-9e3b-c1a76eeee547', '04b17875-9183-54cb-b93a-43b677c7f02e', 'They have the same momentum', 'C', true, 2),
('89b14c5c-cdba-5503-b04e-4d1daf31758d', '04b17875-9183-54cb-b93a-43b677c7f02e', 'The proton has the larger momentum', 'D', false, 3),
('38550e70-9495-5e61-a1f6-982293ceda0b', '706ce56e-8430-5e4a-88ae-682e2f88a552', 'A wave would deliver energy continuously, so even dim light of any frequency should eventually release electrons', 'A', true, 0),
('c5feb2b5-9751-55fe-9c8e-07b98455a576', '706ce56e-8430-5e4a-88ae-682e2f88a552', 'Waves cannot carry energy', 'B', false, 1),
('93bf104d-2359-5afd-946e-ea7aa379e3d1', '706ce56e-8430-5e4a-88ae-682e2f88a552', 'Waves cannot travel through a vacuum', 'C', false, 2),
('c39c05dd-ae35-5041-a649-94c9fcda3bd3', '706ce56e-8430-5e4a-88ae-682e2f88a552', 'The wave model predicts no electrons for bright light', 'D', false, 3),
('64c8ea12-2dbd-5085-b7e1-a9ec6bcd2bcf', 'd5cbfb5b-ac3f-52da-90ff-27246c56b9a6', 'The energy of each photon', 'A', false, 0),
('d7159728-27b3-560d-bc78-db6c27cdf53e', 'd5cbfb5b-ac3f-52da-90ff-27246c56b9a6', 'The frequency of the light', 'B', false, 1),
('3a7bb1cc-ed07-5201-94e3-f048638557e3', 'd5cbfb5b-ac3f-52da-90ff-27246c56b9a6', 'The speed of the photons', 'C', false, 2),
('bb38e393-2e2e-5e2b-a936-a2b7bde32b4b', 'd5cbfb5b-ac3f-52da-90ff-27246c56b9a6', 'The number of photons arriving per second per unit area', 'D', true, 3),
('f67a2f82-7cbe-509c-8d34-46a3ca6d0af3', '70824ee2-52b0-512b-9f32-e3970e1d0e0f', 'They get larger because the wavelength increases', 'A', false, 0),
('2920162f-7d55-559e-880d-9c8405581ae6', '70824ee2-52b0-512b-9f32-e3970e1d0e0f', 'They get smaller because the electrons'' de Broglie wavelength decreases', 'B', true, 1),
('cc3b7489-fa60-5560-8da0-83dc3c1698e6', '70824ee2-52b0-512b-9f32-e3970e1d0e0f', 'They do not change', 'C', false, 2),
('7f0ba482-44e9-51a8-a371-2e46d4d83c2d', '70824ee2-52b0-512b-9f32-e3970e1d0e0f', 'They disappear because faster electrons cannot diffract', 'D', false, 3),
('ee9addd5-94c6-5e47-8e7d-c24652f13eba', 'f2507641-9e59-5f53-8a62-87082b97d479', 'The electron has much more energy than the photon', 'A', false, 0),
('0cbfd268-92ca-5d34-ad96-bd548fd2af48', 'f2507641-9e59-5f53-8a62-87082b97d479', 'They have equal energies', 'B', false, 1),
('bae33045-8c80-57b3-a0b8-bf91d79937b0', 'f2507641-9e59-5f53-8a62-87082b97d479', 'The photon has much more energy than the electron', 'C', true, 2),
('97b08747-f286-5fb7-9178-1e000a7e4c94', 'f2507641-9e59-5f53-8a62-87082b97d479', 'They have different momenta', 'D', false, 3),
('9a431f11-d624-5111-a6e0-22d7c18ff1ac', 'cf0a577b-5ff0-5116-9272-4432ff5fb5b5', 'Its de Broglie wavelength is far smaller than the width of the doorway', 'A', true, 0),
('b313ba4f-4314-5a87-ab3c-745ab4780dbc', 'cf0a577b-5ff0-5116-9272-4432ff5fb5b5', 'Cricket balls have no de Broglie wavelength', 'B', false, 1),
('59e9a973-40dc-52ca-99a3-a414a2b5a33c', 'cf0a577b-5ff0-5116-9272-4432ff5fb5b5', 'The doorway is too narrow', 'C', false, 2),
('aff1e4e8-07ec-5711-95b8-6321b106e036', 'cf0a577b-5ff0-5116-9272-4432ff5fb5b5', 'Only charged particles can diffract', 'D', false, 3),
('e6deb287-0450-58e3-9fe1-0e2d912b5360', 'f880783f-5e4a-5749-9a0a-0786cbd9234e', 'Electrons are emitted from metals, and they can be absorbed', 'A', false, 0),
('29312d03-9b74-57a7-8499-b9fc4229fc94', 'f880783f-5e4a-5749-9a0a-0786cbd9234e', 'Electrons have charge, and they have mass', 'B', false, 1),
('b6eb56e7-f03b-531b-9749-366f08e5a03f', 'f880783f-5e4a-5749-9a0a-0786cbd9234e', 'Electrons travel in straight lines, and they produce X-rays', 'C', false, 2),
('4416bcc1-cd58-5ad1-9501-225b9e5b96a3', 'f880783f-5e4a-5749-9a0a-0786cbd9234e', 'Electrons are deflected by fields as charged particles, and they form diffraction patterns', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('ccf4d223-96cd-5899-a7ef-2403284fa003', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 9, 9, 'A sodium street lamp emits yellow light of wavelength 589 nm. Calculate the energy of one photon of this light in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '3.377', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 589 × 10⁻⁹ = 3.38 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: E = hc/λ. A1: E = 3.38 × 10⁻¹⁹ J.', 2, NULL, NULL),
('495d909a-610f-5fd8-8fa2-cdac03bd471a', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 10, 10, 'What is the unit of the Planck constant?', NULL, 1, 'multiple_choice'::answer_type, 'J s', NULL, false, NULL, false, NULL, 'h = E/f, so its unit is J ÷ s⁻¹ = J s. Mark scheme (1 mark). B1: C (J s).', 1, NULL, NULL),
('3d7ef661-c9c8-5fe2-9841-4d6f3ec82065', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 11, 11, 'Microwaves in an oven have a frequency of 2.45 × 10⁹ Hz. Calculate the energy of one microwave photon in units of 10⁻²⁴ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.624', '10⁻²⁴ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 2.45 × 10⁹ = 1.62 × 10⁻²⁴ J. Mark scheme (2 marks). C1: E = hf. A1: E = 1.62 × 10⁻²⁴ J.', 2, NULL, NULL),
('cf78c0dc-40ef-5468-9e83-39ae0718f3e4', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 12, 12, 'The wavelength of a beam of light is halved. What happens to the energy of each photon?', NULL, 1, 'multiple_choice'::answer_type, 'It doubles', NULL, false, NULL, false, NULL, 'E = hc/λ, so E ∝ 1/λ. Mark scheme (1 mark). B1: A (It doubles).', 1, NULL, NULL),
('527f3b96-0382-517f-b81c-fd27fc5f6829', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 13, 13, 'A photon of infrared radiation has an energy of 1.5 × 10⁻¹⁹ J. Calculate its frequency. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '2.262e14', 'Hz', false, NULL, false, NULL, 'f = E/h = 1.5 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 2.26 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f = E/h. A1: f = 2.26 × 10¹⁴ Hz.', 2, NULL, NULL),
('46d8a3cd-40ce-54f8-a081-088884712215', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 14, 14, 'Which expression gives the momentum p of a photon of energy E?', NULL, 1, 'multiple_choice'::answer_type, 'p = E/c', NULL, false, NULL, false, NULL, 'p = h/λ = hf/c = E/c. Mark scheme (1 mark). B1: D (p = E/c).', 1, NULL, NULL),
('884f09ae-d6ad-5ed0-ab84-0f7827632d50', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 15, 15, 'A gamma-ray photon has a frequency of 2.4 × 10²⁰ Hz. Calculate its energy in units of 10⁻¹³ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '1.591', '10⁻¹³ J', false, NULL, false, NULL, 'E = hf = 6.63 × 10⁻³⁴ × 2.4 × 10²⁰ = 1.59 × 10⁻¹³ J. Mark scheme (2 marks). C1: E = hf. A1: E = 1.6 × 10⁻¹³ J.', 2, NULL, NULL),
('ec18e42a-0dfc-502b-9cb9-2632d4477acd', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 16, 16, 'One electronvolt is the energy transferred when', NULL, 1, 'multiple_choice'::answer_type, 'an electron moves through a potential difference of 1 V', NULL, false, NULL, false, NULL, '1 eV = 1.60 × 10⁻¹⁹ C × 1 V = 1.60 × 10⁻¹⁹ J. Mark scheme (1 mark). B1: B (an electron moves through a potential difference of 1 V).', 1, NULL, NULL),
('6c27cd34-4fe3-5266-9d87-314d06256e10', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 17, 17, 'A photon of ultraviolet light has an energy of 4.8 eV. Calculate this energy in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '7.68', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = 4.8 × 1.60 × 10⁻¹⁹ = 7.68 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: × 1.60 × 10⁻¹⁹. A1: E = 7.7 × 10⁻¹⁹ J.', 2, NULL, NULL),
('2c24d5b2-ab08-5857-87e5-2a6d89055d5e', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 18, 18, 'Which colour of visible light has photons of the greatest energy?', NULL, 1, 'multiple_choice'::answer_type, 'Violet', NULL, false, NULL, false, NULL, 'Violet has the highest frequency in the visible spectrum. Mark scheme (1 mark). B1: C (Violet).', 1, NULL, NULL),
('adc192fd-cb4c-5faa-afbe-925d9b447e0b', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 19, 19, 'Calculate the momentum of a photon of ultraviolet light of wavelength 250 nm, in units of 10⁻²⁷ kg m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '2.652', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'p = h/λ = 6.63 × 10⁻³⁴ ÷ 250 × 10⁻⁹ = 2.65 × 10⁻²⁷ kg m s⁻¹. Mark scheme (2 marks). C1: p = h/λ. A1: p = 2.65 × 10⁻²⁷ kg m s⁻¹.', 2, NULL, NULL),
('9fabf033-36c8-5d26-96e5-99848eecba2a', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 20, 20, 'A beam of monochromatic light is made brighter without changing its colour. What increases?', NULL, 1, 'multiple_choice'::answer_type, 'The number of photons arriving per second', NULL, false, NULL, false, NULL, 'Colour fixes photon energy; brightness is photon rate. Mark scheme (1 mark). B1: A (The number of photons arriving per second).', 1, NULL, NULL),
('f9ca88d6-7d0a-5e11-92f1-d1000a522dba', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 21, 21, 'A photon has an energy of 2.0 eV. Calculate its energy in joules and hence its frequency. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '4.827e14', 'Hz', false, NULL, false, NULL, 'E = 2.0 × 1.60 × 10⁻¹⁹ = 3.2 × 10⁻¹⁹ J. f = 3.2 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 4.83 × 10¹⁴ Hz. Mark scheme (2 marks). C1: eV to J then f = E/h. A1: f = 4.83 × 10¹⁴ Hz.', 2, NULL, NULL),
('2a73b285-c31d-5bfd-a848-6b42aa320fad', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 22, 22, 'An X-ray photon has a momentum of 6.6 × 10⁻²⁴ kg m s⁻¹. Calculate its energy in units of 10⁻¹⁵ J. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.98', '10⁻¹⁵ J', false, NULL, false, NULL, 'E = pc = 6.6 × 10⁻²⁴ × 3.00 × 10⁸ = 1.98 × 10⁻¹⁵ J. Mark scheme (2 marks). C1: E = pc. A1: E = 2.0 × 10⁻¹⁵ J.', 2, NULL, NULL),
('ba6ade1c-2f67-5d1f-bb75-a02ca737face', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 23, 23, 'Which equation links the energy of a photon to its wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'E = hc/λ', NULL, false, NULL, false, NULL, 'E = hf and f = c/λ, so E = hc/λ: shorter wavelengths give more energetic photons. Mark scheme (1 mark). B1: D (E = hc/λ).', 1, NULL, NULL),
('94a4f246-a32f-5d30-b312-1592fa50a7b0', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 24, 24, 'A photon has an energy of 5.0 × 10⁻¹⁹ J. Calculate its momentum in units of 10⁻²⁷ kg m s⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1.667', '10⁻²⁷ kg m s⁻¹', false, 0.05, false, NULL, 'p = E/c = 5.0 × 10⁻¹⁹ ÷ 3.00 × 10⁸ = 1.67 × 10⁻²⁷ kg m s⁻¹. Mark scheme (1 mark). A1: p = 1.7 × 10⁻²⁷ kg m s⁻¹.', 1, NULL, NULL),
('1367eb3f-d029-5098-8080-8add44b075f1', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 25, 25, 'How many photons, each of energy 4.0 eV, together carry a total energy of 1.0 J? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.562e18', NULL, false, NULL, false, NULL, 'E = 4.0 × 1.60 × 10⁻¹⁹ = 6.4 × 10⁻¹⁹ J. N = 1.0 ÷ 6.4 × 10⁻¹⁹ = 1.56 × 10¹⁸. Mark scheme (2 marks). C1: eV to J then N = total ÷ E. A1: N = 1.56 × 10¹⁸.', 2, NULL, NULL),
('b133b0d9-2e95-58e6-922e-dd1473b2de42', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 26, 26, 'Which type of electromagnetic radiation has photons of the lowest energy?', NULL, 1, 'multiple_choice'::answer_type, 'Radio waves', NULL, false, NULL, false, NULL, 'Radio waves have the lowest frequency, and E = hf. Mark scheme (1 mark). B1: C (Radio waves).', 1, NULL, NULL),
('9b7dccc0-14a1-5da6-bf15-964d2d709e58', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 27, 27, 'A photon of energy 3.5 eV is emitted by an LED. Calculate the wavelength of the light in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '355.2 nm', 'nm', false, NULL, false, NULL, 'E = 3.5 × 1.60 × 10⁻¹⁹ = 5.6 × 10⁻¹⁹ J. λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 5.6 × 10⁻¹⁹ = 3.552 × 10⁻⁷ m. In nm: 3.552 × 10⁻⁷ × 10⁹ = 355. Mark scheme (3 marks). C1: eV to J. C1: λ = hc/E. A1: λ = 355 nm.', 3, NULL, NULL),
('6213767e-9d4a-53b5-9949-392546807355', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 28, 28, 'A lamp emits 1.5 W of light of wavelength 590 nm. How many photons does it emit per second? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '4.449e18', NULL, false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 590 × 10⁻⁹ = 3.371 × 10⁻¹⁹ J. n = 1.5 ÷ 3.371 × 10⁻¹⁹ = 4.45 × 10¹⁸. Mark scheme (3 marks). C1: photon energy. C1: n = P/E. A1: n = 4.45 × 10¹⁸.', 3, NULL, NULL),
('c4d46368-edde-5a87-990e-047506b3b48c', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 29, 29, 'Show that the energy in eV of a photon of wavelength λ nm is about 1240/λ, and use this to find the energy of a 310 nm photon in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4.01', 'eV', false, NULL, false, NULL, 'hc/e = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1.60 × 10⁻¹⁹ = 1.243 × 10⁻⁶ V m, which is 1243 eV nm. E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (310 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 4.01 eV. Mark scheme (3 marks). C1: hc/e evaluated. C1: division by λ. A1: E = 4.01 eV.', 3, NULL, NULL),
('1d03071e-5af7-5761-a70b-f4d46a96b144', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 30, 30, 'Photon X has twice the wavelength of photon Y. What is (momentum of X) ÷ (momentum of Y)?', NULL, 2, 'multiple_choice'::answer_type, '0.5', NULL, false, NULL, false, NULL, 'p = h/λ, so doubling λ halves p. Mark scheme (3 marks). C1: p = h/λ. C1: inverse proportion. A1: B (0.5).', 3, NULL, NULL),
('756536db-3d9e-58eb-ba65-82acc159a3c8', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 31, 31, 'A beam of photons, each of energy 2.2 × 10⁻¹⁹ J, delivers 8.8 mW. Calculate the number of photons arriving per second.', NULL, 2, 'numeric'::answer_type, '4e16', NULL, false, NULL, false, NULL, 'n = P/E = 8.8 × 10⁻³ ÷ 2.2 × 10⁻¹⁹ = 4.00 × 10¹⁶. Mark scheme (3 marks). C1: P = nE. C1: mW to W. A1: n = 4.0 × 10¹⁶.', 3, NULL, NULL),
('7f7f291a-3565-58ae-b854-093c4edba7ab', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 32, 32, 'A photon has a momentum of 1.2 × 10⁻²⁷ kg m s⁻¹. Calculate its energy in eV. Take c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.25', 'eV', false, NULL, false, NULL, 'E = pc = 1.2 × 10⁻²⁷ × 3.00 × 10⁸ = 3.6 × 10⁻¹⁹ J. In eV: 3.6 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 2.25 eV. Mark scheme (4 marks). C1: E = pc. C1: value in J. C1: ÷ e. A1: E = 2.25 eV.', 4, NULL, NULL),
('9a13df48-a97d-51a9-aa89-850109b80e82', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 33, 33, 'Two lasers emit the same power. Laser P emits red light and laser Q emits blue light. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Laser P emits more photons per second', NULL, false, NULL, false, NULL, 'Red photons carry less energy each, so more are needed for the same power. Mark scheme (3 marks). C1: E red < E blue. C1: n = P/E. A1: C (Laser P emits more photons per second).', 3, NULL, NULL),
('0ab95c94-f7e4-5c96-85e6-a0ef45f980b9', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 34, 34, 'A photon of visible light has momentum 1.3 × 10⁻²⁷ kg m s⁻¹. Calculate its wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '510 nm', 'nm', false, NULL, false, NULL, 'λ = h/p = 6.63 × 10⁻³⁴ ÷ 1.3 × 10⁻²⁷ = 5.100 × 10⁻⁷ m. In nm: 5.100 × 10⁻⁷ × 10⁹ = 510. Mark scheme (3 marks). C1: λ = h/p. C1: convert to nm. A1: λ = 510 nm.', 3, NULL, NULL),
('2319315f-f43b-5423-a46f-cef130225f58', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 35, 35, 'A 100 W light bulb converts 5.0% of its power into visible light. Treating this light as photons of wavelength 560 nm, calculate the number of visible photons emitted per second. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.408e19', NULL, false, NULL, false, NULL, 'Visible power = 0.050 × 100 = 5.0 W. E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 560 × 10⁻⁹ = 3.552 × 10⁻¹⁹ J. n = 5.0 ÷ 3.552 × 10⁻¹⁹ = 1.41 × 10¹⁹. Mark scheme (4 marks). C1: useful power. C1: photon energy. C1: n = P/E. A1: n = 1.41 × 10¹⁹.', 4, NULL, NULL),
('9b788b4a-845a-59fc-b826-39075c064e5e', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 36, 36, 'Which graph would be a straight line through the origin?', NULL, 2, 'multiple_choice'::answer_type, 'Photon energy against frequency', NULL, false, NULL, false, NULL, 'E = hf, so E ∝ f with gradient h. Mark scheme (3 marks). C1: E = hf. C1: gradient h. A1: A (Photon energy against frequency).', 3, NULL, NULL),
('b3ae6e3a-ddef-5435-81b6-aa3b3ec06959', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 37, 37, 'Calculate (energy of an X-ray photon of wavelength 0.050 nm) ÷ (energy of a visible photon of wavelength 500 nm).', NULL, 2, 'numeric'::answer_type, '10000', NULL, false, NULL, false, NULL, 'E ∝ 1/λ, so ratio = 500 ÷ 0.050 = 1.00 × 10⁴. Mark scheme (3 marks). C1: E ∝ 1/λ. C1: same units used. A1: ratio = 1.0 × 10⁴.', 3, NULL, NULL),
('d548c3fb-2d1e-551d-acfe-6aa6fd9de489', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 38, 38, 'A pulse from a laser contains 3.0 × 10¹⁵ photons of wavelength 694 nm. Calculate the energy of the pulse. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '8.598e-4', 'J', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 694 × 10⁻⁹ = 2.866 × 10⁻¹⁹ J per photon. Total = 3.0 × 10¹⁵ × 2.866 × 10⁻¹⁹ = 8.60 × 10⁻⁴ J. Mark scheme (3 marks). C1: photon energy. C1: × number. A1: E = 8.60 × 10⁻⁴ J.', 3, NULL, NULL),
('a4fbfef2-97bd-5aeb-9a65-1be847a2e40e', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 39, 39, 'A photon is absorbed by a surface. Which quantity is transferred to the surface?', NULL, 2, 'multiple_choice'::answer_type, 'Both energy hf and momentum h/λ', NULL, false, NULL, false, NULL, 'A photon carries momentum p = E/c, so absorption transfers both, giving radiation pressure. Mark scheme (4 marks). C1: energy transferred. C1: momentum p = h/λ. C1: radiation pressure exists. A1: D (Both energy hf and momentum h/λ).', 4, NULL, NULL),
('7e50b774-dad6-54e8-a09e-3b2c49de78db', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 40, 40, 'Each photon from an ultraviolet lamp carries 8.0 × 10⁻¹⁹ J of energy. What momentum does one photon carry? Give the answer in units of 10⁻²⁷ kg m s⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '2.667', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'p = E/c = 8.0 × 10⁻¹⁹ ÷ 3.00 × 10⁸ = 2.67 × 10⁻²⁷ kg m s⁻¹. Mark scheme (3 marks). C1: p = E/c. C1: substitution. A1: p = 2.67 × 10⁻²⁷ kg m s⁻¹.', 3, NULL, NULL),
('1dc5a930-ce9f-5a15-a888-f7cffae5f551', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 41, 41, 'A photon of energy 1.8 eV is emitted by a red LED. Calculate the frequency of the light. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '4.344e14', 'Hz', false, NULL, false, NULL, 'E = 1.8 × 1.60 × 10⁻¹⁹ = 2.88 × 10⁻¹⁹ J. f = 2.88 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 4.34 × 10¹⁴ Hz. Mark scheme (4 marks). C1: eV to J. C1: f = E/h. C1: substitution. A1: f = 4.34 × 10¹⁴ Hz.', 4, NULL, NULL),
('55a8146f-b19f-57bb-acdb-c4347ed50ece', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 42, 42, 'Two photons have energies of 2.0 eV and 4.0 eV. What is (wavelength of the 2.0 eV photon) ÷ (wavelength of the 4.0 eV photon)?', NULL, 2, 'multiple_choice'::answer_type, '2', NULL, false, NULL, false, NULL, 'λ = hc/E: halving E doubles λ. Mark scheme (3 marks). C1: λ ∝ 1/E. C1: ratio. A1: B (2).', 3, NULL, NULL),
('54b58623-47bc-5ce1-8245-662addb495d1', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 43, 43, 'A photon counter registers photons that each carry 1.2 × 10⁻¹⁸ J. Calculate the wavelength of this radiation in nm. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '165.7 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 1.2 × 10⁻¹⁸ = 1.657 × 10⁻⁷ m. In nm: 1.657 × 10⁻⁷ × 10⁹ = 166. Mark scheme (3 marks). C1: λ = hc/E. C1: convert to nm. A1: λ = 166 nm.', 3, NULL, NULL),
('b013cb21-f001-5072-8c66-f071b5ebbec3', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 44, 44, 'A laser emits pulses of light of wavelength 532 nm. Each pulse lasts 10 ns and carries 0.20 J. (a) Calculate the mean power during a pulse. (b) Calculate the energy of one photon. (c) Calculate the number of photons in one pulse. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.349e17', NULL, false, NULL, false, NULL, '(a) P = 0.20 ÷ 10 × 10⁻⁹ = 2.0 × 10⁷ W. (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 532 × 10⁻⁹ = 3.739 × 10⁻¹⁹ J. (c) N = 0.20 ÷ 3.739 × 10⁻¹⁹ = 5.35 × 10¹⁷. Mark scheme (5 marks). C1: P = E/t. C1: photon energy. M1: N = pulse energy ÷ photon energy. B1: correct units. A1: N = 5.35 × 10¹⁷.', 5, NULL, NULL),
('ed0894d1-f197-5a4c-80ef-48a83862e192', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 45, 45, 'A solar sail of area 100 m² faces the Sun at a distance where the intensity is 1.4 kW m⁻². The sail reflects all the light straight back. (a) Calculate the power arriving at the sail. (b) Explain why reflection doubles the momentum change of each photon. (c) Calculate the force on the sail. Give only the answer to (c), in mN. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '0.9333 mN', 'mN', false, NULL, false, NULL, '(a) P = 1.4 × 10³ × 100 = 1.4 × 10⁵ W. (b) Each photon arrives with p and leaves with −p, so Δp = 2p. (c) F = 2P/c = 2 × 1.4 × 10⁵ ÷ 3.00 × 10⁸ = 9.33 × 10⁻⁴ N. In mN: 9.333 × 10⁻⁴ × 10³ = 0.933. Mark scheme (6 marks). C1: P = IA. B1: Δp = 2p on reflection. M1: F = 2P/c. C1: value. C1: conversion to mN. A1: F = 0.933 mN.', 6, NULL, NULL),
('cd56cf46-e266-5d96-8304-141be7a5b09c', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 46, 46, 'A detector records 5.0 × 10⁸ photons of wavelength 450 nm per second. (a) Calculate the energy of one photon. (b) Calculate the power received. (c) The detector has an area of 4.0 mm². Calculate the intensity at the detector. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.525e-5', 'W m⁻²', false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 450 × 10⁻⁹ = 4.420 × 10⁻¹⁹ J. (b) P = 5.0 × 10⁸ × 4.420 × 10⁻¹⁹ = 2.210 × 10⁻¹⁰ W. (c) I = 2.210 × 10⁻¹⁰ ÷ 4.0 × 10⁻⁶ = 5.53 × 10⁻⁵ W m⁻². Mark scheme (5 marks). C1: photon energy. C1: P = nE. C1: mm² to m². C1: I = P/A. A1: I = 5.53 × 10⁻⁵ W m⁻².', 5, NULL, NULL),
('0235910f-f045-59d0-afae-bd78ab4014b7', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 47, 47, 'A 2.0 W beam of light of wavelength 600 nm is completely absorbed by a 1.0 g piece of foil hanging in a vacuum. (a) Calculate the momentum of one photon. (b) Calculate the number of photons absorbed per second. (c) Calculate the force on the foil. (d) Calculate the acceleration of the foil. Give only the answer to (d), in units of 10⁻⁶ m s⁻². Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '6.667', '10⁻⁶ m s⁻²', false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 600 × 10⁻⁹ = 1.105 × 10⁻²⁷ kg m s⁻¹. (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 600 × 10⁻⁹ = 3.315 × 10⁻¹⁹ J, so n = 2.0 ÷ 3.315 × 10⁻¹⁹ = 6.033 × 10¹⁸ s⁻¹. (c) F = np = 6.033 × 10¹⁸ × 1.105 × 10⁻²⁷ = 6.667 × 10⁻⁹ N. (d) a = F/m = 6.667 × 10⁻⁹ ÷ 1.0 × 10⁻³ = 6.67 × 10⁻⁶ m s⁻². Mark scheme (6 marks). C1: photon momentum. C1: photon rate. C1: F = np (or P/c). C1: mass in kg. C1: a = F/m. A1: a = 6.67 × 10⁻⁶ m s⁻².', 6, NULL, NULL),
('e0006e20-f11d-5cd9-b125-52ad0ab51b7a', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 48, 48, 'A star emits 3.8 × 10²⁶ W, and its light can be treated as photons of mean wavelength 500 nm. (a) Calculate the photon energy. (b) Calculate the number of photons emitted each second. (c) Explain why the photon nature of starlight can be seen with sensitive detectors on Earth. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '9.553e44', NULL, false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 500 × 10⁻⁹ = 3.978 × 10⁻¹⁹ J. (b) n = 3.8 × 10²⁶ ÷ 3.978 × 10⁻¹⁹ = 9.55 × 10⁴⁴. (c) Far away the photons are spread so thinly that a detector receives them one at a time, as separate counts. Mark scheme (5 marks). C1: photon energy. M1: n = P/E. C1: value. B1: photons arrive individually at low intensity. A1: n = 9.55 × 10⁴⁴.', 5, NULL, NULL),
('f2cd5859-057f-5b8a-bad3-50b55195b07d', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 49, 49, 'A photon of wavelength 0.071 nm is produced in an X-ray tube. (a) Calculate its energy in joules. (b) Calculate its energy in keV. (c) Calculate its momentum. (d) Calculate the minimum accelerating p.d. across the tube. Give only the answer to (b), in keV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '17.51', 'keV', false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 0.071 × 10⁻⁹ = 2.801 × 10⁻¹⁵ J. (b) In keV: 2.801 × 10⁻¹⁵ ÷ 1.60 × 10⁻¹⁶ = 17.5 keV. (c) p = 6.63 × 10⁻³⁴ ÷ 0.071 × 10⁻⁹ = 9.34 × 10⁻²⁴ kg m s⁻¹. (d) eV = E, so V ≈ 17.5 kV. Mark scheme (6 marks). C1: E = hc/λ. C1: 1 keV = 1.60 × 10⁻¹⁶ J. C1: value. C1: p = h/λ. B1: V = E/e. A1: E = 17.5 keV.', 6, NULL, NULL),
('cea71962-8540-5726-8684-c55af6fabfcd', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 50, 50, 'Green light of wavelength 520 nm from a 4.0 mW laser is spread evenly over a circle of diameter 2.0 mm. (a) Calculate the intensity. (b) Calculate the number of photons per second. (c) Calculate the number of photons arriving per second on each mm². Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '3.329e15', NULL, false, NULL, false, NULL, '(a) A = π × (1.0 × 10⁻³)² = 3.142 × 10⁻⁶ m², I = 4.0 × 10⁻³ ÷ 3.142 × 10⁻⁶ = 1273 W m⁻². (b) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 520 × 10⁻⁹ = 3.825 × 10⁻¹⁹ J, n = 4.0 × 10⁻³ ÷ 3.825 × 10⁻¹⁹ = 1.046 × 10¹⁶ s⁻¹. (c) Area = π × 1.0² = 3.142 mm², so 1.046 × 10¹⁶ ÷ 3.142 = 3.33 × 10¹⁵. Mark scheme (5 marks). C1: area of beam. C1: photon energy. C1: photon rate. C1: per mm². A1: n = 3.33 × 10¹⁵.', 5, NULL, NULL),
('4be08576-9fd3-5ba5-b7b3-f44394695ceb', '7d22edfc-44c4-4846-9769-292936cb7827', '6403e30c-f596-5ad5-a997-b63837482348', 'a-level', '28.2', '9702 coursebook 28.2 · Photons: energy and momentum', 51, 51, 'A photon of energy 1.0 MeV is a gamma ray. (a) Convert this energy into joules. (b) Calculate its frequency. (c) Calculate its momentum. Give only the answer to (c), in units of 10⁻²² kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C, h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.333', '10⁻²² kg m s⁻¹', false, NULL, false, NULL, '(a) E = 1.0 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹³ J. (b) f = 1.6 × 10⁻¹³ ÷ 6.63 × 10⁻³⁴ = 2.41 × 10²⁰ Hz. (c) p = E/c = 1.6 × 10⁻¹³ ÷ 3.00 × 10⁸ = 5.33 × 10⁻²² kg m s⁻¹. Mark scheme (5 marks). C1: MeV to J. C1: f = E/h. M1: p = E/c. C1: value. A1: p = 5.33 × 10⁻²² kg m s⁻¹.', 5, NULL, NULL)
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('2487f6a4-d59c-50aa-80b7-340d19a99655', '495d909a-610f-5fd8-8fa2-cdac03bd471a', 'J s⁻¹', 'A', false, 0),
('18068c3d-1afe-5041-af80-504c2f9b87fa', '495d909a-610f-5fd8-8fa2-cdac03bd471a', 'J Hz', 'B', false, 1),
