INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('853f6cfa-0b61-568d-8aea-39c387e68063', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 6, 6, 'Photons of energy 3.2 eV fall on a metal whose work function is 2.3 eV. Calculate the maximum kinetic energy of the emitted electrons, in eV.', NULL, 1, 'numeric'::answer_type, '0.9', 'eV', false, NULL, false, NULL, 'Ek(max) = hf − Φ = 3.2 − 2.3 = 0.90 eV. Mark scheme (2 marks). C1: hf = Φ + Ek(max). A1: Ek(max) = 0.90 eV.', 2, NULL, NULL),
('dd7d5694-644a-5bac-9812-4d1bf1e1502f', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 7, 7, 'What is meant by the work function of a metal?', NULL, 1, 'multiple_choice'::answer_type, 'The minimum energy needed to release an electron from the surface of the metal', NULL, false, NULL, false, NULL, 'Electrons nearest the surface need the least energy, Φ, to escape. Mark scheme (1 mark). B1: C (The minimum energy needed to release an electron from the surface of the metal).', 1, NULL, NULL),
('7fe297ca-2b60-5297-917d-1022848c0b6a', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 8, 8, 'The fastest photoelectrons from a surface have a kinetic energy of 2.4 × 10⁻¹⁹ J. Calculate the stopping potential. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.5', 'V', false, NULL, false, NULL, 'V_s = Ek(max)/e = 2.4 × 10⁻¹⁹ ÷ 1.60 × 10⁻¹⁹ = 1.5 V. Mark scheme (2 marks). C1: eV_s = Ek(max). A1: V_s = 1.5 V.', 2, NULL, NULL),
('1a63eff8-8c4a-5fc3-bc80-56b2044eb738', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 9, 9, 'Light above the threshold frequency falls on a metal. Its intensity is increased, with the frequency unchanged. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'More electrons are emitted per second, with the same maximum kinetic energy', NULL, false, NULL, false, NULL, 'More photons per second release more electrons, but each photon still has energy hf. Mark scheme (1 mark). B1: A (More electrons are emitted per second, with the same maximum kinetic energy).', 1, NULL, NULL),
('ff194533-10a8-551a-a840-5140c4a25689', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 10, 10, 'Potassium has a work function of 2.1 eV. Express this in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.36', '10⁻¹⁹ J', false, NULL, false, NULL, 'Φ = 2.1 × 1.60 × 10⁻¹⁹ = 3.36 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: × 1.60 × 10⁻¹⁹. A1: Φ = 3.4 × 10⁻¹⁹ J.', 2, NULL, NULL),
('fed5aff1-48be-5794-8329-6857f1581f0b', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 11, 11, 'The frequency of light shining on a metal is increased (it is already above the threshold). What happens to the maximum kinetic energy of the photoelectrons?', NULL, 1, 'multiple_choice'::answer_type, 'It increases', NULL, false, NULL, false, NULL, 'Ek(max) = hf − Φ rises with f. Mark scheme (1 mark). B1: D (It increases).', 1, NULL, NULL),
('3216c399-5615-5f4d-8db7-92a7a075f81b', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 12, 12, 'Photoelectrons are just stopped by a potential difference of 0.80 V. Calculate their maximum kinetic energy in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.28', '10⁻¹⁹ J', false, NULL, false, NULL, 'Ek(max) = eV_s = 1.60 × 10⁻¹⁹ × 0.80 = 1.28 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: Ek = eV_s. A1: Ek(max) = 1.3 × 10⁻¹⁹ J.', 2, NULL, NULL),
('a8454c08-abe4-5c7d-9a30-51228a287f9d', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 13, 13, 'When light above the threshold frequency first reaches a metal surface, how long is it before electrons are emitted?', NULL, 1, 'multiple_choice'::answer_type, 'Emission begins at once, with no measurable delay', NULL, false, NULL, false, NULL, 'Each photon gives its energy to one electron instantly. Mark scheme (1 mark). B1: B (Emission begins at once, with no measurable delay).', 1, NULL, NULL),
('d72db639-9269-5652-90ec-3c84b85ca2a0', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 14, 14, 'Photons of energy 5.0 × 10⁻¹⁹ J strike a metal with a work function of 3.2 × 10⁻¹⁹ J. Calculate the maximum kinetic energy of the photoelectrons, in units of 10⁻¹⁹ J.', NULL, 1, 'numeric'::answer_type, '1.8', '10⁻¹⁹ J', false, NULL, false, NULL, 'Ek(max) = hf − Φ = 5.0 × 10⁻¹⁹ − 3.2 × 10⁻¹⁹ = 1.8 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: Ek(max) = hf − Φ. A1: Ek(max) = 1.8 × 10⁻¹⁹ J.', 2, NULL, NULL),
('7db8788b-c41e-5a62-b3e6-bcf82d9eee79', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 15, 15, 'In the photon explanation of the photoelectric effect, how many electrons can one photon release?', NULL, 1, 'multiple_choice'::answer_type, 'At most one', NULL, false, NULL, false, NULL, 'A photon is absorbed by a single electron in a one-to-one interaction. Mark scheme (1 mark). B1: C (At most one).', 1, NULL, NULL),
('b769b0d5-507b-578a-90ba-56b03406d42f', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 16, 16, 'Photons of energy 3.4 eV release electrons whose maximum kinetic energy is 1.1 eV. Calculate the work function of the metal in eV.', NULL, 1, 'numeric'::answer_type, '2.3', 'eV', false, NULL, false, NULL, 'Φ = hf − Ek(max) = 3.4 − 1.1 = 2.3 eV. Mark scheme (2 marks). C1: Φ = hf − Ek(max). A1: Φ = 2.3 eV.', 2, NULL, NULL),
('3d32f0bb-83c4-5bd6-897e-2cdc9ecde28a', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 17, 17, 'Why do photoelectrons emitted by monochromatic light have a range of kinetic energies up to a maximum?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons below the surface lose some energy before escaping', NULL, false, NULL, false, NULL, 'Only electrons at the surface leave with the full hf − Φ. Mark scheme (1 mark). B1: A (Electrons below the surface lose some energy before escaping).', 1, NULL, NULL),
('fce580c6-4cfd-5271-8214-725c11cec9c5', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 18, 18, 'Zinc has a work function of 4.3 eV. Ultraviolet photons of energy 5.0 eV fall on a zinc plate. What is the maximum kinetic energy of the emitted electrons, in eV?', NULL, 1, 'numeric'::answer_type, '0.7', 'eV', false, NULL, false, NULL, 'Ek(max) = 5.0 − 4.3 = 0.70 eV. Mark scheme (2 marks). C1: Ek(max) = hf − Φ. A1: Ek(max) = 0.70 eV.', 2, NULL, NULL),
('03ab7aca-cad0-5a1c-b47f-bd25f0d37e81', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 19, 19, 'Which equation is Einstein''s photoelectric equation?', NULL, 1, 'multiple_choice'::answer_type, 'hf = Φ + ½mv²(max)', NULL, false, NULL, false, NULL, 'Photon energy = work function + maximum kinetic energy. Mark scheme (1 mark). B1: D (hf = Φ + ½mv²(max)).', 1, NULL, NULL),
('6f9e31ed-7f56-576e-9de1-9d6d4f7ad08d', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 20, 20, 'Photoelectrons leave a surface with a maximum kinetic energy of 1.0 eV. Calculate their maximum speed. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 1, 'numeric'::answer_type, '5.927e5', 'm s⁻¹', false, NULL, false, NULL, 'Ek = 1.0 × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹⁹ J. v = √(2Ek/m) = √(2 × 1.6 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹) = 5.93 × 10⁵ m s⁻¹. Mark scheme (2 marks). C1: ½mv² = Ek. A1: v = 5.93 × 10⁵ m s⁻¹.', 2, NULL, NULL),
('747c3b2f-7c4a-5bdd-afa3-abd37434fe9d', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 21, 21, 'Very bright red light falls on a metal whose threshold frequency is in the ultraviolet. What is observed?', NULL, 1, 'multiple_choice'::answer_type, 'No electrons are emitted', NULL, false, NULL, false, NULL, 'Each red photon has too little energy, however many arrive. Mark scheme (1 mark). B1: B (No electrons are emitted).', 1, NULL, NULL),
('f2391082-dad0-5fbf-b1ab-70f92d7e1a14', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 22, 22, 'Photoelectrons from a cathode are just stopped by a potential difference of 1.8 V. What is their maximum kinetic energy in eV?', NULL, 1, 'numeric'::answer_type, '1.8', 'eV', false, NULL, false, NULL, 'Ek(max) = eV_s, so in eV: Ek(max) = 1 × 1.8 = 1.8 eV. Mark scheme (1 mark). A1: Ek(max) = 1.8 eV.', 1, NULL, NULL),
('e41a792f-0509-5862-8bc4-b5c12925efbe', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 23, 23, 'Violet light of wavelength 400 nm falls on potassium, work function 2.3 eV. Calculate the maximum kinetic energy of the photoelectrons in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.8078', 'eV', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (400 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 3.108 eV. Ek(max) = 3.108 − 2.3 = 0.808 eV. Mark scheme (3 marks). C1: photon energy in eV. C1: subtract Φ. A1: Ek(max) = 0.808 eV.', 3, NULL, NULL),
('3e919758-9a86-5d56-bef6-8f87f6867560', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 24, 24, 'Light of wavelength 500 nm falls on caesium (work function 2.1 eV). Calculate the stopping potential. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.3862', 'V', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (500 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 2.486 eV. V_s = 2.486 − 2.1 = 0.386 V. Mark scheme (3 marks). C1: photon energy. C1: eV_s = hf − Φ. A1: V_s = 0.386 V.', 3, NULL, NULL),
('76658ee8-8284-5914-bd9d-98cfd0f4d68f', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 25, 25, 'Ultraviolet light of wavelength 250 nm releases photoelectrons that are stopped by a potential difference of 1.6 V. Calculate the work function in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.372', 'eV', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (250 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 4.972 eV. Ek(max) = 1.6 eV, so Φ = 4.972 − 1.6 = 3.37 eV. Mark scheme (4 marks). C1: photon energy. C1: Ek(max) = eV_s. C1: Φ = hf − Ek(max). A1: Φ = 3.37 eV.', 4, NULL, NULL),
('603ae661-0d74-5ab3-a431-15f077c55cb7', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 26, 26, 'A graph is plotted of the maximum kinetic energy of photoelectrons against the frequency of the light. What does its gradient equal?', NULL, 2, 'multiple_choice'::answer_type, 'The Planck constant h', NULL, false, NULL, false, NULL, 'Ek(max) = hf − Φ is a straight line of gradient h. Mark scheme (3 marks). C1: equation in y = mx + c form. C1: gradient h. A1: C (The Planck constant h).', 3, NULL, NULL),
('3678208a-f6c2-519e-98a5-49fd8a6f7121', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 27, 27, 'On the same graph of Ek(max) against frequency, where does the line cross the frequency axis?', NULL, 2, 'multiple_choice'::answer_type, 'At the threshold frequency', NULL, false, NULL, false, NULL, 'Ek(max) = 0 when hf = Φ, i.e. f = f₀. Mark scheme (3 marks). C1: Ek = 0 at intercept. C1: f₀ = Φ/h. A1: A (At the threshold frequency).', 3, NULL, NULL),
('88258b76-9d89-54d7-9e42-b2b158da9799', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 28, 28, 'Light of wavelength 350 nm falls on a metal of work function 2.6 eV. Calculate the maximum speed of the photoelectrons. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹, e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '5.782e5', 'm s⁻¹', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (350 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 3.552 eV, so Ek = 0.9518 eV = 1.523 × 10⁻¹⁹ J. v = √(2 × 1.523 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹) = 5.78 × 10⁵ m s⁻¹. Mark scheme (3 marks). C1: Ek(max) in eV. C1: v = √(2Ek/m). A1: v = 5.78 × 10⁵ m s⁻¹.', 3, NULL, NULL),
('d7efa8ae-6414-52c4-bde6-75382d48a8cf', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 29, 29, 'A photocell passes a current of 2.0 µA. How many photoelectrons reach the anode each second? Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.25e13', NULL, false, NULL, false, NULL, 'n = I/e = 2.0 × 10⁻⁶ ÷ 1.60 × 10⁻¹⁹ = 1.25 × 10¹³. Mark scheme (3 marks). C1: I = ne. C1: µA to A. A1: n = 1.25 × 10¹³.', 3, NULL, NULL),
('b3755bcf-42f8-5acc-8026-94c459798fbe', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 30, 30, 'The frequency of light falling on a metal is doubled (it is above the threshold before and after). How does the maximum kinetic energy of the photoelectrons change?', NULL, 2, 'multiple_choice'::answer_type, 'It more than doubles', NULL, false, NULL, false, NULL, 'Ek = hf − Φ: doubling f gives 2hf − Φ = 2Ek + Φ. Mark scheme (3 marks). C1: Ek = hf − Φ. C1: 2hf − Φ > 2(hf − Φ). A1: D (It more than doubles).', 3, NULL, NULL),
('84679424-6dd2-5b96-83b2-f068f1a0adf0', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 31, 31, 'A 1.0 mW beam of ultraviolet light of wavelength 300 nm falls on a photocell. One photon in 50 releases an electron, and all these electrons are collected. Calculate the photocurrent in µA. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4.827 uA', 'µA', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 300 × 10⁻⁹ = 6.630 × 10⁻¹⁹ J. Photons per second = 1.0 × 10⁻³ ÷ 6.630 × 10⁻¹⁹ = 1.508 × 10¹⁵. I = 1.508 × 10¹⁵ ÷ 50 × 1.60 × 10⁻¹⁹ = 4.827 × 10⁻⁶ A. In µA: 4.827 × 10⁻⁶ × 10⁶ = 4.83. Mark scheme (4 marks). C1: photon rate. C1: electron rate. C1: I = ne. A1: I = 4.83 µA.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 380 250" role="img" aria-labelledby="fg68e3c108-t fg68e3c108-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg68e3c108-t">Photocell circuit</title><desc id="fg68e3c108-d">A vacuum photocell lit by a 1.0 mW ultraviolet beam of wavelength 300 nm. The curved cathode and the rod anode are connected through a microammeter to a cell that makes the anode positive.</desc><circle cx="175" cy="104" r="56" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M150,74 A40,40 0 0,0 150,134" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205" y1="92" x2="205" y2="116" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="128" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">cathode</text><text x="205" y="132" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">anode</text><line x1="205" y1="14" x2="156" y2="76.2" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="153,80 154.6,73.2 159.2,76.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="222" y1="24" x2="158.4" y2="90.5" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="155,94 157.2,87.4 161.5,91.5" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="239" y1="34" x2="160.6" y2="104.7" style="stroke:var(--fig-accent-2,#b45309);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="157,108 159.7,101.6 163.7,105.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="246" y="16" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">300 nm, 1.0 mW</text><line x1="136.5" y1="104" x2="50" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="205" y1="104" x2="310" y2="104" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="104" x2="310" y2="152" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="310" y1="176" x2="310" y2="224" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="310" cy="164" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="310" y="164.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">A</text><text x="330" y="164" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">µA</text><line x1="50" y1="104" x2="50" y2="159" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="50" y1="169" x2="50" y2="224" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="37" y1="169" x2="63" y2="169" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="43" y1="159" x2="57" y2="159" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="50" y1="224" x2="310" y2="224" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'A vacuum photocell lit by a 1.0 mW ultraviolet beam of wavelength 300 nm. The curved cathode and the rod anode are connected through a microammeter to a cell that makes the anode positive.'),
('e2d4452a-1bab-5c96-87b9-6f8fc9ce2ac1', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 32, 32, 'What does the stopping potential in a photoelectric experiment measure?', NULL, 2, 'multiple_choice'::answer_type, 'The maximum kinetic energy of the photoelectrons, in eV', NULL, false, NULL, false, NULL, 'eV_s = Ek(max): the most energetic electrons are just stopped. Mark scheme (3 marks). C1: eV_s. C1: = Ek(max). A1: B (The maximum kinetic energy of the photoelectrons, in eV).', 3, NULL, NULL),
('c18c1209-c78b-5177-b5c5-b2cf7970ab6c', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 33, 33, 'Light of frequency 1.2 × 10¹⁵ Hz releases photoelectrons that are stopped by 2.0 V. Calculate the work function of the metal in eV. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.973', 'eV', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 1.2 × 10¹⁵ ÷ 1.60 × 10⁻¹⁹ = 4.973 eV. Φ = 4.973 − 2.0 = 2.97 eV. Mark scheme (3 marks). C1: hf in eV. C1: Φ = hf − eV_s. A1: Φ = 2.97 eV.', 3, NULL, NULL),
('da764973-b140-5e1a-af72-8dec5223fe28', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 34, 34, 'Which observation could the wave model of light not explain?', NULL, 2, 'multiple_choice'::answer_type, 'Photoelectrons are emitted immediately even when the light is very dim', NULL, false, NULL, false, NULL, 'A spread-out wave would need time to deliver Φ to one electron; photons deliver it at once. Mark scheme (4 marks). C1: wave energy spread over surface. C1: time delay predicted. C1: none observed. A1: C (Photoelectrons are emitted immediately even when the light is very dim).', 4, NULL, NULL),
('c0bf6a71-e850-5426-9df6-414d6f22a3ae', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 35, 35, 'A metal has a work function of 3.0 × 10⁻¹⁹ J. Light of frequency 6.0 × 10¹⁴ Hz falls on it. Calculate the maximum kinetic energy of the photoelectrons in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '0.978', '10⁻¹⁹ J', false, NULL, false, NULL, 'hf = 6.63 × 10⁻³⁴ × 6.0 × 10¹⁴ = 3.978 × 10⁻¹⁹ J. Ek(max) = 3.978 × 10⁻¹⁹ − 3.0 × 10⁻¹⁹ = 9.78 × 10⁻²⁰ J. Mark scheme (3 marks). C1: hf. C1: subtract Φ. A1: Ek(max) = 0.978 × 10⁻¹⁹ J.', 3, NULL, NULL),
('2f585d0c-257b-51a9-a8dd-8a7b5cd1a1a0', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 36, 36, 'In a photocell the current stops increasing once the anode is made sufficiently positive. Why?', NULL, 2, 'multiple_choice'::answer_type, 'All the photoelectrons emitted each second are already being collected', NULL, false, NULL, false, NULL, 'The current is limited by the emission rate, which depends on the light intensity. Mark scheme (3 marks). C1: saturation current. C1: set by photon rate. A1: A (All the photoelectrons emitted each second are already being collected).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg1c84dd15-t fg1c84dd15-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1c84dd15-t">Photocell characteristic</title><desc id="fg1c84dd15-d">Graph of photocurrent I against anode potential V for a photocell: zero below the stopping potential, rising through V = 0 and levelling off at a saturation current for positive V.</desc><line x1="64.8" y1="34" x2="64.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="128.2" y1="34" x2="128.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="191.7" y1="34" x2="191.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255.1" y1="34" x2="255.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="318.6" y1="34" x2="318.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="382" y1="34" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="155.3" x2="382" y2="155.3" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="68.7" x2="382" y2="68.7" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="191.7" y1="242" x2="191.7" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="191.7,24 194.6,30.3 188.7,30.3" style="fill:currentColor;stroke:none"/><line x1="64.8" y1="242" x2="64.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="64.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">−2</text><line x1="128.2" y1="242" x2="128.2" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="128.2" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">−1</text><line x1="191.7" y1="242" x2="191.7" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="191.7" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="255.1" y1="242" x2="255.1" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="255.1" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1</text><line x1="318.6" y1="242" x2="318.6" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="318.6" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="382" y1="242" x2="382" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="382" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3</text><line x1="187.7" y1="242" x2="191.7" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="184.7" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="187.7" y1="155.3" x2="191.7" y2="155.3" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="184.7" y="155.3" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="187.7" y1="68.7" x2="191.7" y2="68.7" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="184.7" y="68.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">V / V</text><text x="187.7" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">I (arbitrary units)</text><line x1="102.8" y1="34" x2="102.8" y2="242" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="106.8" y="42" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−Vₛ</text><polyline points="64.8,242 102.8,242 134.6,146.7 191.7,94.7 229.7,73.9 286.8,68.7 382,68.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="293.2" y="54.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">saturation current</text></svg>', 'Graph of photocurrent I against anode potential V for a photocell: zero below the stopping potential, rising through V = 0 and levelling off at a saturation current for positive V.'),
('a8c99119-f9b4-5570-aeff-bf8f6a704d4d', '7d22edfc-44c4-4846-9769-292936cb7827', '7b93970a-92bd-55df-bca6-9d3907e1c231', 'a-level', '28.3', '9702 coursebook 28.3 · The photoelectric effect', 37, 37, 'A student measures Ek(max) = 0.40 eV for light of 6.0 × 10¹⁴ Hz and Ek(max) = 1.23 eV for light of 8.0 × 10¹⁴ Hz. Use these two points to calculate the Planck constant, in units of 10⁻³⁴ J s. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.64', '10⁻³⁴ J s', false, NULL, false, NULL, 'Gradient = ΔEk/Δf = (1.23 − 0.40) × 1.60 × 10⁻¹⁹ ÷ 2.0 × 10¹⁴ = 6.64 × 10⁻³⁴ J s. Mark scheme (4 marks). C1: gradient of Ek against f. C1: eV to J. C1: Δf. A1: h = 6.64 × 10⁻³⁴ J s.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgacdd3c43-t fgacdd3c43-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgacdd3c43-t">Two measurements</title><desc id="fgacdd3c43-d">Graph of maximum kinetic energy against frequency with two measured points, (6.0 × 10¹⁴ Hz, 0.40 eV) and (8.0 × 10¹⁴ Hz, 1.23 eV), joined by a straight line.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="110.6" y1="34" x2="110.6" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="188.1" y1="34" x2="188.1" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="265.7" y1="34" x2="265.7" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="343.2" y1="34" x2="343.2" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:va