('c376be96-3c5a-58e6-8d6c-8edd31204495', 'fed5aff1-48be-5794-8329-6857f1581f0b', 'It stays the same', 'B', false, 1),
('019442a8-d3a2-5889-93fc-d682b4caa5bb', 'fed5aff1-48be-5794-8329-6857f1581f0b', 'It falls to zero', 'C', false, 2),
