('9b632c81-eee7-5c8a-ab05-a495bee37139', 'a8454c08-abe4-5c7d-9a30-51228a287f9d', 'Emission begins at once, with no measurable delay', 'B', true, 1),
('647bdfc2-3163-5b66-b19c-7af19c9a88b0', 'a8454c08-abe4-5c7d-9a30-51228a287f9d', 'It depends on the intensity: dim light takes hours', 'C', false, 2),
('3b800129-f0b1-5e6b-a525-a79c4c1225ec', 'a8454c08-abe4-5c7d-9a30-51228a287f9d', 'Emission only starts once the metal warms up', 'D', false, 3),
('788c9bee-6261-581a-82ae-5600035c8dcc', '7db8788b-c41e-5a62-b3e6-bcf82d9eee79', 'Exactly two', 'A', false, 0),
('aa76610d-ff0e-5e16-b17b-104882e3779c', '7db8788b-c41e-5a62-b3e6-bcf82d9eee79', 'As many as its energy allows', 'B', false, 1),
('1e60d72d-9342-5149-8c66-5193adeb1d0f', '7db8788b-c41e-5a62-b3e6-bcf82d9eee79', 'At most one', 'C', true, 2),
('1c7f4290-5192-58b6-9d2e-849b5e458a55', '7db8788b-c41e-5a62-b3e6-bcf82d9eee79', 'None, photons only heat the metal', 'D', false, 3),
('a8972859-a8a7-5d05-9e5c-32f49887e164', '3d32f0bb-83c4-5bd6-897e-2cdc9ecde28a', 'Electrons below the surface lose some energy before escaping', 'A', true, 0),
('247eb086-2421-57b6-ba79-60fe651af9ce', '3d32f0bb-83c4-5bd6-897e-2cdc9ecde28a', 'The photons have a range of energies', 'B', false, 1),
('060c7a7f-3323-5690-91c6-980b3562118c', '3d32f0bb-83c4-5bd6-897e-2cdc9ecde28a', 'Some photons are slower than others', 'C', false, 2),
('e3206be8-da4d-5ce5-8dc1-cba0c21ccd44', '3d32f0bb-83c4-5bd6-897e-2cdc9ecde28a', 'The work function varies with time', 'D', false, 3),
