('c02cc42d-d8f0-5696-8362-f48ea50522aa', '03ab7aca-cad0-5a1c-b47f-bd25f0d37e81', 'Φ = hf + ½mv²(max)', 'B', false, 1),
('f1290448-97ac-519b-b077-5d730ec134d3', '03ab7aca-cad0-5a1c-b47f-bd25f0d37e81', 'hf = ½mv²(max)', 'C', false, 2),
('f3cd8cb3-a9b4-55b3-9c52-da7cbf2f8167', '03ab7aca-cad0-5a1c-b47f-bd25f0d37e81', 'hf = Φ + ½mv²(max)', 'D', true, 3),
('3dc701e7-170f-5385-b0fd-b3e87ec4183f', '747c3b2f-7c4a-5bdd-afa3-abd37434fe9d', 'Many slow electrons are emitted', 'A', false, 0),
