('77005118-c304-5ba3-987c-2ccbc44db781', '603ae661-0d74-5ab3-a431-15f077c55cb7', 'The work function', 'A', false, 0),
('16a7fe31-5aee-5470-badb-257fe8e56201', '603ae661-0d74-5ab3-a431-15f077c55cb7', 'The threshold frequency', 'B', false, 1),
('1c961c74-1d1c-5f8f-b70d-7e10163d159c', '603ae661-0d74-5ab3-a431-15f077c55cb7', 'The Planck constant h', 'C', true, 2),
('ee3ddd45-3953-5ba5-86e9-63813180e35b', '603ae661-0d74-5ab3-a431-15f077c55cb7', 'The electron charge e', 'D', false, 3),
('8068f8f8-1c5f-5a24-bd46-7d29de44a83e', '3678208a-f6c2-519e-98a5-49fd8a6f7121', 'At the threshold frequency', 'A', true, 0),
