('2aeefa36-0e6f-52de-a337-e6208b6e76a3', '3678208a-f6c2-519e-98a5-49fd8a6f7121', 'At the origin', 'C', false, 2),
('525673bc-7eb4-590d-bf00-f409377c7fa8', '3678208a-f6c2-519e-98a5-49fd8a6f7121', 'At the Planck constant', 'D', false, 3),
('3ae7642c-c409-5b11-9520-b75c2d4163a1', 'b3755bcf-42f8-5acc-8026-94c459798fbe', 'It exactly doubles', 'A', false, 0),
