('d27ec38d-b71e-5442-b6ec-58b6fa8b5008', 'e2d4452a-1bab-5c96-87b9-6f8fc9ce2ac1', 'The work function of the metal', 'A', false, 0),
('c77723b8-857d-58fd-acd1-ded58f063f2f', 'e2d4452a-1bab-5c96-87b9-6f8fc9ce2ac1', 'The maximum kinetic energy of the photoelectrons, in eV', 'B', true, 1),
('12ccce35-2427-5ed1-bc67-b68bc313471a', 'e2d4452a-1bab-5c96-87b9-6f8fc9ce2ac1', 'The number of photons per second', 'C', false, 2),
('2b9e142f-62bf-5ae2-bb37-02ab1c008a66', 'e2d4452a-1bab-5c96-87b9-6f8fc9ce2ac1', 'The threshold wavelength', 'D', false, 3),
('d6cb49e9-af12-5ede-91d9-ba62860c1ac6', 'da764973-b140-5e1a-af72-8dec5223fe28', 'The photocurrent increases with intensity', 'A', false, 0),
('1b26fb4f-21ca-5084-8ea2-7278edd85090', 'da764973-b140-5e1a-af72-8dec5223fe28', 'Light can be reflected from the metal', 'B', false, 1),
('27600e78-e172-5a52-b0e9-6fb4cd092aa9', 'da764973-b140-5e1a-af72-8dec5223fe28', 'Photoelectrons are emitted immediately even when the light is very dim', 'C', true, 2),
('db6f2eca-f41a-5095-9c5b-80383cf677d2', 'da764973-b140-5e1a-af72-8dec5223fe28', 'Light is absorbed by the metal', 'D', false, 3),
('6d5bb02f-00a5-5e93-98be-74d1d58c7fb5', '2f585d0c-257b-51a9-a8dd-8a7b5cd1a1a0', 'All the photoelectrons emitted each second are already being collected', 'A', true, 0),
('8e4713e7-9b57-538e-84ff-92b9301fa677', '2f585d0c-257b-51a9-a8dd-8a7b5cd1a1a0', 'The photons run out', 'B', false, 1),
('baa3a5f4-20eb-52f9-a5c3-99ff0f85737a', '2f585d0c-257b-51a9-a8dd-8a7b5cd1a1a0', 'The anode starts emitting electrons', 'C', false, 2),
('2ddd7d31-3cbf-5b71-97e9-2f1f72f763a0', '2f585d0c-257b-51a9-a8dd-8a7b5cd1a1a0', 'The work function increases', 'D', false, 3),
('503948e3-8703-598a-a39b-405d39d003d5', '227cd3ee-ebdf-5192-bd9a-1532668aeb20', 'Electrons from Q have the larger maximum kinetic energy', 'A', false, 0),
('cbd05ec0-b9ad-5775-85c1-25547f9cf32d', '227cd3ee-ebdf-5192-bd9a-1532668aeb20', 'Both give the same maximum kinetic energy', 'B', false, 1),
('240cc9f2-d1f3-513a-ae27-6a1eb6e39637', '227cd3ee-ebdf-5192-bd9a-1532668aeb20', 'Only Q emits electrons', 'C', false, 2),
('c0a7d7b4-f7e9-5e3e-b6da-1ee84e594a9a', '227cd3ee-ebdf-5192-bd9a-1532668aeb20', 'Electrons from P have the larger maximum kinetic energy', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('9255f302-1a37-55dd-a536-8252ebd414d0', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 7, 7, 'Calcium needs at least 2.9 eV to free an electron from its surface. What is the lowest frequency of light that can do this? Give your answer in units of 10¹⁴ Hz. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '6.998', '10¹⁴ Hz', false, NULL, false, NULL, 'f₀ = Φ/h = 2.9 × 1.60 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 7.00 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f₀ = Φ/h. A1: f₀ = 7.00 × 10¹⁴ Hz.', 2, NULL, NULL),
('1b1a830a-fce6-5b61-9247-f50c2f8bda96', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 8, 8, 'What is the threshold wavelength of a metal?', NULL, 1, 'multiple_choice'::answer_type, 'The longest wavelength of light that can release electrons from it', NULL, false, NULL, false, NULL, 'λ₀ = hc/Φ; longer wavelengths have photons with too little energy. Mark scheme (1 mark). B1: C (The longest wavelength of light that can release electrons from it).', 1, NULL, NULL),
('16bd48be-4f25-5c8a-8ba6-22985ee4cfb8', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 9, 9, 'A surface has a threshold frequency of 1.1 × 10¹⁵ Hz. Calculate its work function in eV. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4.558', 'eV', false, NULL, false, NULL, 'Φ = hf₀ = 6.63 × 10⁻³⁴ × 1.1 × 10¹⁵ ÷ 1.60 × 10⁻¹⁹ = 4.56 eV. Mark scheme (2 marks). C1: Φ = hf₀ in eV. A1: Φ = 4.56 eV.', 2, NULL, NULL),
('ef8f6202-4957-5ce1-8add-a163f3f8a127', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 10, 10, 'Which metal has the highest threshold frequency?', NULL, 1, 'multiple_choice'::answer_type, 'The one with the largest work function', NULL, false, NULL, false, NULL, 'f₀ = Φ/h, so a larger work function needs a higher-frequency photon. Mark scheme (1 mark). B1: A (The one with the largest work function).', 1, NULL, NULL),
('e3743241-7c1a-5a60-a383-903b7ba590fe', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 11, 11, 'A metal has a threshold wavelength of 680 nm. Calculate its threshold frequency in units of 10¹⁴ Hz. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '4.412', '10¹⁴ Hz', false, NULL, false, NULL, 'f₀ = c/λ₀ = 3.00 × 10⁸ ÷ 680 × 10⁻⁹ = 4.41 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f₀ = c/λ₀. A1: f₀ = 4.41 × 10¹⁴ Hz.', 2, NULL, NULL),
('3f13f124-6ee8-5f38-ab19-36b5624e5827', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 12, 12, 'Light of wavelength longer than the threshold wavelength falls on a metal. What happens?', NULL, 1, 'multiple_choice'::answer_type, 'No electrons are emitted, whatever the intensity', NULL, false, NULL, false, NULL, 'Each photon has less energy than Φ. Mark scheme (1 mark). B1: D (No electrons are emitted, whatever the intensity).', 1, NULL, NULL),
('d48832b1-cf33-5092-b14b-6b345340e587', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 13, 13, 'The work function of a metal is 3.6 × 10⁻¹⁹ J. Calculate its threshold frequency in units of 10¹⁴ Hz. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '5.43', '10¹⁴ Hz', false, NULL, false, NULL, 'f₀ = 3.6 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 5.43 × 10¹⁴ Hz. Mark scheme (2 marks). C1: f₀ = Φ/h. A1: f₀ = 5.43 × 10¹⁴ Hz.', 2, NULL, NULL),
('9c740489-34df-5ffc-9018-47afd6cc1c78', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 14, 14, 'Which equation links the work function Φ to the threshold frequency f₀?', NULL, 1, 'multiple_choice'::answer_type, 'Φ = hf₀', NULL, false, NULL, false, NULL, 'At threshold the photon energy just equals Φ. Mark scheme (1 mark). B1: B (Φ = hf₀).', 1, NULL, NULL),
('f167d470-66e4-5a48-aad8-f349d9173307', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 15, 15, 'A metal emits electrons only for light of frequency above 8.0 × 10¹⁴ Hz. Calculate the corresponding threshold wavelength in nm. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '375 nm', 'nm', false, NULL, false, NULL, 'λ₀ = c/f₀ = 3.00 × 10⁸ ÷ 8.0 × 10¹⁴ = 3.750 × 10⁻⁷ m. In nm: 3.750 × 10⁻⁷ × 10⁹ = 375. Mark scheme (2 marks). C1: λ₀ = c/f₀. A1: λ₀ = 375 nm.', 2, NULL, NULL),
('971e67b1-0ade-5f9d-8122-d417001932d0', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 16, 16, 'Increasing the intensity of light whose frequency is below the threshold frequency', NULL, 1, 'multiple_choice'::answer_type, 'still releases no electrons', NULL, false, NULL, false, NULL, 'Intensity changes photon numbers, not the energy of each photon. Mark scheme (1 mark). B1: C (still releases no electrons).', 1, NULL, NULL),
('220a6c87-3dac-5172-808f-d78639a21050', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 17, 17, 'Calculate the work function, in eV, of a metal whose threshold wavelength is 290 nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4.287', 'eV', false, NULL, false, NULL, 'Φ = hc/λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (290 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 4.29 eV. Mark scheme (2 marks). C1: Φ = hc/λ₀. A1: Φ = 4.29 eV.', 2, NULL, NULL),
('35142352-601d-50fb-9bcf-ec65a6a4fd5d', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 18, 18, 'In which unit is a work function often quoted?', NULL, 1, 'multiple_choice'::answer_type, 'eV', NULL, false, NULL, false, NULL, 'Φ is an energy, often given in electronvolts (1 eV = 1.60 × 10⁻¹⁹ J). Mark scheme (1 mark). B1: A (eV).', 1, NULL, NULL),
('1b9a8cfc-5027-5de0-94c7-f91d2adec2be', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 19, 19, 'A metal has a work function of 1.9 eV. Calculate its threshold wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '654.3 nm', 'nm', false, NULL, false, NULL, 'λ₀ = hc/Φ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.9 × 1.60 × 10⁻¹⁹) = 6.543 × 10⁻⁷ m. In nm: 6.543 × 10⁻⁷ × 10⁹ = 654. Mark scheme (2 marks). C1: λ₀ = hc/Φ. A1: λ₀ = 654 nm.', 2, NULL, NULL),
('f3678932-29c2-557f-a666-3179ee2fc1fc', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 20, 20, 'Metal X has a threshold wavelength of 500 nm and metal Y one of 300 nm. Which statement is correct?', NULL, 1, 'multiple_choice'::answer_type, 'Y has the larger work function', NULL, false, NULL, false, NULL, 'Φ = hc/λ₀: a shorter λ₀ means a larger Φ. Mark scheme (1 mark). B1: D (Y has the larger work function).', 1, NULL, NULL),
('b5894747-25ad-505b-b14a-19649381f7c6', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 21, 21, 'A metal has a threshold frequency of 5.0 × 10¹⁴ Hz. Calculate its work function in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '3.315', '10⁻¹⁹ J', false, NULL, false, NULL, 'Φ = hf₀ = 6.63 × 10⁻³⁴ × 5.0 × 10¹⁴ = 3.31 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: Φ = hf₀. A1: Φ = 3.31 × 10⁻¹⁹ J.', 2, NULL, NULL),
('14adb24b-5df2-57a2-8e28-82fba6bf51ad', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 22, 22, 'Which describes light exactly at the threshold frequency falling on a metal surface?', NULL, 1, 'multiple_choice'::answer_type, 'Electrons can just escape, with zero kinetic energy', NULL, false, NULL, false, NULL, 'hf₀ = Φ leaves nothing for kinetic energy. Mark scheme (1 mark). B1: B (Electrons can just escape, with zero kinetic energy).', 1, NULL, NULL),
('f6fb239b-49ff-5560-af44-601e8ad477cd', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 23, 23, 'A metal stops emitting electrons when the frequency of the light falls below 6.2 × 10¹⁴ Hz. What wavelength, in nm, does this frequency correspond to? Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '483.9 nm', 'nm', false, NULL, false, NULL, 'λ = c/f = 3.00 × 10⁸ ÷ 6.2 × 10¹⁴ = 4.839 × 10⁻⁷ m. In nm: 4.839 × 10⁻⁷ × 10⁹ = 484. Mark scheme (1 mark). A1: λ₀ = 484 nm.', 1, NULL, NULL),
('351e8dc8-8f31-5ce0-8283-7d18a45e44c9', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 24, 24, 'The table gives the work functions of five metals. Light of wavelength 450 nm falls on each in turn. How many of the metals emit photoelectrons? Caesium 2.1 eV, potassium 2.3 eV, sodium 2.4 eV, calcium 2.9 eV, zinc 4.3 eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3', NULL, false, NULL, false, NULL, 'Photon energy = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (450 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 2.76 eV. Only caesium, potassium and sodium have Φ below this, so the number is 1 + 1 + 1 = 3. Mark scheme (3 marks). C1: photon energy in eV. C1: compare with each Φ. A1: number = 3.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 184" role="img" aria-labelledby="fgcc4e6012-t fgcc4e6012-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgcc4e6012-t">Work functions</title><desc id="fgcc4e6012-d">Table of work functions: caesium 2.1 eV, potassium 2.3 eV, sodium 2.4 eV, calcium 2.9 eV and zinc 4.3 eV.</desc><rect x="53.8" y="8" width="252.4" height="168" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="53.8" y="8" width="252.4" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">metal</text><text x="228.2" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">work function / eV</text><line x1="150.2" y1="8" x2="150.2" y2="176" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="53.8" y1="36" x2="306.2" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Caesium</text><text x="228.2" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.1</text><line x1="53.8" y1="64" x2="306.2" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Potassium</text><text x="228.2" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.3</text><line x1="53.8" y1="92" x2="306.2" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Sodium</text><text x="228.2" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.4</text><line x1="53.8" y1="120" x2="306.2" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Calcium</text><text x="228.2" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.9</text><line x1="53.8" y1="148" x2="306.2" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="162" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Zinc</text><text x="228.2" y="162" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.3</text></svg>', 'Table of work functions: caesium 2.1 eV, potassium 2.3 eV, sodium 2.4 eV, calcium 2.9 eV and zinc 4.3 eV.'),
('934b2c60-8dd5-5b58-8bb7-4a04437546c7', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 25, 25, 'Show that ultraviolet radiation is needed to free electrons from zinc (work function 4.3 eV) by calculating its threshold wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '289.1 nm', 'nm', false, NULL, false, NULL, 'λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (4.3 × 1.60 × 10⁻¹⁹) = 2.891 × 10⁻⁷ m. In nm: 2.891 × 10⁻⁷ × 10⁹ = 289. Mark scheme (3 marks). C1: Φ in J. C1: λ₀ = hc/Φ. A1: λ₀ = 289 nm.', 3, NULL, NULL),
('207eefc3-caeb-5584-96c1-c883fc50acc4', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 26, 26, 'Light of wavelength just shorter than the threshold wavelength releases photoelectrons from a metal. The wavelength is then increased beyond the threshold. What happens?', NULL, 2, 'multiple_choice'::answer_type, 'Emission stops, because each photon now has less energy than the work function', NULL, false, NULL, false, NULL, 'Longer λ means smaller hf; below Φ no electron can escape. Mark scheme (3 marks). C1: E = hc/λ falls. C1: below Φ no emission. A1: C (Emission stops, because each photon now has less energy than the work function).', 3, NULL, NULL),
('325d9811-756e-59db-8742-d39397feb28b', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 27, 27, 'Light of wavelength 380 nm releases photoelectrons with a maximum kinetic energy of 0.60 eV. Calculate the threshold wavelength of the metal in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '465.3 nm', 'nm', false, NULL, false, NULL, 'hf = 3.271 eV, so Φ = 3.271 − 0.60 = 2.671 eV. λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.671 × 1.60 × 10⁻¹⁹) = 4.653 × 10⁻⁷ m. In nm: 4.653 × 10⁻⁷ × 10⁹ = 465. Mark scheme (4 marks). C1: photon energy. C1: Φ. C1: λ₀ = hc/Φ. A1: λ₀ = 465 nm.', 4, NULL, NULL),
('c10744f0-2b88-5ac0-bfad-47d7cdedaf6d', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 28, 28, 'The graph shows the maximum kinetic energy of photoelectrons against frequency for a metal; the line meets the frequency axis at 5.6 × 10¹⁴ Hz. Calculate the work function of the metal in eV. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.321', 'eV', false, NULL, false, NULL, 'Φ = hf₀ = 6.63 × 10⁻³⁴ × 5.6 × 10¹⁴ ÷ 1.60 × 10⁻¹⁹ = 2.32 eV. Mark scheme (3 marks). C1: f₀ from intercept. C1: Φ = hf₀. A1: Φ = 2.32 eV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg94fc9396-t fg94fc9396-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg94fc9396-t">Ek(max) against frequency</title><desc id="fg94fc9396-d">Graph of maximum kinetic energy against frequency for a metal: a straight line rising from the frequency axis at 5.6 × 10¹⁴ Hz.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="99.5" y1="34" x2="99.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166" y1="34" x2="166" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="232.4" y1="34" x2="232.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="298.9" y1="34" x2="298.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="365.4" y1="34" x2="365.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="99.5" y1="242" x2="99.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="99.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="166" y1="242" x2="166" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="166" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="232.4" y1="242" x2="232.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="298.9" y1="242" x2="298.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="365.4" y1="242" x2="365.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="365.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="190" x2="33" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="138" x2="33" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="86" x2="33" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">f / 10¹⁴ Hz</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Ek(max) / eV</text><line x1="219.2" y1="34" x2="219.2" y2="242" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="223.2" y="42" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">5.6</text><polyline points="219.2,242 365.4,52.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of maximum kinetic energy against frequency for a metal: a straight line rising from the frequency axis at 5.6 × 10¹⁴ Hz.'),
('d2943ff2-6ca4-57be-92eb-eec1630dd015', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 29, 29, 'Light of wavelength 600 nm releases no electrons from a metal. Which change could make it release electrons?', NULL, 2, 'multiple_choice'::answer_type, 'Using light of a shorter wavelength', NULL, false, NULL, false, NULL, 'Only raising the photon energy (shorter λ) can exceed Φ. Mark scheme (3 marks). C1: photon energy must exceed Φ. C1: shorter λ. A1: A (Using light of a shorter wavelength).', 3, NULL, NULL),
('af11f651-9029-5fa1-86eb-a53dcc934d87', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 30, 30, 'A metal has a work function of 2.6 eV. Light of wavelength 500 nm falls on it. By how many eV is the photon energy below the work function? Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '0.1138', 'eV', false, NULL, false, NULL, 'Photon energy = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (500 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 2.486 eV. Shortfall = 2.6 − 2.486 = 0.114 eV. Mark scheme (3 marks). C1: photon energy. C1: comparison. A1: shortfall = 0.114 eV.', 3, NULL, NULL),
('6ab9a1a3-3475-5bf0-bebc-154d8345b8d9', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 31, 31, 'A metal has a threshold wavelength of 260 nm. Calculate the maximum kinetic energy, in eV, of photoelectrons released by light of wavelength 200 nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.434', 'eV', false, NULL, false, NULL, 'Ek = hc/λ − hc/λ₀ = 6.216 − 4.781 = 1.43 eV. Mark scheme (3 marks). C1: Φ = hc/λ₀. C1: hf. A1: Ek(max) = 1.43 eV.', 3, NULL, NULL),
('7a90fad4-8b1a-59d8-a708-cd873768da62', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 32, 32, 'Graphs of Ek(max) against frequency are drawn for two different metals. How are the lines related?', NULL, 2, 'multiple_choice'::answer_type, 'They are parallel but cross the frequency axis at different points', NULL, false, NULL, false, NULL, 'Gradient = h for every metal; intercept f₀ = Φ/h differs. Mark scheme (3 marks). C1: same gradient h. C1: different f₀. A1: D (They are parallel but cross the frequency axis at different points).', 3, NULL, NULL),
('ca09badc-8349-5892-aa0a-58d3ba7a1b92', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 33, 33, 'A metal has a threshold frequency of 1.05 × 10¹⁵ Hz. Light of frequency 1.50 × 10¹⁵ Hz falls on it. Calculate the maximum kinetic energy of the photoelectrons in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.983', '10⁻¹⁹ J', false, NULL, false, NULL, 'Ek = h(f − f₀) = 6.63 × 10⁻³⁴ × (1.50 × 10¹⁵ − 1.05 × 10¹⁵) = 2.98 × 10⁻¹⁹ J. Mark scheme (4 marks). C1: Φ = hf₀. C1: Ek = hf − hf₀. C1: substitution. A1: Ek(max) = 2.98 × 10⁻¹⁹ J.', 4, NULL, NULL),
('30802fbb-a86e-5eb9-bd6a-19bd5fba098f', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 34, 34, 'How does the threshold frequency of a metal depend on the intensity of the light?', NULL, 2, 'multiple_choice'::answer_type, 'It does not depend on intensity at all', NULL, false, NULL, false, NULL, 'f₀ = Φ/h is a property of the metal surface. Mark scheme (3 marks). C1: f₀ = Φ/h. C1: independent of intensity. A1: B (It does not depend on intensity at all).', 3, NULL, NULL),
('99f1f76e-15e1-5883-8983-64484c85cd35', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 35, 35, 'Calculate (threshold wavelength of a metal with Φ = 2.0 eV) ÷ (threshold wavelength of a metal with Φ = 5.0 eV).', NULL, 2, 'numeric'::answer_type, '2.5', NULL, false, NULL, false, NULL, 'λ₀ = hc/Φ, so the ratio = 5.0 ÷ 2.0 = 2.5. Mark scheme (3 marks). C1: λ₀ ∝ 1/Φ. C1: ratio. A1: ratio = 2.5.', 3, NULL, NULL),
('51496249-5737-5f3d-8611-59236e23907f', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 36, 36, 'What is the longest wavelength of light, in nm, that can eject electrons from a surface of work function 3.2 × 10⁻¹⁹ J? Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '621.6 nm', 'nm', false, NULL, false, NULL, 'λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 3.2 × 10⁻¹⁹ = 6.216 × 10⁻⁷ m. In nm: 6.216 × 10⁻⁷ × 10⁹ = 622. Mark scheme (3 marks). C1: λ₀ = hc/Φ. C1: nm. A1: λ₀ = 622 nm.', 3, NULL, NULL),
('827ed829-9007-5387-9158-f97e3f23b682', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 37, 37, 'On a graph of Ek(max) against frequency, the line is extended back to cross the Ek axis. What does that intercept equal?', NULL, 2, 'multiple_choice'::answer_type, '−Φ, the negative of the work function', NULL, false, NULL, false, NULL, 'Ek = hf − Φ: at f = 0 the line gives −Φ. Mark scheme (4 marks). C1: y = mx + c form. C1: c = −Φ. C1: negative sign. A1: C (−Φ, the negative of the work function).', 4, NULL, NULL),
('73ff044a-5abf-5bdf-b3c1-af61f3a0a9a3', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 38, 38, 'Light of wavelength 350 nm falls on metal A, whose work function is 2.2 eV. Calculate the maximum speed of the photoelectrons in units of 10⁵ m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹, e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '6.891', '10⁵ m s⁻¹', false, NULL, false, NULL, 'hf = 3.552 eV; Ek = 1.352 eV = 2.163 × 10⁻¹⁹ J. v = √(2 × 2.163 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹) = 6.89 × 10⁵ m s⁻¹. Mark scheme (4 marks). C1: photon energy. C1: Ek(max). C1: v = √(2Ek/m). A1: v = 6.89 × 10⁵ m s⁻¹.', 4, NULL, NULL),
('e6f36e17-373a-514f-aeec-3e75bd0fde7a', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 39, 39, 'A metal has a threshold frequency of 6.0 × 10¹⁴ Hz. Light of frequency 9.0 × 10¹⁴ Hz falls on it. Calculate the stopping potential. Take h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.243', 'V', false, NULL, false, NULL, 'eV_s = h(f − f₀), so V_s = 6.63 × 10⁻³⁴ × 3.0 × 10¹⁴ ÷ 1.60 × 10⁻¹⁹ = 1.24 V. Mark scheme (3 marks). C1: h(f − f₀). C1: ÷ e. A1: V_s = 1.24 V.', 3, NULL, NULL),
('2108d9df-8f7d-59e6-bd77-6e4a3b037834', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 40, 40, 'Light of frequency only slightly above the threshold frequency falls on a metal. Which statement is correct?', NULL, 2, 'multiple_choice'::answer_type, 'Electrons are emitted, but the fastest have very little kinetic energy', NULL, false, NULL, false, NULL, 'Ek(max) = h(f − f₀) is small but positive. Mark scheme (3 marks). C1: emission occurs. C1: Ek small. A1: A (Electrons are emitted, but the fastest have very little kinetic energy).', 3, NULL, NULL),
('daaa57fb-0e4c-535d-868e-5be85e74c697', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 41, 41, 'A metal has a threshold wavelength of 550 nm. Calculate its work function in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.616', '10⁻¹⁹ J', false, NULL, false, NULL, 'Φ = hc/λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 550 × 10⁻⁹ = 3.62 × 10⁻¹⁹ J. Mark scheme (3 marks). C1: Φ = hc/λ₀. C1: nm to m. A1: Φ = 3.62 × 10⁻¹⁹ J.', 3, NULL, NULL),
('1d1df6e6-0b01-59cb-8cf7-0bc548fddf27', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 42, 42, 'Why can light below the threshold frequency never release electrons, however long it shines?', NULL, 2, 'multiple_choice'::answer_type, 'Each electron absorbs one whole photon, and one photon has less energy than Φ', NULL, false, NULL, false, NULL, 'Photon absorption is all-or-nothing and one photon per electron. Mark scheme (3 marks). C1: one photon per electron. C1: hf < Φ. A1: D (Each electron absorbs one whole photon, and one photon has less energy than Φ).', 3, NULL, NULL),
('09adbe12-6968-5f45-afb0-72a03dbab2ca', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 43, 43, 'Caesium has a work function of 2.1 eV. (a) Calculate its threshold wavelength in nm. (b) Visible light runs from 400 nm to 700 nm. Calculate the fraction of this range of wavelengths that can release photoelectrons from caesium. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.6399', NULL, false, NULL, false, NULL, '(a) λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.1 × 1.60 × 10⁻¹⁹) = 5.920 × 10⁻⁷ m, which is 592.0 nm. (b) Wavelengths from 400 nm to 592 nm work: fraction = (592.0 − 400) ÷ 300 = 0.640. Mark scheme (5 marks). C1: λ₀ = hc/Φ. C1: value. M1: range shorter than λ₀. C1: fraction. A1: fraction = 0.640.', 5, NULL, NULL),
('30eb1169-8d12-54b7-81a4-6824b01bfdf2', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 44, 44, 'For a metal, Ek(max) = 0.80 eV with light of 7.5 × 10¹⁴ Hz and 1.84 eV with light of 1.00 × 10¹⁵ Hz. (a) Calculate the gradient of the Ek–f graph in eV per Hz. (b) Hence find h. (c) Find the threshold frequency. Give only the answer to (c), in units of 10¹⁴ Hz. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '5.577', '10¹⁴ Hz', false, NULL, false, NULL, '(a) Gradient = (1.84 − 0.80) ÷ 2.5 × 10¹⁴ = 4.160 × 10⁻¹⁵ eV Hz⁻¹. (b) h = 4.160 × 10⁻¹⁵ × 1.60 × 10⁻¹⁹ = 6.66 × 10⁻³⁴ J s. (c) f₀ = 7.5 × 10¹⁴ − 0.80 ÷ 4.160 × 10⁻¹⁵ = 5.58 × 10¹⁴ Hz. Mark scheme (6 marks). C1: gradient. C1: h in J s. M1: Ek = 0 at f₀. C1: substitution. C1: value. A1: f₀ = 5.58 × 10¹⁴ Hz.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fgc93b20a3-t fgc93b20a3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc93b20a3-t">Two measurements</title><desc id="fgc93b20a3-d">Graph of maximum kinetic energy against frequency with two measured points: 0.80 eV at 7.5 × 10¹⁴ Hz and 1.84 eV at 1.00 × 10¹⁵ Hz.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="96.5" y1="34" x2="96.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="159.9" y1="34" x2="159.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="223.4" y1="34" x2="223.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="286.8" y1="34" x2="286.8" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="350.3" y1="34" x2="350.3" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="190" x2="382" y2="190" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="138" x2="382" y2="138" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="86" x2="382" y2="86" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="96.5" y1="242" x2="96.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="96.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="159.9" y1="242" x2="159.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="159.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="223.4" y1="242" x2="223.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="223.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="286.8" y1="242" x2="286.8" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="286.8" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="350.3" y1="242" x2="350.3" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="350.3" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="190" x2="33" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="190" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="138" x2="33" y2="138" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="138" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="86" x2="33" y2="86" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="86" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.0</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">f / 10¹⁴ Hz</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Ek(max) / eV</text><line x1="267" y1="154.8" x2="275" y2="162.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="267" y1="162.8" x2="275" y2="154.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="46.6" x2="354.3" y2="54.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="346.3" y1="54.6" x2="354.3" y2="46.6" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of maximum kinetic energy against frequency with two measured points: 0.80 eV at 7.5 × 10¹⁴ Hz and 1.84 eV at 1.00 × 10¹⁵ Hz.'),
('33b6d336-bd9d-534f-bea2-fbde87eebfbe', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 45, 45, 'A mercury lamp gives ultraviolet light of wavelength 254 nm. It falls in turn on potassium (Φ = 2.3 eV), magnesium (Φ = 3.7 eV) and platinum (Φ = 6.4 eV). (a) Calculate the photon energy in eV. (b) State which metals emit electrons. (c) Calculate the maximum kinetic energy of the electrons from magnesium, in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.194', 'eV', false, NULL, false, NULL, '(a) 4.894 eV. (b) Potassium and magnesium; platinum needs 6.4 eV. (c) Ek = 4.894 − 3.7 = 1.19 eV. Mark scheme (5 marks). C1: photon energy. B1: comparison with each Φ. M1: Ek = hf − Φ. C1: value. A1: Ek(max) = 1.19 eV.', 5, NULL, NULL),
('530c26dd-bc58-5ad3-b614-3c5ce1c80555', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 46, 46, 'Light of wavelength 300 nm gives photoelectrons with a stopping potential of 1.20 V. (a) Calculate the photon energy in eV. (b) Calculate the work function. (c) Calculate the threshold wavelength in nm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '422.3 nm', 'nm', false, NULL, false, NULL, '(a) 4.144 eV. (b) Φ = 4.144 − 1.20 = 2.944 eV. (c) λ₀ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.944 × 1.60 × 10⁻¹⁹) = 4.223 × 10⁻⁷ m. In nm: 4.223 × 10⁻⁷ × 10⁹ = 422. Mark scheme (6 marks). C1: photon energy. C1: Φ = hf − eV_s. M1: λ₀ = hc/Φ. C1: J conversion. C1: value. A1: λ₀ = 422 nm.', 6, NULL, NULL),
('66fbaeaf-358c-5c3f-9fab-978ffccfce98', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 47, 47, 'Caesium has a threshold frequency of 4.5 × 10¹⁴ Hz. Infrared radiation of wavelength 1000 nm falls on it. (a) Calculate the frequency of the radiation. (b) Explain why no electrons are emitted. (c) Calculate the work function of caesium in eV. Take c = 3.00 × 10⁸ m s⁻¹, h = 6.63 × 10⁻³⁴ J s and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.865', 'eV', false, NULL, false, NULL, '(a) f = 3.00 × 10⁸ ÷ 1000 × 10⁻⁹ = 3.0 × 10¹⁴ Hz. (b) It is below f₀, so each photon has less energy than Φ. (c) Φ = 6.63 × 10⁻³⁴ × 4.5 × 10¹⁴ ÷ 1.60 × 10⁻¹⁹ = 1.86 eV. Mark scheme (5 marks). C1: f = c/λ. B1: f < f₀. M1: Φ = hf₀. C1: value. A1: Φ = 1.86 eV.', 5, NULL, NULL),
('d7be322a-a36c-5d77-b42b-ebeccfea9c85', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 48, 48, 'Light of wavelength 600 nm releases photoelectrons from a metal. Light of 300 nm releases photoelectrons whose maximum kinetic energy is three times as large. (a) Calculate the photon energy for each wavelength in eV. (b) Write an equation linking the two kinetic energies and Φ. (c) Calculate Φ in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.036', 'eV', false, NULL, false, NULL, '(a) 2.072 eV and 4.144 eV. (b) 4.144 − Φ = 3(2.072 − Φ). (c) 2Φ = 3 × 2.072 − 4.144, so Φ = (3 × 2.072 − 4.144) ÷ 2 = 1.04 eV. Mark scheme (6 marks). C1: both photon energies. B1: equation. M1: rearranged for Φ. C1: substitution. C1: value. A1: Φ = 1.04 eV.', 6, NULL, NULL),
('8b8307ae-95ff-5a63-9269-486d026b1045', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 49, 49, 'A graph of stopping potential against frequency has a gradient of 4.1 × 10⁻¹⁵ V s and meets the frequency axis at 5.2 × 10¹⁴ Hz. (a) Show that the gradient equals h/e. (b) Calculate h. (c) Calculate the work function in eV. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2.132', 'eV', false, NULL, false, NULL, '(a) eV_s = hf − Φ gives V_s = (h/e)f − Φ/e. (b) h = 4.1 × 10⁻¹⁵ × 1.60 × 10⁻¹⁹ = 6.56 × 10⁻³⁴ J s. (c) Φ/e = gradient × f₀ = 4.1 × 10⁻¹⁵ × 5.2 × 10¹⁴ = 2.13 V, so Φ = 2.13 eV. Mark scheme (5 marks). B1: gradient h/e. C1: h. M1: Φ = (h/e)f₀ in eV. C1: value. A1: Φ = 2.13 eV.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 290" role="img" aria-labelledby="fg4ce15fa2-t fg4ce15fa2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4ce15fa2-t">Stopping potential against frequency</title><desc id="fg4ce15fa2-d">Graph of stopping potential against frequency: a straight line of gradient 4.1 × 10⁻¹⁵ V s meeting the frequency axis at 5.2 × 10¹⁴ Hz.</desc><line x1="33" y1="34" x2="33" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="99.5" y1="34" x2="99.5" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="166" y1="34" x2="166" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="232.4" y1="34" x2="232.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="298.9" y1="34" x2="298.9" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="365.4" y1="34" x2="365.4" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="382" y2="242" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="200.4" x2="382" y2="200.4" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="158.8" x2="382" y2="158.8" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="117.2" x2="382" y2="117.2" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="75.6" x2="382" y2="75.6" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="34" x2="382" y2="34" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="388" y2="242" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="33" y1="242" x2="33" y2="28" style="stroke:currentColor;stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="392,242 385.7,245 385.7,239" style="fill:currentColor;stroke:none"/><polygon points="33,24 36,30.3 30.1,30.3" style="fill:currentColor;stroke:none"/><line x1="33" y1="242" x2="33" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="33" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="99.5" y1="242" x2="99.5" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="99.5" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2</text><line x1="166" y1="242" x2="166" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="166" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4</text><line x1="232.4" y1="242" x2="232.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="232.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">6</text><line x1="298.9" y1="242" x2="298.9" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298.9" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">8</text><line x1="365.4" y1="242" x2="365.4" y2="246" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="365.4" y="254" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">10</text><line x1="29" y1="242" x2="33" y2="242" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="242" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="29" y1="200.4" x2="33" y2="200.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="200.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0.5</text><line x1="29" y1="158.8" x2="33" y2="158.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="158.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.0</text><line x1="29" y1="117.2" x2="33" y2="117.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="117.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1.5</text><line x1="29" y1="75.6" x2="33" y2="75.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="75.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.0</text><line x1="29" y1="34" x2="33" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="26" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2.5</text><text x="207.5" y="274" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">f / 10¹⁴ Hz</text><text x="29" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Vₛ / V</text><line x1="205.9" y1="34" x2="205.9" y2="242" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="209.9" y="42" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">5.2</text><polyline points="205.9,242 365.4,78.3" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/></svg>', 'Graph of stopping potential against frequency: a straight line of gradient 4.1 × 10⁻¹⁵ V s meeting the frequency axis at 5.2 × 10¹⁴ Hz.'),
('75eb6388-c567-57cc-bcb0-e07d123fffeb', '7d22edfc-44c4-4846-9769-292936cb7827', '41988582-a22a-4110-ad60-63bc462aa69a', 'a-level', '28.4', '9702 coursebook 28.4 · Threshold frequency and wavelength', 50, 50, 'Two lasers of equal power, one violet (400 nm) and one red (600 nm), shine in turn on a metal of work function 1.9 eV. Each photon has the same chance of releasing an electron. (a) Show that both lasers release electrons. (b) Calculate Ek(max) for the violet laser in eV. (c) Calculate (photocurrent with red) ÷ (photocurrent with violet). Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.5', NULL, false, NULL, false, NULL, '(a) Photon energies 3.108 eV and 2.072 eV, both above 1.9 eV. (b) 3.108 − 1.9 = 1.21 eV. (c) Photon rate = P/E ∝ λ, so ratio = 600 ÷ 400 = 1.5. Mark scheme (6 marks). C1: both photon energies. B1: both above Φ. C1: Ek(max). M1: n ∝ λ for equal power. C1: ratio. A1: ratio = 1.5.', 6, NULL, NULL)
