('52c89c30-fb96-53d7-a927-9f1a9e27153b', '14adb24b-5df2-57a2-8e28-82fba6bf51ad', 'Electrons escape with the maximum possible speed', 'A', false, 0),
('e5758422-30c0-5641-a7b4-f49da19bbdfd', '14adb24b-5df2-57a2-8e28-82fba6bf51ad', 'Electrons can just escape, with zero kinetic energy', 'B', true, 1),
