('8ccd3ecf-5fd7-54dc-8d37-073222e0bc0d', '207eefc3-caeb-5584-96c1-c883fc50acc4', 'Emission stops, because each photon now has less energy than the work function', 'C', true, 2),
('4794f22d-84a5-55fa-a3b2-876c3f377857', '207eefc3-caeb-5584-96c1-c883fc50acc4', 'Emission stops only if the intensity is reduced', 'D', false, 3),
('0d4f8641-532e-5fb6-a711-2a3daabe8743', 'd2943ff2-6ca4-57be-92eb-eec1630dd015', 'Using light of a shorter wavelength', 'A', true, 0),
('a42033e4-9cbd-526a-9f4c-09fe980191b0', 'd2943ff2-6ca4-57be-92eb-eec1630dd015', 'Using a brighter 600 nm source', 'B', false, 1),
('e1a9f589-6e97-5e78-a8b0-fcdfbcd9841b', 'd2943ff2-6ca4-57be-92eb-eec1630dd015', 'Shining the light for longer', 'C', false, 2),
('f17e6741-6368-5bf2-a0d4-2093e3e83579', 'd2943ff2-6ca4-57be-92eb-eec1630dd015', 'Using light of a longer wavelength', 'D', false, 3),
('94313442-d609-5d8d-a7e6-5e2ec4bf2f4a', '7a90fad4-8b1a-59d8-a708-cd873768da62', 'They have different gradients but the same intercept', 'A', false, 0),
('8eb985e2-3a89-5ac8-9f9f-c13a81d8eaef', '7a90fad4-8b1a-59d8-a708-cd873768da62', 'They are identical', 'B', false, 1),
('bc939885-4822-5bdf-9d66-37cb5f7ca435', '7a90fad4-8b1a-59d8-a708-cd873768da62', 'They are perpendicular', 'C', false, 2),
('6064598a-fbec-59a9-a9dc-ddb3daa156c6', '7a90fad4-8b1a-59d8-a708-cd873768da62', 'They are parallel but cross the frequency axis at different points', 'D', true, 3),
('051374ee-a220-5b7d-8a08-492b0b9b9cb2', '30802fbb-a86e-5eb9-bd6a-19bd5fba098f', 'It falls as the intensity rises', 'A', false, 0),
('1c06be5d-bc2b-5221-ae97-e33ab95f7b4a', '30802fbb-a86e-5eb9-bd6a-19bd5fba098f', 'It does not depend on intensity at all', 'B', true, 1),
('66fa00c5-1324-58a5-ad18-02b568690d87', '30802fbb-a86e-5eb9-bd6a-19bd5fba098f', 'It rises as the intensity rises', 'C', false, 2),
('2d29f805-2b3e-51ae-909d-5876501cb61e', '30802fbb-a86e-5eb9-bd6a-19bd5fba098f', 'It is proportional to the intensity', 'D', false, 3),
('b0d71d65-0bc5-5754-b8a8-a2b9123d8397', '827ed829-9007-5387-9158-f97e3f23b682', '+Φ', 'A', false, 0),
('5e1fb8db-ca30-57cd-a5b5-0d82a149670e', '827ed829-9007-5387-9158-f97e3f23b682', 'Zero', 'B', false, 1),
('6eceec2f-7d03-5065-ba27-cf33b0537e83', '827ed829-9007-5387-9158-f97e3f23b682', '−Φ, the negative of the work function', 'C', true, 2),
('7d3d32be-def3-575b-a00e-e54a85e29348', '827ed829-9007-5387-9158-f97e3f23b682', 'The threshold frequency', 'D', false, 3),
('3a0f4596-fe06-5570-ab58-1c9052eff184', '2108d9df-8f7d-59e6-bd77-6e4a3b037834', 'Electrons are emitted, but the fastest have very little kinetic energy', 'A', true, 0),
('de14d1e7-db9f-5937-9ccb-7e50ebb1fbc7', '2108d9df-8f7d-59e6-bd77-6e4a3b037834', 'No electrons are emitted', 'B', false, 1),
('fb18f7cd-13fe-56e5-a74d-93438ee911cd', '2108d9df-8f7d-59e6-bd77-6e4a3b037834', 'Electrons are emitted with large kinetic energies', 'C', false, 2),
('c009e6e8-c14d-5422-9d4f-22476d7db7ce', '2108d9df-8f7d-59e6-bd77-6e4a3b037834', 'Electrons are emitted only after a delay', 'D', false, 3),
('f4ff37e0-065b-5728-9278-45e2ecd00cd6', '1d1df6e6-0b01-59cb-8cf7-0bc548fddf27', 'The light is reflected', 'A', false, 0),
('7c3f1768-b373-55af-bf51-948848c86357', '1d1df6e6-0b01-59cb-8cf7-0bc548fddf27', 'The electrons absorb energy too slowly', 'B', false, 1),
('cdebbf88-3273-5329-af00-65c1f609c3fb', '1d1df6e6-0b01-59cb-8cf7-0bc548fddf27', 'The metal cools down', 'C', false, 2),
('2f45ed9a-aeee-54bf-a3dd-9212cea8f7a1', '1d1df6e6-0b01-59cb-8cf7-0bc548fddf27', 'Each electron absorbs one whole photon, and one photon has less energy than Φ', 'D', true, 3)
INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('b20847e4-82f1-558a-9aba-f9043890669b', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 7, 7, 'Calculate the momentum of a photon of deep red light of wavelength 700 nm, in units of 10⁻²⁷ kg m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '0.9471', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'p = h/λ = 6.63 × 10⁻³⁴ ÷ 700 × 10⁻⁹ = 9.47 × 10⁻²⁸ kg m s⁻¹. Mark scheme (2 marks). C1: p = h/λ. A1: p = 0.947 × 10⁻²⁷ kg m s⁻¹.', 2, NULL, NULL),
('35e72a8a-abd7-50d2-bc53-26a07b5a29f6', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 8, 8, 'Which expression gives the momentum of a photon of wavelength λ?', NULL, 1, 'multiple_choice'::answer_type, 'h/λ', NULL, false, NULL, false, NULL, 'The de Broglie relation applies to photons: p = h/λ. Mark scheme (1 mark). B1: C (h/λ).', 1, NULL, NULL),
('46abeecf-fcfb-5699-9d45-d6c288077892', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 9, 9, 'A photon has a momentum of 3.3 × 10⁻²⁷ kg m s⁻¹. What is its wavelength in nm? Take h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '200.9 nm', 'nm', false, NULL, false, NULL, 'λ = h/p = 6.63 × 10⁻³⁴ ÷ 3.3 × 10⁻²⁷ = 2.009 × 10⁻⁷ m. In nm: 2.009 × 10⁻⁷ × 10⁹ = 201. Mark scheme (2 marks). C1: λ = h/p. A1: λ = 201 nm.', 2, NULL, NULL),
('f39954b2-6492-5a7d-880c-6444ab622376', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 10, 10, 'A photon of momentum p is reflected straight back from a mirror. What is the size of the change in its momentum?', NULL, 1, 'multiple_choice'::answer_type, '2p', NULL, false, NULL, false, NULL, 'Momentum goes from +p to −p. Mark scheme (1 mark). B1: A (2p).', 1, NULL, NULL),
('6e101c9f-ec4c-5e9f-9a1d-1451f1b138e9', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 11, 11, 'A photon of extreme ultraviolet light has an energy of 2.0 × 10⁻¹⁸ J. Calculate its momentum in units of 10⁻²⁷ kg m s⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '6.667', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'p = E/c = 2.0 × 10⁻¹⁸ ÷ 3.00 × 10⁸ = 6.67 × 10⁻²⁷ kg m s⁻¹. Mark scheme (2 marks). C1: p = E/c. A1: p = 6.67 × 10⁻²⁷ kg m s⁻¹.', 2, NULL, NULL),
('6beba388-4c73-55fb-98ae-6b4768adef10', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 12, 12, 'A beam of light of power P is completely absorbed by a surface. What force does it exert?', NULL, 1, 'multiple_choice'::answer_type, 'P/c', NULL, false, NULL, false, NULL, 'Momentum arrives at a rate (P/c) per second. Mark scheme (1 mark). B1: D (P/c).', 1, NULL, NULL),
('a09aca28-258b-57fe-bd02-7f6e08872dde', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 13, 13, 'A 3.0 W beam of light is completely absorbed by a black surface. Calculate the force on the surface in units of 10⁻⁸ N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '1', '10⁻⁸ N', false, NULL, false, NULL, 'F = P/c = 3.0 ÷ 3.00 × 10⁸ = 1.0 × 10⁻⁸ N. Mark scheme (2 marks). C1: F = P/c. A1: F = 1.0 × 10⁻⁸ N.', 2, NULL, NULL),
('a0831f71-57c5-538e-bbf8-ddfc906290ce', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 14, 14, 'Which photon has the greater momentum?', NULL, 1, 'multiple_choice'::answer_type, 'An X-ray photon', NULL, false, NULL, false, NULL, 'p = h/λ, and X-rays have the shortest wavelength. Mark scheme (1 mark). B1: B (An X-ray photon).', 1, NULL, NULL),
('e56666ef-f7ca-5ddb-86a0-d701a6e2e1b6', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 15, 15, 'A 6.0 W laser beam is reflected straight back by a mirror. Calculate the force on the mirror in units of 10⁻⁸ N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '4', '10⁻⁸ N', false, NULL, false, NULL, 'F = 2P/c = 2 × 6.0 ÷ 3.00 × 10⁸ = 4.0 × 10⁻⁸ N. Mark scheme (2 marks). C1: F = 2P/c for reflection. A1: F = 4.0 × 10⁻⁸ N.', 2, NULL, NULL),
('63a41910-94ed-57a4-b55d-c99d3bc4f847', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 16, 16, 'A light vane spinning in a near-vacuum is often used to suggest that light pushes on surfaces. Which property of photons does radiation pressure depend on?', NULL, 1, 'multiple_choice'::answer_type, 'Their momentum', NULL, false, NULL, false, NULL, 'Photons carry momentum p = h/λ even though they have no mass. Mark scheme (1 mark). B1: C (Their momentum).', 1, NULL, NULL),
('e5c87fc8-e584-546b-86b8-443f89fc10d8', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 17, 17, 'An X-ray photon has an energy of 10 keV. Calculate its momentum in units of 10⁻²⁴ kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '5.333', '10⁻²⁴ kg m s⁻¹', false, NULL, false, NULL, 'E = 10 × 10³ × 1.60 × 10⁻¹⁹ = 1.6 × 10⁻¹⁵ J. p = 1.6 × 10⁻¹⁵ ÷ 3.00 × 10⁸ = 5.33 × 10⁻²⁴ kg m s⁻¹. Mark scheme (2 marks). C1: keV to J then p = E/c. A1: p = 5.33 × 10⁻²⁴ kg m s⁻¹.', 2, NULL, NULL),
('ebdac511-dc06-5dfd-b2cd-5c1515e11f7a', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 18, 18, 'How does the momentum of a photon depend on its wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'It is inversely proportional to the wavelength', NULL, false, NULL, false, NULL, 'p = h/λ, so halving the wavelength doubles the momentum. Mark scheme (1 mark). B1: A (It is inversely proportional to the wavelength).', 1, NULL, NULL),
('2c6b2565-dbd4-5f2e-bdab-23cc9a644485', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 19, 19, 'Each second, 2.4 × 10¹⁷ photons, each of momentum 1.1 × 10⁻²⁷ kg m s⁻¹, are absorbed by a target. Calculate the force on the target in units of 10⁻¹⁰ N.', NULL, 1, 'numeric'::answer_type, '2.64', '10⁻¹⁰ N', false, NULL, false, NULL, 'F = (photons per second) × p = 2.4 × 10¹⁷ × 1.1 × 10⁻²⁷ = 2.64 × 10⁻¹⁰ N. Mark scheme (2 marks). C1: F = rate of momentum transfer. A1: F = 2.64 × 10⁻¹⁰ N.', 2, NULL, NULL),
('89c04875-f05f-5844-9ede-ee0acdb23a54', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 20, 20, 'Which unit is equivalent to kg m s⁻¹, the unit of photon momentum?', NULL, 1, 'multiple_choice'::answer_type, 'N s', NULL, false, NULL, false, NULL, 'Impulse (N s) and momentum share the same unit. Mark scheme (1 mark). B1: D (N s).', 1, NULL, NULL),
('f1b0c189-6c27-5109-8a35-ce70e367a306', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 21, 21, 'Calculate (momentum of a 400 nm photon) ÷ (momentum of an 800 nm photon).', NULL, 1, 'numeric'::answer_type, '2', NULL, false, NULL, false, NULL, 'p ∝ 1/λ, so ratio = 800 ÷ 400 = 2.0. Mark scheme (2 marks). C1: p = h/λ. A1: ratio = 2.0.', 2, NULL, NULL),
('58d09e6a-692c-597d-88b2-e958a6249fc0', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 22, 22, 'The same beam of light falls on a perfectly reflecting surface and then on a perfectly absorbing one. How does the force compare?', NULL, 1, 'multiple_choice'::answer_type, 'The force on the reflecting surface is twice as large', NULL, false, NULL, false, NULL, 'Reflection reverses each photon''s momentum, a change of 2p. Mark scheme (1 mark). B1: B (The force on the reflecting surface is twice as large).', 1, NULL, NULL),
('62d23ac9-81db-528c-a3f8-77871d82f772', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 23, 23, 'A photon has a momentum of 2.2 × 10⁻²⁷ kg m s⁻¹. Calculate its energy in units of 10⁻¹⁹ J. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 1, 'numeric'::answer_type, '6.6', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = pc = 2.2 × 10⁻²⁷ × 3.00 × 10⁸ = 6.60 × 10⁻¹⁹ J. Mark scheme (1 mark). A1: E = 6.6 × 10⁻¹⁹ J.', 1, NULL, NULL),
('5b23c6e2-c79e-5774-a48e-a32507d06853', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 24, 24, 'A 1.0 mW laser beam is completely absorbed by a target. Calculate the force on the target in units of 10⁻¹² N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.333', '10⁻¹² N', false, NULL, false, NULL, 'F = P/c = 1.0 × 10⁻³ ÷ 3.00 × 10⁸ = 3.33 × 10⁻¹² N. Mark scheme (3 marks). C1: F = P/c. C1: mW to W. A1: F = 3.33 × 10⁻¹² N.', 3, NULL, NULL),
('837c0af9-de69-574c-ab2a-b4ef6e76954f', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 25, 25, 'Sunlight of intensity 1.36 kW m⁻² falls at right angles on a 1.0 m² black panel in space. Calculate the force of the light on the panel in units of 10⁻⁶ N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '4.533', '10⁻⁶ N', false, NULL, false, NULL, 'P = 1.36 × 10³ × 1.0 = 1360 W. F = 1360 ÷ 3.00 × 10⁸ = 4.53 × 10⁻⁶ N. Mark scheme (3 marks). C1: P = IA. C1: F = P/c. A1: F = 4.53 × 10⁻⁶ N.', 3, NULL, NULL),
('daa96dd5-4b68-564b-bb9f-14dcd6c4c31a', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 26, 26, 'A 2.0 W laser emits light of wavelength 450 nm, all absorbed by a target. (a) Calculate the photon momentum. (b) Calculate the photons per second. Give the force on the target in units of 10⁻⁹ N. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '6.667', '10⁻⁹ N', false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 450 × 10⁻⁹ = 1.473 × 10⁻²⁷ kg m s⁻¹. n = 2.0 ÷ 4.420 × 10⁻¹⁹ = 4.525 × 10¹⁸ s⁻¹. F = 4.525 × 10¹⁸ × 1.473 × 10⁻²⁷ = 6.67 × 10⁻⁹ N. Mark scheme (4 marks). C1: photon momentum. C1: photon rate. C1: F = np. A1: F = 6.67 × 10⁻⁹ N.', 4, NULL, NULL),
('78882bb0-d3de-5c9c-a69c-a757d1c6b125', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 27, 27, 'Why is a solar sail made from a highly reflective material rather than a black one?', NULL, 2, 'multiple_choice'::answer_type, 'Reflected photons change momentum by 2p, giving twice the force', NULL, false, NULL, false, NULL, 'Δp = 2p on reflection, p on absorption. Mark scheme (3 marks). C1: Δp = 2p reflected. C1: force doubled. A1: C (Reflected photons change momentum by 2p, giving twice the force).', 3, NULL, NULL),
('bf20093f-231b-564d-ba9f-f99d07b7f4a5', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 28, 28, 'Light of intensity 1.0 kW m⁻² is absorbed by a surface at normal incidence. Calculate the radiation pressure in units of 10⁻⁶ Pa. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.333', '10⁻⁶ Pa', false, NULL, false, NULL, 'p = I/c = 1.0 × 10³ ÷ 3.00 × 10⁸ = 3.33 × 10⁻⁶ Pa. Mark scheme (3 marks). C1: pressure = F/A = I/c. C1: value. A1: pressure = 3.33 × 10⁻⁶ Pa.', 3, NULL, NULL),
('231e82c9-adb2-5ed7-a798-58d0c414d8a8', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 29, 29, 'Find the wavelength, in nm, of a photon whose momentum equals that of an electron moving at 2.0 × 10⁶ m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 2, 'numeric'::answer_type, '0.3639 nm', 'nm', false, NULL, false, NULL, 'p = 9.11 × 10⁻³¹ × 2.0 × 10⁶ = 1.822 × 10⁻²⁴ kg m s⁻¹. λ = 6.63 × 10⁻³⁴ ÷ 1.822 × 10⁻²⁴ = 3.639 × 10⁻¹⁰ m. In nm: 3.639 × 10⁻¹⁰ × 10⁹ = 0.364. Mark scheme (3 marks). C1: p = mv. C1: λ = h/p. A1: λ = 0.364 nm.', 3, NULL, NULL),
('6c760ae4-6981-513a-9dcd-7ddb9b7701cf', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 30, 30, 'A photon and an electron have the same momentum. Which has the greater energy (for an electron moving much slower than light)?', NULL, 2, 'multiple_choice'::answer_type, 'The photon', NULL, false, NULL, false, NULL, 'Photon E = pc; electron E = p²/2m = (pv)/2, and v ≪ c. Mark scheme (3 marks). C1: E = pc for photon. C1: E = p²/2m much smaller. A1: A (The photon).', 3, NULL, NULL),
('9e8a0063-02d9-504a-9c62-31aed45e4f14', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 31, 31, 'A photon has a momentum of 5.0 × 10⁻²⁸ kg m s⁻¹. Calculate its frequency in units of 10¹⁴ Hz. Take c = 3.00 × 10⁸ m s⁻¹ and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.262', '10¹⁴ Hz', false, NULL, false, NULL, 'E = pc = 5.0 × 10⁻²⁸ × 3.00 × 10⁸ = 1.5 × 10⁻¹⁹ J. f = E/h = 1.5 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 2.26 × 10¹⁴ Hz. Mark scheme (4 marks). C1: E = pc. C1: f = E/h. C1: value. A1: f = 2.26 × 10¹⁴ Hz.', 4, NULL, NULL),
('e294c4d0-94d4-5c6f-8d42-fee090d95c04', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 32, 32, 'A blue LED emits photons of 3.0 eV. What momentum does each photon carry away from the LED? Give the answer in units of 10⁻²⁷ kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '1.6', '10⁻²⁷ kg m s⁻¹', false, NULL, false, NULL, 'E = 3.0 × 1.60 × 10⁻¹⁹ = 4.8 × 10⁻¹⁹ J. p = 4.8 × 10⁻¹⁹ ÷ 3.00 × 10⁸ = 1.60 × 10⁻²⁷ kg m s⁻¹. Mark scheme (3 marks). C1: eV to J. C1: p = E/c. A1: p = 1.60 × 10⁻²⁷ kg m s⁻¹.', 3, NULL, NULL),
('bcdb38e3-729c-5da4-8093-675cd431675b', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 33, 33, 'An isolated atom at rest emits a photon. What happens to the atom?', NULL, 2, 'multiple_choice'::answer_type, 'It recoils in the opposite direction with momentum equal in size to the photon''s', NULL, false, NULL, false, NULL, 'Total momentum stays zero. Mark scheme (3 marks). C1: conservation of momentum. C1: equal and opposite. A1: D (It recoils in the opposite direction with momentum equal in size to the photon''s).', 3, NULL, NULL),
('a9a36a2c-21b3-5a47-91f5-853f4269d0b6', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 34, 34, 'A mirror reflects a 0.50 W laser beam straight back. Calculate the force on the mirror in units of 10⁻⁹ N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.333', '10⁻⁹ N', false, NULL, false, NULL, 'F = 2P/c = 2 × 0.50 ÷ 3.00 × 10⁸ = 3.33 × 10⁻⁹ N. Mark scheme (3 marks). C1: Δp = 2p. C1: F = 2P/c. A1: F = 3.33 × 10⁻⁹ N.', 3, NULL, NULL),
('de23a340-1624-5d1d-915c-effc4af9df7c', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 35, 35, 'How many photons of wavelength 532 nm must be absorbed each second to give a force of 1.0 nN? Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '8.024e17', NULL, false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 532 × 10⁻⁹ = 1.246 × 10⁻²⁷ kg m s⁻¹. n = F/p = 1.0 × 10⁻⁹ ÷ 1.246 × 10⁻²⁷ = 8.02 × 10¹⁷. Mark scheme (4 marks). C1: photon momentum. C1: F = np. C1: nN to N. A1: n = 8.02 × 10¹⁷.', 4, NULL, NULL),
('44605c8d-11fb-539c-8a03-b67fac7f69e2', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 36, 36, 'A beam of light strikes a mirror at 60° to the normal and reflects. In which direction is the force on the mirror?', NULL, 2, 'multiple_choice'::answer_type, 'Along the normal, into the mirror', NULL, false, NULL, false, NULL, 'Only the momentum component along the normal is reversed. Mark scheme (3 marks). C1: parallel component unchanged. C1: normal component reversed. A1: B (Along the normal, into the mirror).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 360 230" role="img" aria-labelledby="fgebfe9b52-t fgebfe9b52-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgebfe9b52-t">Reflection from a mirror</title><desc id="fgebfe9b52-d">A light beam strikes a plane mirror at 60° to the normal and reflects at 60° on the other side of the normal.</desc><line x1="40" y1="180" x2="320" y2="180" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="44" y1="182" x2="36" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="56" y1="182" x2="48" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="68" y1="182" x2="60" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="80" y1="182" x2="72" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="92" y1="182" x2="84" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="104" y1="182" x2="96" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="116" y1="182" x2="108" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="128" y1="182" x2="120" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="140" y1="182" x2="132" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="152" y1="182" x2="144" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="164" y1="182" x2="156" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="176" y1="182" x2="168" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="188" y1="182" x2="180" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="200" y1="182" x2="192" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="212" y1="182" x2="204" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="224" y1="182" x2="216" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="236" y1="182" x2="228" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="248" y1="182" x2="240" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="260" y1="182" x2="252" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="272" y1="182" x2="264" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="284" y1="182" x2="276" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="296" y1="182" x2="288" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="308" y1="182" x2="300" y2="190" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="180" x2="180" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 4"/><text x="180" y="14" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-muted,#6b7280)">normal</text><line x1="50.1" y1="105" x2="116.1" y2="143.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="121.5,146.2 112.6,145.5 116.4,138.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><line x1="121.5" y1="146.2" x2="180" y2="180" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="180" y1="180" x2="304.4" y2="108.1" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="309.9,105 304.7,112.4 300.9,105.8" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><path d="M180,134 A46,46 0 0,0 140.2,157" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="149" y="126.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60°</text><path d="M180,134 A46,46 0 0,1 219.8,157" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="211" y="126.3" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">60°</text><text x="44.1" y="95" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">incident beam</text><text x="315.9" y="95" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">reflected beam</text></svg>', 'A light beam strikes a plane mirror at 60° to the normal and reflects at 60° on the other side of the normal.'),
('4f7b09b9-ccf8-5cfc-8582-25255bbbd8b6', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 37, 37, 'A sodium atom (mass 3.8 × 10⁻²⁶ kg) at rest absorbs a photon of wavelength 589 nm. Calculate the recoil speed of the atom in units of 10⁻² m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.962', '10⁻² m s⁻¹', false, NULL, false, NULL, 'p = 6.63 × 10⁻³⁴ ÷ 589 × 10⁻⁹ = 1.126 × 10⁻²⁷ kg m s⁻¹. v = p/m = 1.126 × 10⁻²⁷ ÷ 3.8 × 10⁻²⁶ = 0.0296 m s⁻¹. Mark scheme (3 marks). C1: photon momentum. C1: v = p/m. A1: v = 2.96 × 10⁻² m s⁻¹.', 3, NULL, NULL),
('473c9352-f215-5591-813b-1d8fdb3a040e', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 38, 38, 'In laser cooling, each absorbed photon slows an atom by 2.96 cm s⁻¹. Estimate the number of photons needed to slow the atom from 300 m s⁻¹ to rest.', NULL, 2, 'numeric'::answer_type, '10135', NULL, false, NULL, false, NULL, 'N = 300 ÷ 0.0296 = 1.01 × 10⁴. Mark scheme (3 marks). C1: cm s⁻¹ to m s⁻¹. C1: N = total Δv ÷ Δv per photon. A1: N = 1.01 × 10⁴.', 3, NULL, NULL),
('59f10c6e-f713-5359-8dc7-534abeadf323', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 39, 39, 'Comet dust tails point away from the Sun. What causes this?', NULL, 2, 'multiple_choice'::answer_type, 'The momentum carried by sunlight pushes on the small dust grains', NULL, false, NULL, false, NULL, 'For tiny grains radiation force can exceed gravity, since force ∝ area and gravity ∝ volume. Mark scheme (4 marks). C1: radiation pressure. C1: photon momentum. C1: area/volume argument. A1: C (The momentum carried by sunlight pushes on the small dust grains).', 4, NULL, NULL),
('cbe45934-59aa-5e5b-b545-ad96641f8c93', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 40, 40, 'Caesium-137 emits gamma rays of energy 0.66 MeV. Calculate the momentum of one of these photons in units of 10⁻²² kg m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.52', '10⁻²² kg m s⁻¹', false, NULL, false, NULL, 'E = 0.66 × 10⁶ × 1.60 × 10⁻¹⁹ = 1.056 × 10⁻¹³ J. p = 1.056 × 10⁻¹³ ÷ 3.00 × 10⁸ = 3.52 × 10⁻²² kg m s⁻¹. Mark scheme (3 marks). C1: MeV to J. C1: p = E/c. A1: p = 3.52 × 10⁻²² kg m s⁻¹.', 3, NULL, NULL),
('2979d8b2-1691-5428-aa2b-c0999d73570f', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 41, 41, 'What power of light must be absorbed by a surface to exert a force of 2.0 × 10⁻⁷ N on it? Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '60', 'W', false, NULL, false, NULL, 'P = Fc = 2.0 × 10⁻⁷ × 3.00 × 10⁸ = 60 W. Mark scheme (3 marks). C1: F = P/c. C1: rearranged. A1: P = 60 W.', 3, NULL, NULL),
('5e6e6c59-4788-5b1d-8089-797e93086ff8', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 42, 42, 'Why do we not feel the push of light from a torch?', NULL, 2, 'multiple_choice'::answer_type, 'The force P/c is extremely small for everyday powers', NULL, false, NULL, false, NULL, 'A 1 W torch exerts about 3 × 10⁻⁹ N. Mark scheme (3 marks). C1: F = P/c. C1: c very large. A1: A (The force P/c is extremely small for everyday powers).', 3, NULL, NULL),
('391dad0a-85c4-5a2a-af61-89b1e3cd88f4', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 43, 43, 'A solar sail of area 400 m² and total mass 20 kg faces the Sun where the intensity is 1.36 kW m⁻². The sail reflects all the light straight back. (a) Calculate the power reaching the sail. (b) Calculate the force on it. (c) Calculate its acceleration. Give only the answer to (c), in units of 10⁻⁴ m s⁻². Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '1.813', '10⁻⁴ m s⁻²', false, NULL, false, NULL, '(a) P = 1.36 × 10³ × 400 = 5.44 × 10⁵ W. (b) F = 2P/c = 2 × 5.44 × 10⁵ ÷ 3.00 × 10⁸ = 0.003627 N. (c) a = 0.003627 ÷ 20 = 1.81 × 10⁻⁴ m s⁻². Mark scheme (5 marks). C1: P = IA. M1: F = 2P/c. C1: force. C1: a = F/m. A1: a = 1.81 × 10⁻⁴ m s⁻².', 5, NULL, NULL),
('dcfe9441-11a6-5daf-9a30-13db086bda6d', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 44, 44, 'An X-ray photon of wavelength 0.050 nm is scattered straight back by an electron. Assume its wavelength is unchanged. (a) Calculate the photon momentum. (b) Calculate the change in the photon''s momentum. (c) Calculate the speed given to the electron, initially at rest. Give only the answer to (c), in units of 10⁷ m s⁻¹. Take h = 6.63 × 10⁻³⁴ J s and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '2.911', '10⁷ m s⁻¹', false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 0.050 × 10⁻⁹ = 1.326 × 10⁻²³ kg m s⁻¹. (b) Δp = 2 × 1.326 × 10⁻²³ = 2.652 × 10⁻²³ kg m s⁻¹. (c) v = 2.652 × 10⁻²³ ÷ 9.11 × 10⁻³¹ = 2.91 × 10⁷ m s⁻¹. Mark scheme (6 marks). C1: p = h/λ. M1: Δp = 2p. C1: conservation of momentum. C1: v = Δp/m. B1: approximation stated. A1: v = 2.91 × 10⁷ m s⁻¹.', 6, NULL, NULL),
('a1f85c64-2cfb-5b8a-b586-40fc44853933', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 45, 45, 'A 5.0 mW laser beam is reflected straight back by a tiny mirror of mass 0.20 g, which is free to move in a vacuum. (a) Calculate the force on the mirror. (b) Calculate its acceleration. (c) Calculate the speed it reaches after 10 s. Give only the answer to (b), in units of 10⁻⁷ m s⁻². Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '1.667', '10⁻⁷ m s⁻²', false, NULL, false, NULL, '(a) F = 2P/c = 2 × 5.0 × 10⁻³ ÷ 3.00 × 10⁸ = 3.333 × 10⁻¹¹ N. (b) a = 3.333 × 10⁻¹¹ ÷ 0.20 × 10⁻³ = 1.67 × 10⁻⁷ m s⁻². (c) v = at = 1.667 × 10⁻⁷ × 10 = 1.67 × 10⁻⁶ m s⁻¹. Mark scheme (6 marks). M1: F = 2P/c. C1: force. C1: mass in kg. C1: a = F/m. C1: v = at. A1: a = 1.67 × 10⁻⁷ m s⁻².', 6, NULL, NULL),
('0683b60d-2cde-506c-9a1e-f5b1a9a5ed30', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 46, 46, 'Sunlight of intensity 1.36 kW m⁻² reaches the Earth (radius 6.37 × 10⁶ m). Assume it is all absorbed. (a) Calculate the area the Earth presents to the Sun. (b) Calculate the total power absorbed. (c) Calculate the force of sunlight on the Earth, in units of 10⁸ N. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5.779', '10⁸ N', false, NULL, false, NULL, '(a) A = π × (6.37 × 10⁶)² = 1.275 × 10¹⁴ m². (b) P = 1.36 × 10³ × 1.275 × 10¹⁴ = 1.734 × 10¹⁷ W. (c) F = 1.734 × 10¹⁷ ÷ 3.00 × 10⁸ = 5.78 × 10⁸ N. Mark scheme (5 marks). C1: cross-sectional area πR². C1: P = IA. M1: F = P/c. C1: value. A1: F = 5.78 × 10⁸ N.', 5, NULL, NULL),
('9127e7d1-ee41-5ad5-9465-824325f02725', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 47, 47, 'A "photon rocket" would push itself along by emitting a beam of light. (a) Show that the thrust is P/c, where P is the beam power. (b) Calculate the beam power needed for a thrust of 1.0 N. Give only the answer to (b), in units of 10⁸ W. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '3', '10⁸ W', false, NULL, false, NULL, '(a) Light leaves carrying momentum P/c per second, so the rocket gains equal and opposite momentum at that rate. (b) P = Fc = 1.0 × 3.00 × 10⁸ = 3.0 × 10⁸ W. Mark scheme (5 marks). B1: momentum per second P/c. M1: Newton''s third law. C1: P = Fc. C1: value. A1: P = 3.0 × 10⁸ W.', 5, NULL, NULL),
('3bddaaa1-32df-5e71-8d25-5590e0bdb9d4', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 48, 48, 'A 1.0 W laser beam is focused onto a spot of diameter 10 µm on an absorbing surface. (a) Calculate the area of the spot. (b) Calculate the intensity. (c) Calculate the radiation pressure on the spot. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '42.44', 'Pa', false, NULL, false, NULL, '(a) A = π × (5.0 × 10⁻⁶)² = 7.854 × 10⁻¹¹ m². (b) I = 1.0 ÷ 7.854 × 10⁻¹¹ = 1.273 × 10¹⁰ W m⁻². (c) p = I/c = 1.273 × 10¹⁰ ÷ 3.00 × 10⁸ = 42.4 Pa. Mark scheme (6 marks). C1: radius from diameter. C1: area. C1: I = P/A. M1: pressure = I/c. C1: value. A1: pressure = 42.4 Pa.', 6, NULL, NULL),
('f022af20-0491-56ce-bc2e-80b33abbee4e', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 49, 49, 'A 1.0 ms pulse of light carrying 3.0 J is completely absorbed by a 2.0 g block at rest on a frictionless surface. (a) Calculate the momentum carried by the pulse. (b) Calculate the speed of the block afterwards. Give only the answer to (b), in units of 10⁻⁶ m s⁻¹. Take c = 3.00 × 10⁸ m s⁻¹.', NULL, 3, 'numeric'::answer_type, '5', '10⁻⁶ m s⁻¹', false, NULL, false, NULL, '(a) p = E/c = 3.0 ÷ 3.00 × 10⁸ = 1.0 × 10⁻⁸ kg m s⁻¹, whatever the wavelength. (b) v = p/m = 1.0 × 10⁻⁸ ÷ 2.0 × 10⁻³ = 5.00 × 10⁻⁶ m s⁻¹. Mark scheme (5 marks). M1: total momentum = E/c. C1: value. M1: conservation of momentum. C1: v. A1: v = 5.0 × 10⁻⁶ m s⁻¹.', 5, NULL, NULL),
('f34ca774-032c-59ed-8876-3eecdf895e70', '7d22edfc-44c4-4846-9769-292936cb7827', '3523abc9-75b0-40b2-9f61-48537e083932', 'a-level', '28.5', '9702 coursebook 28.5 · Photons have momentum too', 50, 50, 'A laser of wavelength 780 nm is used to slow rubidium atoms (mass 1.42 × 10⁻²⁵ kg) moving at 250 m s⁻¹ towards it. (a) Calculate the photon momentum. (b) Calculate the change in speed of an atom per absorbed photon. (c) Calculate the number of photons needed to stop an atom. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s.', NULL, 3, 'numeric'::answer_type, '41765', NULL, false, NULL, false, NULL, '(a) p = 6.63 × 10⁻³⁴ ÷ 780 × 10⁻⁹ = 8.500 × 10⁻²⁸ kg m s⁻¹. (b) Δv = 8.500 × 10⁻²⁸ ÷ 1.42 × 10⁻²⁵ = 0.005986 m s⁻¹. (c) N = 250 ÷ 0.005986 = 4.18 × 10⁴. Mark scheme (6 marks). C1: photon momentum. M1: Δv = p/m. C1: value. M1: N = v ÷ Δv. C1: value. B1: re-emission random so averages out.', 6, NULL, NULL)
