INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('8542dc93-f51b-58ec-abbc-561c60cbc60c', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 9, 9, 'In a hydrogen atom an electron drops from the −1.51 eV level to the −3.40 eV level. Calculate the energy of the emitted photon in eV.', NULL, 1, 'numeric'::answer_type, '1.89', 'eV', false, NULL, false, NULL, 'ΔE = −1.51 − (−3.40) = 3.40 − 1.51 = 1.89 eV. Mark scheme (2 marks). C1: hf = E₁ − E₂. A1: E = 1.89 eV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg7e6b4a27-t fg7e6b4a27-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7e6b4a27-t">Hydrogen energy levels</title><desc id="fg7e6b4a27-d">Energy level diagram for hydrogen (n = 1 to 4); an arrow shows the electron falling from the −1.51 eV level (n = 3) to the −3.40 eV level (n = 2).</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="95.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><line x1="200" y1="64" x2="200" y2="89.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,95.7 196.2,87.6 203.8,87.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 4); an arrow shows the electron falling from the −1.51 eV level (n = 3) to the −3.40 eV level (n = 2).'),
('c89cb40f-5666-5813-863a-ab55083f4dc8', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 10, 10, 'What is the ground state of an atom?', NULL, 1, 'multiple_choice'::answer_type, 'Its lowest possible energy level', NULL, false, NULL, false, NULL, 'Electrons normally occupy the lowest available levels. Mark scheme (1 mark). B1: C (Its lowest possible energy level).', 1, NULL, NULL),
('206df21f-eb48-5278-889e-88fbcea85792', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 11, 11, 'A photon of energy 1.89 eV is emitted by a hydrogen atom. Calculate its wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '657.7 nm', 'nm', false, NULL, false, NULL, 'λ = hc/E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.89 × 1.60 × 10⁻¹⁹) = 6.577 × 10⁻⁷ m. In nm: 6.577 × 10⁻⁷ × 10⁹ = 658. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 658 nm.', 2, NULL, NULL),
('4efb91bb-7f3c-57d3-a650-1a1670be43e8', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 12, 12, 'How is a bright line in an emission spectrum produced?', NULL, 1, 'multiple_choice'::answer_type, 'An electron drops to a lower energy level and emits a photon of that energy difference', NULL, false, NULL, false, NULL, 'Emitted photon energy = E(upper) − E(lower). Mark scheme (1 mark). B1: A (An electron drops to a lower energy level and emits a photon of that energy difference).', 1, NULL, NULL),
('08c598b7-e273-55de-ba1f-436d317b24cc', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 13, 13, 'An electron is in the −3.40 eV level of a hydrogen atom. How much energy is needed to ionise the atom from this level? Give your answer in units of 10⁻¹⁹ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '5.44', '10⁻¹⁹ J', false, NULL, false, NULL, 'E = 3.40 × 1.60 × 10⁻¹⁹ = 5.44 × 10⁻¹⁹ J. Mark scheme (2 marks). C1: raise the electron to 0 eV. A1: E = 5.44 × 10⁻¹⁹ J.', 2, NULL, NULL),
('e164541f-8786-5a90-8637-1402683adb88', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 14, 14, 'What causes the dark lines in an absorption spectrum?', NULL, 1, 'multiple_choice'::answer_type, 'Atoms absorb photons whose energies match the gaps between their levels', NULL, false, NULL, false, NULL, 'Absorbed photons are re-emitted in all directions, so those wavelengths are dim. Mark scheme (1 mark). B1: D (Atoms absorb photons whose energies match the gaps between their levels).', 1, NULL, NULL),
('f6b67043-40c8-597f-90bd-c279fd8164ce', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 15, 15, 'A mercury atom has levels at −10.4 eV (ground state) and −5.5 eV. Calculate the photon energy when an electron falls from −5.5 eV to the ground state, in eV.', NULL, 1, 'numeric'::answer_type, '4.9', 'eV', false, NULL, false, NULL, 'ΔE = −5.5 − (−10.4) = 10.4 − 5.5 = 4.9 eV. Mark scheme (2 marks). C1: difference of levels. A1: E = 4.9 eV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" role="img" aria-labelledby="fg9de174a5-t fg9de174a5-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg9de174a5-t">Two levels of mercury</title><desc id="fg9de174a5-d">Two energy levels of a mercury atom, the ground state at −10.4 eV and an excited level at −5.5 eV, with an arrow for the fall to the ground state.</desc><line x1="110" y1="238" x2="290" y2="238" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="238" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">ground state</text><text x="298" y="238" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−10.4 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">excited</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−5.5 eV</text><line x1="200" y1="44" x2="200" y2="231.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,238 196.2,229.8 203.8,229.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="246" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Two energy levels of a mercury atom, the ground state at −10.4 eV and an excited level at −5.5 eV, with an arrow for the fall to the ground state.'),
('570c2511-815e-596a-a0e8-32f2797c1b03', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 16, 16, 'What is meant by excitation of an atom?', NULL, 1, 'multiple_choice'::answer_type, 'An electron is raised to a higher energy level within the atom', NULL, false, NULL, false, NULL, 'Excitation leaves the electron bound; ionisation removes it. Mark scheme (1 mark). B1: B (An electron is raised to a higher energy level within the atom).', 1, NULL, NULL),
('fe9ce9e1-975a-511f-ad08-5d4ce3161c43', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 17, 17, 'An atom has four energy levels. How many different photon energies can be emitted as electrons fall between these levels?', NULL, 1, 'numeric'::answer_type, '6', NULL, false, NULL, false, NULL, 'Each pair of levels gives one line: 3 + 2 + 1 = 6. Mark scheme (2 marks). C1: count all pairs. A1: number = 6.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 240" role="img" aria-labelledby="fg4feda451-t fg4feda451-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4feda451-t">Four energy levels</title><desc id="fg4feda451-d">Energy level diagram of an atom with four levels, n = 1 (ground state) to n = 4, with no transitions marked.</desc><line x1="110" y1="218" x2="290" y2="218" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="218" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="119.1" x2="290" y2="119.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="119.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><line x1="110" y1="71.7" x2="290" y2="71.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="71.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="226" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of an atom with four levels, n = 1 (ground state) to n = 4, with no transitions marked.'),
('4bb2bf89-d3ab-5a42-83c4-a10a17bd8f4c', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 18, 18, 'On an energy level diagram, what does the level at 0 eV represent?', NULL, 1, 'multiple_choice'::answer_type, 'The electron has just been freed from the atom', NULL, false, NULL, false, NULL, 'Bound states have negative energy; 0 eV is the ionisation limit. Mark scheme (1 mark). B1: C (The electron has just been freed from the atom).', 1, NULL, NULL),
('7c9eb866-3f29-505a-8e54-dc76360ed56a', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 19, 19, 'A hydrogen atom emits a photon of energy 2.55 eV. Calculate its wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '487.5 nm', 'nm', false, NULL, false, NULL, 'λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.55 × 1.60 × 10⁻¹⁹) = 4.875 × 10⁻⁷ m. In nm: 4.875 × 10⁻⁷ × 10⁹ = 488. Mark scheme (2 marks). C1: λ = hc/E. A1: λ = 488 nm.', 2, NULL, NULL),
('14b9a61a-50dc-5c2b-8fb3-0f89a3f76737', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 20, 20, 'Which transition gives the emitted photon of shortest wavelength?', NULL, 1, 'multiple_choice'::answer_type, 'The one with the largest energy difference', NULL, false, NULL, false, NULL, 'λ = hc/ΔE, so the biggest energy drop gives the shortest wavelength. Mark scheme (1 mark). B1: A (The one with the largest energy difference).', 1, NULL, NULL),
('e1eff3e9-be1f-5871-8cb0-6330c1e95104', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 21, 21, 'The Lyman-alpha line of hydrogen has photon energy 10.2 eV. Calculate its frequency in units of 10¹⁵ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 1, 'numeric'::answer_type, '2.462', '10¹⁵ Hz', false, NULL, false, NULL, 'f = E/h = 10.2 × 1.60 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 2.46 × 10¹⁵ Hz. Mark scheme (2 marks). C1: eV to J then f = E/h. A1: f = 2.46 × 10¹⁵ Hz.', 2, NULL, NULL),
('bc6cc9f0-87bc-549d-a9d0-5ad4ffb5f5ac', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 22, 22, 'What is the ionisation energy of an atom?', NULL, 1, 'multiple_choice'::answer_type, 'The energy needed to remove an electron completely from the ground state', NULL, false, NULL, false, NULL, 'It takes the electron from the ground state to 0 eV. Mark scheme (1 mark). B1: D (The energy needed to remove an electron completely from the ground state).', 1, NULL, NULL),
('dac26b81-4634-5291-a556-84aa6ba25411', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 23, 23, 'An electron in a hydrogen atom falls from −0.85 eV to −1.51 eV. Calculate the photon energy in eV.', NULL, 1, 'numeric'::answer_type, '0.66', 'eV', false, NULL, false, NULL, 'ΔE = −0.85 − (−1.51) = 1.51 − 0.85 = 0.66 eV. Mark scheme (2 marks). C1: difference of levels. A1: E = 0.66 eV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg5a4f1758-t fg5a4f1758-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5a4f1758-t">Hydrogen energy levels</title><desc id="fg5a4f1758-d">Energy level diagram for hydrogen (n = 1 to 4); an arrow shows the electron falling from −0.85 eV (n = 4) to −1.51 eV (n = 3).</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.85 eV</text><line x1="200" y1="44" x2="200" y2="57.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,64 196.2,55.8 203.8,55.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 4); an arrow shows the electron falling from −0.85 eV (n = 4) to −1.51 eV (n = 3).'),
('de3c399c-be1b-5d07-b6f3-b7a0956eb071', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 24, 24, 'A photon passes through a gas of atoms in their ground state. When is it absorbed?', NULL, 1, 'multiple_choice'::answer_type, 'Only when its energy exactly matches the energy gap to a higher level (or exceeds the ionisation energy)', NULL, false, NULL, false, NULL, 'Bound-to-bound transitions need an exact energy match. Mark scheme (1 mark). B1: B (Only when its energy exactly matches the energy gap to a higher level (or exceeds the ionisation energy)).', 1, NULL, NULL),
('bd1b51ce-3c51-5cf2-a898-0d301eb7dde4', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 25, 25, 'Sodium has a ground state at −5.14 eV and an excited level at −3.03 eV. How much energy, in eV, is needed to excite an electron from the ground state to this level?', NULL, 1, 'numeric'::answer_type, '2.11', 'eV', false, NULL, false, NULL, 'ΔE = −3.03 − (−5.14) = 5.14 − 3.03 = 2.11 eV. Mark scheme (1 mark). A1: ΔE = 2.11 eV.', 1, NULL, NULL),
('08fb5df3-c6c3-5584-82ba-a5118d5ac9c8', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 26, 26, 'In hydrogen, an electron falls from the −0.54 eV level to the −3.40 eV level. Calculate the wavelength of the emitted light in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '434.7 nm', 'nm', false, NULL, false, NULL, 'ΔE = 3.40 − 0.54 = 2.86 eV. λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.86 × 1.60 × 10⁻¹⁹) = 4.347 × 10⁻⁷ m. In nm: 4.347 × 10⁻⁷ × 10⁹ = 435. Mark scheme (3 marks). C1: energy difference. C1: λ = hc/E. A1: λ = 435 nm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 304.1" role="img" aria-labelledby="fgfec1862a-t fgfec1862a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgfec1862a-t">Hydrogen energy levels</title><desc id="fgfec1862a-d">Energy level diagram for hydrogen (n = 1 to 5); an arrow shows the electron falling from −0.54 eV (n = 5) to −3.40 eV (n = 2).</desc><line x1="110" y1="282.1" x2="290" y2="282.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="282.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="115" x2="290" y2="115" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="115" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="115" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="84" x2="290" y2="84" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="84" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 5</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.54 eV</text><line x1="200" y1="44" x2="200" y2="108.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,115 196.2,106.8 203.8,106.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="290.1" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 5); an arrow shows the electron falling from −0.54 eV (n = 5) to −3.40 eV (n = 2).'),
('17bbb276-3912-5982-bb9f-5207b72b3ac7', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 27, 27, 'A hydrogen atom in its ground state (−13.6 eV) absorbs a photon of 12.09 eV. How much more energy, in eV, would then be needed to ionise it?', NULL, 2, 'numeric'::answer_type, '1.51', 'eV', false, NULL, false, NULL, 'New level = −13.6 + 12.09 = −1.51 eV. Energy to ionise = 13.6 − 12.09 = 1.51 eV. Mark scheme (3 marks). C1: new level. C1: raise to 0 eV. A1: E = 1.51 eV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg70287d9d-t fg70287d9d-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg70287d9d-t">Hydrogen energy levels</title><desc id="fg70287d9d-d">Energy level diagram for hydrogen (n = 1 to 4); an upward arrow shows the atom being excited from the ground state at −13.6 eV by absorbing a photon.</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><text x="298" y="266.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−13.6 eV</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><line x1="200" y1="266.9" x2="200" y2="70.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,64 203.8,72.2 196.2,72.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 4); an upward arrow shows the atom being excited from the ground state at −13.6 eV by absorbing a photon.'),
('d938fa28-9f4f-5fe0-ae2e-7b24ab2432d9', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 28, 28, 'An electron with kinetic energy 12.5 eV collides with a hydrogen atom in its ground state (levels −13.6, −3.40, −1.51, −0.85 eV). Which is the highest level the atom can be excited to?', NULL, 2, 'multiple_choice'::answer_type, 'The −1.51 eV level', NULL, false, NULL, false, NULL, '−1.51 needs 12.09 eV ≤ 12.5 eV; −0.85 needs 12.75 eV. A colliding electron can give part of its energy. Mark scheme (3 marks). C1: energy needed for each level. C1: partial transfer allowed. A1: C (The −1.51 eV level).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg93a59f0a-t fg93a59f0a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg93a59f0a-t">Hydrogen energy levels</title><desc id="fg93a59f0a-d">Energy level diagram for hydrogen with levels at −13.6 eV (ground state), −3.40 eV, −1.51 eV and −0.85 eV.</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><text x="298" y="266.9" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−13.6 eV</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="95.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.85 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen with levels at −13.6 eV (ground state), −3.40 eV, −1.51 eV and −0.85 eV.'),
('4bd67143-db76-5e82-a232-faa093a59dbd', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 29, 29, 'Mercury vapour emits a strong ultraviolet line at 254 nm. Calculate the energy gap between the two levels involved, in eV. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4.894', 'eV', false, NULL, false, NULL, 'ΔE = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (254 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 4.89 eV. Mark scheme (3 marks). C1: E = hc/λ. C1: in eV. A1: ΔE = 4.89 eV.', 3, NULL, NULL),
('0c834d36-ed1a-581f-9131-b64822a601e5', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 30, 30, 'An atom has energy levels at −8.0 eV, −4.0 eV, −2.5 eV and −1.0 eV. Calculate the longest wavelength it can emit, in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '828.8 nm', 'nm', false, NULL, false, NULL, 'Smallest gap = −1.0 − (−2.5) = 1.5 eV. λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.5 × 1.60 × 10⁻¹⁹) = 8.288 × 10⁻⁷ m. In nm: 8.288 × 10⁻⁷ × 10⁹ = 829. Mark scheme (4 marks). M1: smallest gap gives longest λ. C1: gap. C1: λ = hc/E. A1: λ = 829 nm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" role="img" aria-labelledby="fg7617b9d6-t fg7617b9d6-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7617b9d6-t">Energy levels of an atom</title><desc id="fg7617b9d6-d">Energy level diagram of an atom with levels at −8.0 eV, −4.0 eV, −2.5 eV and −1.0 eV.</desc><line x1="110" y1="238" x2="290" y2="238" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="238" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−8.0 eV</text><line x1="110" y1="127.1" x2="290" y2="127.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="127.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−4.0 eV</text><line x1="110" y1="85.6" x2="290" y2="85.6" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="85.6" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−2.5 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.0 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="246" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of an atom with levels at −8.0 eV, −4.0 eV, −2.5 eV and −1.0 eV.'),
('e5688923-a007-5741-81b4-9749c68d07e0', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 31, 31, 'Why does each element have its own characteristic set of spectral lines?', NULL, 2, 'multiple_choice'::answer_type, 'Each element has its own pattern of energy levels', NULL, false, NULL, false, NULL, 'Photon energies equal the gaps between levels, which differ from element to element. Mark scheme (3 marks). C1: levels unique. C1: lines = level gaps. A1: A (Each element has its own pattern of energy levels).', 3, NULL, NULL),
('2c04ba6d-d3bc-5fdf-aeae-387ac741abe9', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 32, 32, 'An electron with 6.0 eV of kinetic energy collides with a mercury atom in its ground state and raises it to the first excited state, 4.9 eV above the ground state. What kinetic energy, in eV, does the electron keep?', NULL, 2, 'numeric'::answer_type, '1.1', 'eV', false, NULL, false, NULL, 'Ek left = 6.0 − 4.9 = 1.1 eV. Mark scheme (3 marks). C1: energy conservation. C1: value. A1: Ek = 1.1 eV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg4b7ddf1c-t fg4b7ddf1c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4b7ddf1c-t">Mercury: first excitation</title><desc id="fg4b7ddf1c-d">Energy level diagram of mercury showing the ground state and the first excited state 4.9 eV above it, with an upward arrow for the excitation.</desc><line x1="110" y1="198" x2="290" y2="198" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="198" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">ground state</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">first excited</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">+4.9 eV</text><line x1="200" y1="198" x2="200" y2="50.3" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,44 203.8,52.2 196.2,52.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="206" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of mercury showing the ground state and the first excited state 4.9 eV above it, with an upward arrow for the excitation.'),
('49668817-4884-5e9c-992a-c9be11bb0184', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 33, 33, 'In hydrogen, an electron falls from −1.51 eV to −13.6 eV. Calculate the frequency of the emitted photon in units of 10¹⁵ Hz. Take e = 1.60 × 10⁻¹⁹ C and h = 6.63 × 10⁻³⁴ J s.', NULL, 2, 'numeric'::answer_type, '2.918', '10¹⁵ Hz', false, NULL, false, NULL, 'ΔE = 13.6 − 1.51 = 12.09 eV. f = 12.09 × 1.60 × 10⁻¹⁹ ÷ 6.63 × 10⁻³⁴ = 2.92 × 10¹⁵ Hz. Mark scheme (3 marks). C1: energy difference. C1: f = E/h. A1: f = 2.92 × 10¹⁵ Hz.', 3, NULL, NULL),
('fbe3b40a-64a1-5de2-907e-c85881c07442', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 34, 34, 'White light passes through cool sodium vapour and then into a spectrometer. What is seen?', NULL, 2, 'multiple_choice'::answer_type, 'A continuous spectrum crossed by dark lines at sodium''s characteristic wavelengths', NULL, false, NULL, false, NULL, 'Sodium atoms absorb photons that match their level gaps and re-emit them in all directions. Mark scheme (3 marks). C1: absorption. C1: dark lines at matching wavelengths. A1: D (A continuous spectrum crossed by dark lines at sodium''s characteristic wavelengths).', 3, NULL, NULL),
('4c755290-262c-5964-9a4c-6405f806d714', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 35, 35, 'Hydrogen emits ultraviolet light of wavelength 121.6 nm when an electron falls to the ground state (−13.6 eV). Calculate the photon energy in eV, which is the energy of the upper level above the ground state. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '10.22', 'eV', false, NULL, false, NULL, 'E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (121.6 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 10.2 eV. Mark scheme (4 marks). C1: E = hc/λ. C1: nm to m. C1: J to eV. A1: E = 10.2 eV.', 4, NULL, NULL),
('57ede404-e921-5c0b-8ccf-064c575e9950', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 36, 36, 'The visible lines of hydrogen (the Balmer series) all end on the same level. Which?', NULL, 2, 'multiple_choice'::answer_type, 'The −3.40 eV level (n = 2)', NULL, false, NULL, false, NULL, 'Transitions to n = 2 have gaps of 1.9–3.4 eV, which are visible photons. Mark scheme (3 marks). C1: n = 2. C1: visible energies. A1: B (The −3.40 eV level (n = 2)).', 3, NULL, NULL),
('10afb386-3494-511f-b16b-6379f77fdfa3', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 37, 37, 'Calculate (wavelength of the −1.51 → −3.40 eV line) ÷ (wavelength of the −0.85 → −3.40 eV line) for hydrogen.', NULL, 2, 'numeric'::answer_type, '1.349', NULL, false, NULL, false, NULL, 'λ ∝ 1/ΔE: ratio = (3.40 − 0.85) ÷ (3.40 − 1.51) = 2.55 ÷ 1.89 = 1.35. Mark scheme (3 marks). C1: both energy gaps. C1: inverse ratio. A1: ratio = 1.35.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg47cbc7da-t fg47cbc7da-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg47cbc7da-t">Hydrogen energy levels</title><desc id="fg47cbc7da-d">Energy level diagram for hydrogen (n = 1 to 4) with two downward arrows ending on the −3.40 eV level: one from −1.51 eV and one from −0.85 eV.</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="95.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.85 eV</text><line x1="170" y1="64" x2="170" y2="89.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,95.7 166.2,87.6 173.8,87.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="44" x2="230" y2="89.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,95.7 226.2,87.6 233.8,87.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 4) with two downward arrows ending on the −3.40 eV level: one from −1.51 eV and one from −0.85 eV.'),
('93df94e7-450b-51f8-8545-451b85bd1cfe', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 38, 38, 'A hydrogen atom is excited to the n = 3 level. How many different photon energies could it emit on its way back to the ground state (by any route)?', NULL, 2, 'multiple_choice'::answer_type, '3', NULL, false, NULL, false, NULL, '3 → 1, 3 → 2 and 2 → 1. Mark scheme (3 marks). C1: list transitions. C1: count. A1: C (3).', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 280" role="img" aria-labelledby="fg21f50d8c-t fg21f50d8c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg21f50d8c-t">Hydrogen energy levels</title><desc id="fg21f50d8c-d">Energy level diagram for hydrogen showing the n = 1, n = 2 and n = 3 levels.</desc><line x1="110" y1="258" x2="290" y2="258" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="258" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="77.5" x2="290" y2="77.5" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="77.5" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="266" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen showing the n = 1, n = 2 and n = 3 levels.'),
('ae53bf5f-e12b-566b-b50c-b1088e59fb7c', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 39, 39, 'The yellow sodium line has a wavelength of 589 nm. Calculate the energy gap between the levels involved, in units of 10⁻¹⁹ J. Take h = 6.63 × 10⁻³⁴ J s and c = 3.00 × 10⁸ m s⁻¹.', NULL, 2, 'numeric'::answer_type, '3.377', '10⁻¹⁹ J', false, NULL, false, NULL, 'ΔE = hc/λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ 589 × 10⁻⁹ = 3.38 × 10⁻¹⁹ J. Mark scheme (3 marks). C1: E = hc/λ. C1: substitution. A1: ΔE = 3.38 × 10⁻¹⁹ J.', 3, NULL, NULL),
('d1e2eb3e-e4df-5277-957c-4f43391d8dc2', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 40, 40, 'A simple model atom has only three levels, at −7.0 eV, −4.0 eV and −1.5 eV. Which emitted photon has the shortest wavelength? Calculate that wavelength in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '226 nm', 'nm', false, NULL, false, NULL, 'Largest gap = −1.5 − (−7.0) = 5.5 eV. λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (5.5 × 1.60 × 10⁻¹⁹) = 2.260 × 10⁻⁷ m. In nm: 2.260 × 10⁻⁷ × 10⁹ = 226. Mark scheme (4 marks). M1: largest gap. C1: gap value. C1: λ = hc/E. A1: λ = 226 nm.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" role="img" aria-labelledby="fg43179323-t fg43179323-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg43179323-t">A three-level atom</title><desc id="fg43179323-d">Energy level diagram of a model atom with three levels at −7.0 eV, −4.0 eV and −1.5 eV.</desc><line x1="110" y1="238" x2="290" y2="238" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="238" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−7.0 eV</text><line x1="110" y1="132.2" x2="290" y2="132.2" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="132.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−4.0 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.5 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="246" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of a model atom with three levels at −7.0 eV, −4.0 eV and −1.5 eV.'),
('54cea194-0468-5f08-92c5-b282d745769a', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 41, 41, 'Which observation is the best evidence that atoms have discrete energy levels?', NULL, 2, 'multiple_choice'::answer_type, 'Gases emit and absorb light only at certain sharp wavelengths', NULL, false, NULL, false, NULL, 'Sharp lines mean only certain photon energies, so only certain level gaps. Mark scheme (3 marks). C1: line spectra. C1: fixed photon energies. A1: A (Gases emit and absorb light only at certain sharp wavelengths).', 3, NULL, NULL),
('b27631d6-49d6-5dd9-a805-e920f4a42741', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 42, 42, 'Two visible lines of hydrogen come from transitions to the −3.40 eV level: one from −1.51 eV and one from −0.85 eV. (a) Calculate the photon energy of each line. (b) Calculate the wavelength of each in nm. (c) Calculate the difference between the two wavelengths, in nm. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '170.2 nm', 'nm', false, NULL, false, NULL, '(a) 3.40 − 1.51 = 1.89 eV; 3.40 − 0.85 = 2.55 eV. (b) λ = hc/E: 657.7 nm and 487.5 nm. (c) 657.7 − 487.5 = 170 nm. Mark scheme (5 marks). C1: both energies. C1: λ for 1.89 eV. C1: λ for 2.55 eV. C1: difference. A1: Δλ = 170 nm.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 288.9" role="img" aria-labelledby="fg17ac92d0-t fg17ac92d0-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg17ac92d0-t">Hydrogen energy levels</title><desc id="fg17ac92d0-d">Energy level diagram for hydrogen (n = 1 to 4) with the two transitions ending on −3.40 eV: from −1.51 eV and from −0.85 eV.</desc><line x1="110" y1="266.9" x2="290" y2="266.9" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="266.9" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="95.7" x2="290" y2="95.7" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="95.7" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="95.7" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.85 eV</text><line x1="170" y1="64" x2="170" y2="89.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,95.7 166.2,87.6 173.8,87.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="44" x2="230" y2="89.4" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,95.7 226.2,87.6 233.8,87.6" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="274.9" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 4) with the two transitions ending on −3.40 eV: from −1.51 eV and from −0.85 eV.'),
('c7ad2a24-84d9-53e5-b3a8-79b01f46e219', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 43, 43, 'An atom has energy levels at −12.0 eV, −7.5 eV, −4.0 eV and −1.8 eV. (a) State its ionisation energy. (b) State how many different lines it can emit. (c) Calculate the longest wavelength it can emit, in nm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '565.1 nm', 'nm', false, NULL, false, NULL, '(a) 12.0 eV. (b) 3 + 2 + 1 = 6 lines. (c) Smallest gap = 4.0 − 1.8 = 2.2 eV; λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (2.2 × 1.60 × 10⁻¹⁹) = 5.651 × 10⁻⁷ m. In nm: 5.651 × 10⁻⁷ × 10⁹ = 565. Mark scheme (6 marks). B1: ionisation energy. B1: six lines. M1: smallest gap. C1: gap value. C1: λ = hc/E. A1: λ = 565 nm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" role="img" aria-labelledby="fg076d339a-t fg076d339a-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg076d339a-t">Energy levels of an atom</title><desc id="fg076d339a-d">Energy level diagram of an atom with levels at −12.0 eV, −7.5 eV, −4.0 eV and −1.8 eV.</desc><line x1="110" y1="238" x2="290" y2="238" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="238" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−12.0 eV</text><line x1="110" y1="152.4" x2="290" y2="152.4" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="152.4" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−7.5 eV</text><line x1="110" y1="85.8" x2="290" y2="85.8" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="85.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−4.0 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.8 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="246" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of an atom with levels at −12.0 eV, −7.5 eV, −4.0 eV and −1.8 eV.'),
('baf023f7-4b3a-5374-a332-b873155f255f', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 44, 44, 'In a fluorescent tube, mercury atoms emit ultraviolet photons of wavelength 254 nm. The coating absorbs each one and emits a visible photon of wavelength 550 nm, the rest of the energy becoming heat. (a) Calculate both photon energies in eV. (b) Calculate the percentage of each ultraviolet photon''s energy that leaves as visible light. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '46.18', '%', false, NULL, false, NULL, '(a) 4.894 eV and 2.260 eV. (b) E ∝ 1/λ, so the fraction = 254 ÷ 550 × 100 = 46.2 %. Mark scheme (5 marks). C1: UV photon energy. C1: visible photon energy. M1: ratio of energies. C1: percentage. A1: percentage = 46.2%.', 5, NULL, NULL),
('52bf87cb-412c-50f6-827b-d748ef2cf33d', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 45, 45, 'Electrons accelerated through 11.0 V collide with hydrogen atoms in the ground state (levels −13.6, −3.40, −1.51 eV). (a) State which excited level can be reached. (b) Calculate the kinetic energy an electron keeps after exciting an atom. (c) Calculate the wavelength of the light emitted when the atom returns to the ground state, in nm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '121.9 nm', 'nm', false, NULL, false, NULL, '(a) −3.40 eV, needing 10.2 eV; −1.51 eV needs 12.09 eV, too much. (b) 11.0 − 10.2 = 0.8 eV. (c) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (10.2 × 1.60 × 10⁻¹⁹) = 1.219 × 10⁻⁷ m. In nm: 1.219 × 10⁻⁷ × 10⁹ = 122. Mark scheme (6 marks). C1: electron energy 11.0 eV. B1: only n = 2 reachable. C1: energy kept. M1: λ = hc/ΔE. C1: value. A1: λ = 122 nm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 280" role="img" aria-labelledby="fg775a4e9c-t fg775a4e9c-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg775a4e9c-t">Hydrogen energy levels</title><desc id="fg775a4e9c-d">Energy level diagram for hydrogen showing the ground state at −13.6 eV and the levels at −3.40 eV and −1.51 eV.</desc><line x1="110" y1="258" x2="290" y2="258" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="258" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><text x="298" y="258" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−13.6 eV</text><line x1="110" y1="77.5" x2="290" y2="77.5" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="77.5" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><text x="298" y="77.5" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.40 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−1.51 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="266" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen showing the ground state at −13.6 eV and the levels at −3.40 eV and −1.51 eV.'),
('cba8b3d3-3a77-56ba-a024-8767b2992f23', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 46, 46, 'A photon of energy 15.0 eV is absorbed by a hydrogen atom in its ground state (−13.6 eV). (a) Explain why the atom is ionised. (b) Calculate the kinetic energy of the freed electron in eV. (c) Calculate its speed. Give only the answer to (c), in units of 10⁵ m s⁻¹. Take e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg.', NULL, 3, 'numeric'::answer_type, '7.013', '10⁵ m s⁻¹', false, NULL, false, NULL, '(a) 15.0 eV exceeds the ionisation energy, 13.6 eV. (b) Ek = 15.0 − 13.6 = 1.4 eV. (c) v = √(2 × 1.4 × 1.60 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹) = 7.01 × 10⁵ m s⁻¹. Mark scheme (5 marks). B1: above ionisation energy. C1: Ek. C1: eV to J. C1: v = √(2Ek/m). A1: v = 7.01 × 10⁵ m s⁻¹.', 5, NULL, NULL),
('1f3968f8-0578-50a4-811e-0b4422ca87f7', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 47, 47, 'Hydrogen atoms are excited to the −0.54 eV level (n = 5). (a) State how many different lines can be emitted as the atoms return to the ground state. (b) Calculate the photon energy for the 5 → 1 transition. (c) Calculate its wavelength in nm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '95.19 nm', 'nm', false, NULL, false, NULL, '(a) 4 + 3 + 2 + 1 = 10 lines. (b) 13.6 − 0.54 = 13.06 eV. (c) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (13.06 × 1.60 × 10⁻¹⁹) = 9.519 × 10⁻⁸ m. In nm: 9.519 × 10⁻⁸ × 10⁹ = 95.2. Mark scheme (6 marks). B1: ten lines. C1: energy gap. M1: λ = hc/ΔE. C1: J conversion. C1: value. A1: λ = 95.2 nm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 304.1" role="img" aria-labelledby="fg7e9c48ce-t fg7e9c48ce-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg7e9c48ce-t">Hydrogen energy levels</title><desc id="fg7e9c48ce-d">Energy level diagram for hydrogen (n = 1 to 5) with an arrow from the −0.54 eV level (n = 5) down to the ground state.</desc><line x1="110" y1="282.1" x2="290" y2="282.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="282.1" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 1</text><line x1="110" y1="115" x2="290" y2="115" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="115" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 2</text><line x1="110" y1="84" x2="290" y2="84" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="84" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 3</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="64" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 4</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="44" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">n = 5</text><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−0.54 eV</text><line x1="200" y1="44" x2="200" y2="275.8" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,282.1 196.2,273.9 203.8,273.9" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="290.1" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for hydrogen (n = 1 to 5) with an arrow from the −0.54 eV level (n = 5) down to the ground state.'),
('887bf5db-44fb-5285-8a71-821ac38bcbb0', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 48, 48, 'In a helium–neon laser the light comes from a transition in neon between levels 20.66 eV and 18.70 eV above the ground state. (a) Calculate the photon energy. (b) Calculate the wavelength in nm. Give only the answer to (b). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '634.2 nm', 'nm', false, NULL, false, NULL, '(a) 20.66 − 18.70 = 1.96 eV. (b) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (1.96 × 1.60 × 10⁻¹⁹) = 6.342 × 10⁻⁷ m. In nm: 6.342 × 10⁻⁷ × 10⁹ = 634. Mark scheme (5 marks). C1: energy difference. M1: λ = hc/E. C1: conversion. C1: value. A1: λ = 634 nm.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 243.5" role="img" aria-labelledby="fg94199b9f-t fg94199b9f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg94199b9f-t">Neon laser levels</title><desc id="fg94199b9f-d">Energy level diagram for neon: the ground state and two excited levels at 18.70 eV and 20.66 eV above it, with the laser transition from 20.66 eV down to 18.70 eV.</desc><line x1="110" y1="221.5" x2="290" y2="221.5" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="102" y="221.5" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">ground state</text><line x1="110" y1="64" x2="290" y2="64" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="64" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">18.70 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">20.66 eV</text><line x1="200" y1="44" x2="200" y2="57.7" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,64 196.2,55.8 203.8,55.8" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="229.5" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram for neon: the ground state and two excited levels at 18.70 eV and 20.66 eV above it, with the laser transition from 20.66 eV down to 18.70 eV.'),
('16c582e1-8240-59d0-a2d7-229539378b87', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 49, 49, 'The spectrum of a star shows a dark line at 656 nm. (a) Calculate the energy of photons of this wavelength in eV. (b) Hydrogen has levels at −1.51 eV and −3.40 eV. Show that this line could be due to hydrogen. (c) Explain why the line is dark. Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '1.895', 'eV', false, NULL, false, NULL, '(a) E = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (656 × 10⁻⁹ × 1.60 × 10⁻¹⁹) = 1.90 eV. (b) 3.40 − 1.51 = 1.89 eV, a match. (c) Hydrogen in the cooler outer layers absorbs these photons and re-emits them in all directions. Mark scheme (5 marks). C1: photon energy. C1: gap = 1.89 eV. B1: match. B1: absorption and re-emission in all directions. A1: E = 1.90 eV.', 5, NULL, NULL),
('b31ef9fe-5d17-53e1-a3b1-47050218653f', '7d22edfc-44c4-4846-9769-292936cb7827', '9aa7e25f-8f21-5c29-8c21-0ab595acb86b', 'a-level', '28.6', '9702 coursebook 28.6 · Energy levels and line spectra', 50, 50, 'An atom has levels at −9.0 eV (ground), −5.2 eV and −3.1 eV. An electron with 4.5 eV of kinetic energy collides with the atom in its ground state. (a) Show that it can excite the atom to −5.2 eV but not to −3.1 eV. (b) Calculate the kinetic energy the electron keeps. (c) Calculate the wavelength emitted when the atom returns to its ground state, in nm. Give only the answer to (c). Take h = 6.63 × 10⁻³⁴ J s, c = 3.00 × 10⁸ m s⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '327.1 nm', 'nm', false, NULL, false, NULL, '(a) −5.2 needs 3.8 eV ≤ 4.5 eV; −3.1 needs 5.9 eV. (b) 4.5 − 3.8 = 0.7 eV. (c) λ = 6.63 × 10⁻³⁴ × 3.00 × 10⁸ ÷ (3.8 × 1.60 × 10⁻¹⁹) = 3.271 × 10⁻⁷ m. In nm: 3.271 × 10⁻⁷ × 10⁹ = 327. Mark scheme (6 marks). C1: energies needed. B1: comparison. C1: energy kept. M1: λ = hc/ΔE. C1: value. A1: λ = 327 nm.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 260" role="img" aria-labelledby="fg3c22b84b-t fg3c22b84b-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3c22b84b-t">Energy levels of an atom</title><desc id="fg3c22b84b-d">Energy level diagram of an atom with its ground state at −9.0 eV and excited levels at −5.2 eV and −3.1 eV.</desc><line x1="110" y1="238" x2="290" y2="238" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="238" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−9.0 eV</text><line x1="110" y1="113.1" x2="290" y2="113.1" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="113.1" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−5.2 eV</text><line x1="110" y1="44" x2="290" y2="44" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="298" y="44" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">−3.1 eV</text><text x="14" y="12" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">energy / eV</text><line x1="14" y1="246" x2="14" y2="24" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="14,20 17,26.3 11,26.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/></svg>', 'Energy level diagram of an atom with its ground state at −9.0 eV and excited levels at −5.2 eV and −3.1 eV.')
INSERT INTO problem_options (id, problem_id, option_text, option_letter, is_correct, "order") VALUES
('ecc70b15-6bf5-548b-8e77-5fcf0c9683a5', 'c89cb40f-5666-5813-863a-ab55083f4dc8', 'Its highest energy level', 'A', false, 0),
('0c73a76d-f13d-5802-ae87-08a9da9bb850', 'c89cb40f-5666-5813-863a-ab55083f4dc8', 'The level at 0 eV', 'B', false, 1),
('0dead748-d023-5a10-b6da-414d1ad87f25', 'c89cb40f-5666-5813-863a-ab55083f4dc8', 'Its lowest possible energy level', 'C', true, 2),
('3f446a7e-ec6b-558c-8c48-db0d53289e02', 'c89cb40f-5666-5813-863a-ab55083f4dc8', 'The state after ionisation', 'D', false, 3),
('8ebf585c-5045-5995-b369-ad8b922288d8', '4efb91bb-7f3c-57d3-a650-1a1670be43e8', 'An electron drops to a lower energy level and emits a photon of that energy difference', 'A', true, 0),
('6ab8065c-bb6b-5afa-b746-2f67edb2938a', '4efb91bb-7f3c-57d3-a650-1a1670be43e8', 'An electron absorbs a photon and rises to a higher level', 'B', false, 1),
('b1238a8d-6634-5c4f-b6b4-509cd07b70b3', '4efb91bb-7f3c-57d3-a650-1a1670be43e8', 'The atom is ionised', 'C', false, 2),
('af40190b-d16d-5311-bdc0-fed315e83c39', '4efb91bb-7f3c-57d3-a650-1a1670be43e8', 'The nucleus emits a photon', 'D', false, 3),
('a57ca244-1147-53c6-8090-60c8541688f5', 'e164541f-8786-5a90-8637-1402683adb88', 'Atoms emit extra photons at those wavelengths', 'A', false, 0),
('02aa9b54-8d8c-501b-8e18-f75eba7ed371', 'e164541f-8786-5a90-8637-1402683adb88', 'The light is reflected at those wavelengths', 'B', false, 1),
('50466863-631d-5ddb-8c4b-546d1654cfc3', 'e164541f-8786-5a90-8637-1402683adb88', 'Dust blocks those wavelengths', 'C', false, 2),
('a7a74303-1939-5658-8576-b18108caf38e', 'e164541f-8786-5a90-8637-1402683adb88', 'Atoms absorb photons whose energies match the gaps between their levels', 'D', true, 3),
('d78a8fd1-1092-5d62-883b-5db5474e5a66', '570c2511-815e-596a-a0e8-32f2797c1b03', 'An electron is removed from the atom', 'A', false, 0),
('144f39c5-4ebf-58a5-bb32-8b7e0d2136d2', '570c2511-815e-596a-a0e8-32f2797c1b03', 'An electron is raised to a higher energy level within the atom', 'B', true, 1),
('48307ed9-8bef-5608-af6a-fe65de50ba45', '570c2511-815e-596a-a0e8-32f2797c1b03', 'The atom gains a proton', 'C', false, 2),
('a99a5f08-9922-56bd-ba27-2dc0448fab00', '570c2511-815e-596a-a0e8-32f2797c1b03', 'The atom emits a photon', 'D', false, 3),
('ed4be872-d632-5896-9839-6e4da7ab26ea', '4bb2bf89-d3ab-5a42-83c4-a10a17bd8f4c', 'The ground state', 'A', false, 0),
('f2bedb17-b071-5531-8968-75e8e614f7bf', '4bb2bf89-d3ab-5a42-83c4-a10a17bd8f4c', 'The nucleus', 'B', false, 1),
('8eb726a0-db9b-51cd-a497-2d7ad7425a1c', '4bb2bf89-d3ab-5a42-83c4-a10a17bd8f4c', 'The electron has just been freed from the atom', 'C', true, 2),
('2363a094-e4e6-513e-8b3e-69c73792b645', '4bb2bf89-d3ab-5a42-83c4-a10a17bd8f4c', 'The first excited state', 'D', false, 3),
('361badac-5699-5417-afbd-4b2052020bc9', '14b9a61a-50dc-5c2b-8fb3-0f89a3f76737', 'The one with the largest energy difference', 'A', true, 0),
('9b1d1589-8ff5-5428-9ba2-62799cf97717', '14b9a61a-50dc-5c2b-8fb3-0f89a3f76737', 'The one with the smallest energy difference', 'B', false, 1),
('2624a795-81ae-565b-ad41-3dee828b35df', '14b9a61a-50dc-5c2b-8fb3-0f89a3f76737', 'The one ending in the highest level', 'C', false, 2),
('ce2199b0-62ac-5951-a090-39181f259eea', '14b9a61a-50dc-5c2b-8fb3-0f89a3f76737', 'All transitions give the same wavelength', 'D', false, 3),
('c0f76498-fbda-5433-a8cd-2f26c2897a46', 'bc6cc9f0-87bc-549d-a9d0-5ad4ffb5f5ac', 'The energy of the ground state photon', 'A', false, 0),
('7bb899ef-55cf-56d4-b907-8aef4687c0d6', 'bc6cc9f0-87bc-549d-a9d0-5ad4ffb5f5ac', 'The energy to move an electron up one level', 'B', false, 1),
('1fe43bb2-53cd-5601-9a0c-2f9b07ba60eb', 'bc6cc9f0-87bc-549d-a9d0-5ad4ffb5f5ac', 'The energy of the emitted line', 'C', false, 2),
('bd895d73-2fd6-56fd-818d-e0cc4cb54fc7', 'bc6cc9f0-87bc-549d-a9d0-5ad4ffb5f5ac', 'The energy needed to remove an electron completely from the ground state', 'D', true, 3),
('ed901a01-e4a9-5c4b-9ec0-f02f7349ec31', 'de3c399c-be1b-5d07-b6f3-b7a0956eb071', 'Whenever its energy is greater than any energy gap', 'A', false, 0),
('6dabd6d1-57e8-592f-95b6-1800a5d6a78a', 'de3c399c-be1b-5d07-b6f3-b7a0956eb071', 'Only when its energy exactly matches the energy gap to a higher level (or exceeds the ionisation energy)', 'B', true, 1),
('f95d475d-86dc-53b1-b84d-64bc042133fe', 'de3c399c-be1b-5d07-b6f3-b7a0956eb071', 'Always', 'C', false, 2),
('f6f0c748-332b-5e0e-833f-78b9f6d6fc9c', 'de3c399c-be1b-5d07-b6f3-b7a0956eb071', 'Never', 'D', false, 3),
